// Sinh bởi chung/tools/tao-tu-dien-han.mjs từ dữ liệu của kho. Không sửa tay.
window.HAN_CAU=[["像","(tượng","giống, mô phỏng): Dịch là một hệ mô hình của thế giới."],["利用獄","Lợi dụng ngục.","Nên dùng đến pháp luật, hình phạt."],["利艱貞","Lợi gian trinh.","Giữ chính trong gian nan thì lợi."],["坎陷也","khảm hãm dã","hãm, sâu"],["小事吉","Tiểu sự cát.","Việc nhỏ thì tốt."],["棟橈凶","Đống nạo, hung.","Xà nóc cong oằn vì chịu quá nặng, xấu."],["離麗也","ly lệ dã","bám, nương tựa"],["上六引兌","Thượng lục: Dẫn đoài.","Dẫn dụ người khác vào niềm vui."],["九二悔亡","Cửu nhị: Hối vong.","Hối hận mất."],["九二貞吉","Cửu nhị: Trinh cát.","Giữ chính thì tốt."],["亢龍有悔","Kháng long, hữu hối.","Rồng bay lên quá cao, có hối hận."],["兌亨利貞","Đoài: Hanh, lợi trinh.","Đoài: hanh thông, lợi về chính bền."],["六三包羞","Lục tam: Bao tu.","Ôm điều xấu hổ."],["初六无咎","Sơ lục: Vô cữu.","Không lỗi."],["初吉終亂","Sơ cát chung loạn.","Lúc đầu tốt, cuối cùng rối loạn, nếu không phòng."],["嘉遯貞吉","Gia độn, trinh cát.","Lui một cách đẹp; giữ chính thì tốt."],["大壯利貞","Đại Tráng: Lợi trinh.","Đại Tráng: lợi về chính bền."],["大往小來","Đại vãng tiểu lai.","Cái lớn đi, cái nhỏ đến."],["大有元亨","Đại Hữu: Nguyên hanh.","Đại Hữu: rất hanh thông."],["已日乃孚","Dĩ nhật nãi phu.","Đến đúng ngày, việc đổi mới được người tin."],["往蹇來譽","Vãng kiển, lai dự.","Đi tới thì gặp khó, quay lại thì được khen."],["明兩作離","minh lưỡng tác ly","hai vầng sáng nối nhau, đó là Ly"],["潛龍勿用","Tiềm long vật dụng.","Rồng còn ẩn dưới nước, chưa phải lúc dùng."],["睽小事吉","Khuê: Tiểu sự cát.","Khuê: việc nhỏ thì tốt."],["鼎元吉亨","Đỉnh: Nguyên cát, hanh.","Đỉnh: rất tốt, hanh thông."],["上九敦艮吉","Thượng cửu: Đôn cấn, cát.","Dừng một cách đôn hậu, tốt."],["上六震恆凶","Thượng lục: Chấn hằng, hung.","Động mãi không yên mà cho là bền, xấu."],["九三升虛邑","Cửu tam: Thăng hư ấp.","Lên như vào ấp không người."],["九三棟橈凶","Cửu tam: Đống nạo, hung.","Xà nóc cong oằn, xấu."],["九三頻巽吝","Cửu tam: Tần tốn, lận.","Khiêm thuận một cách gượng ép nhiều lần, đáng tiếc."],["九二牽復吉","Cửu nhị: Khiên phục, cát.","Dắt nhau trở về, tốt."],["九二輿說輹","Cửu nhị: Dư thoát phúc.","Xe tháo nan bánh (tự dừng)."],["九五訟元吉","Cửu ngũ: Tụng, nguyên cát.","Xử kiện (công minh), rất tốt."],["九四田无禽","Cửu tứ: Điền vô cầm.","Đi săn mà không có thú."],["九四震遂泥","Cửu tứ: Chấn toại nê.","Sấm sa vào bùn."],["乾元亨利貞","Càn: Nguyên, hanh, lợi, trinh.","Càn: khởi đầu lớn lao, hanh thông, thuận lợi, chính bền."],["二簋可用享","Nhị quỹ khả dụng hưởng.","Hai bát cơm cũng đủ dâng cúng: ít mà thành thì vẫn trọn lễ."],["六三來兌凶","Lục tam: Lai đoài, hung.","Đến tìm niềm vui (chạy theo, nịnh bợ), xấu."],["六二休復吉","Lục nhị: Hưu phục, cát.","Quay về một cách tốt đẹp, tốt."],["六二賁其須","Lục nhị: Bí kỳ tu.","Trang sức bộ râu."],["六五童蒙吉","Lục ngũ: Đồng mông, cát.","Trẻ thơ dại, tốt."],["六四困蒙吝","Lục tứ: Khốn mông, lận.","Bị vây trong tối tăm, đáng tiếc."],["六四安節亨","Lục tứ: An tiết, hanh.","Yên với sự tiết chế, hanh thông."],["其用柔中也","kỳ dụng nhu trung dã","cái dùng của nó là mềm mà ở giữa"],["初九和兌吉","Sơ cửu: Hòa đoài, cát.","Vui vẻ hòa nhã, tốt."],["初六咸其拇","Sơ lục: Hàm kỳ mẫu.","Cảm ở ngón chân cái."],["初六鳴豫凶","Sơ lục: Minh dự, hung.","Vui đến kêu vang lên, xấu."],["匪其尫无咎","Phỉ kỳ bàng, vô cữu.","Không phô trương sự đầy thịnh, không lỗi."],["同人于宗吝","Đồng nhân vu tông, lận.","Chỉ hòa với người trong họ hàng, đáng tiếc."],["女歸吉利貞","Nữ quy cát, lợi trinh.","Con gái về nhà chồng đúng lễ thì tốt; giữ chính thì lợi."],["家人利女貞","Gia Nhân: Lợi nữ trinh.","Gia Nhân: lợi về sự chính bền của người nữ."],["小亨旅貞吉","Tiểu hanh, lữ trinh cát.","Thông ở việc nhỏ; người đi xa giữ chính thì tốt."],["履霜堅冰至","lý sương kiên băng chí","giẫm sương biết băng sắp tới."],["征凶无攸利","Chinh hung, vô du lợi.","Vội vàng đi tới thì xấu, không có lợi gì."],["明夷利艱貞","Minh Di: Lợi gian trinh.","Minh Di: lợi giữ chính trong gian nan."],["有攸往夙吉","Hữu du vãng, túc cát.","Còn việc phải làm thì làm sớm mới tốt."],["渙其群元吉","Hoán kỳ quần, nguyên cát.","Làm tan bè phái nhỏ, rất tốt; tan rồi mới tụ lại được thành lớn."],["物不可以終","vật bất khả dĩ chung","“vật không thể mãi …”:"],["用六利永貞","Dụng lục: Lợi vĩnh trinh.","Lợi về chính bền lâu dài."],["盈不可久也","doanh bất khả cửu dã","đầy thì không lâu được."],["苦節不可貞","Khổ tiết bất khả trinh.","Tiết chế đến mức khắc khổ thì không thể giữ lâu."],["遯亨小利貞","Độn: Hanh, tiểu lợi trinh.","Độn: hanh thông; lợi nhỏ về chính bền."],["陷必有所麗","hãm tất hữu sở lệ","đã hãm ắt cần chỗ bám"],["上九亢龍有悔","Thượng cửu: Kháng long, hữu hối.","Rồng bay lên quá cao, có hối hận."],["上九白賁无咎","Thượng cửu: Bạch bí, vô cữu.","Trang sức bằng màu trắng, không lỗi."],["上六濡其首厲","Thượng lục: Nhu kỳ thủ, lệ.","Ướt cả đầu, nguy."],["九三往蹇來反","Cửu tam: Vãng kiển lai phản.","Đi thì gặp khó, nên quay trở lại."],["九五嘉遯貞吉","Cửu ngũ: Gia độn, trinh cát.","Lui một cách tốt đẹp, giữ chính thì tốt."],["九五大蹇朋來","Cửu ngũ: Đại kiển bằng lai.","Gian nan lớn, bạn bè kéo đến."],["九五夬履貞厲","Cửu ngũ: Quải lý, trinh lệ.","Bước đi quyết đoán, cố giữ thì nguy."],["九五孚于嘉吉","Cửu ngũ: Phu vu gia, cát.","Tin vào điều tốt đẹp, tốt."],["九四可貞无咎","Cửu tứ: Khả trinh, vô cữu.","Có thể giữ chính, không lỗi."],["九四大吉无咎","Cửu tứ: Đại cát, vô cữu.","Rất tốt thì mới không lỗi."],["二多譽四多懼","Nhị đa dự, tứ đa cụ.","Hào hai được khen nhiều, hào bốn lo sợ nhiều: cùng tài mà khác chỗ đứng."],["以斷天下之疑","dĩ đoán thiên hạ chi nghi","để quyết điều thiên hạ còn ngờ"],["六三剝之无咎","Lục tam: Bác chi, vô cữu.","Ở trong thời bác mà không lỗi."],["六三比之匪人","Lục tam: Tỷ chi phỉ nhân.","Gần gũi với kẻ không xứng đáng."],["六三眾允悔亡","Lục tam: Chúng doãn, hối vong.","Mọi người đều tin theo, hối mất."],["六二鳴謙貞吉","Lục nhị: Minh khiêm, trinh cát.","Đức khiêm vang ra ngoài, giữ chính thì tốt."],["六二黃離元吉","Lục nhị: Hoàng ly, nguyên cát.","Ánh sáng màu vàng, rất tốt."],["六五敦復无悔","Lục ngũ: Đôn phục, vô hối.","Quay về một cách đôn hậu, không hối."],["六五貞吉升階","Lục ngũ: Trinh cát, thăng giai.","Giữ chính thì tốt, lên từng bậc thềm."],["六五黃裳元吉","Lục ngũ: Hoàng thường, nguyên cát.","Xiêm màu vàng, rất tốt."],["六四中行獨復","Lục tứ: Trung hành độc phục.","Đi giữa bầy mà một mình quay về."],["六四井甃无咎","Lục tứ: Tỉnh trứu, vô cữu.","Xây thành giếng bằng gạch, không lỗi."],["六四富家大吉","Lục tứ: Phú gia, đại cát.","Làm giàu cho nhà, rất tốt."],["六四往蹇來連","Lục tứ: Vãng kiển lai liên.","Đi thì gặp khó, trở lại liên kết (với người dưới)."],["六四至臨无咎","Lục tứ: Chí lâm, vô cữu.","Đến gần tận nơi, không lỗi."],["初九咸臨貞吉","Sơ cửu: Hàm lâm, trinh cát.","Cảm hóa mà đến, giữ chính thì tốt."],["初九无妄往吉","Sơ cửu: Vô vọng, vãng cát.","Không càn bậy, đi thì tốt."],["初九有厲利已","Sơ cửu: Hữu lệ, lợi dĩ.","Có nguy, lợi ở việc dừng lại."],["初九潛龍勿用","Sơ cửu: Tiềm long, vật dụng.","Rồng còn ẩn dưới nước, chớ dùng."],["初六允升大吉","Sơ lục: Doãn thăng, đại cát.","Được tin cậy mà đi lên, rất tốt."],["初六往蹇來譽","Sơ lục: Vãng kiển, lai dự.","Đi thì gặp khó, trở lại thì được khen."],["初六濡其尾吝","Sơ lục: Nhu kỳ vĩ, lận.","Ướt đuôi, đáng tiếc."],["初六飛鳥以凶","Sơ lục: Phi điểu dĩ hung.","Chim bay (lên cao) nên bị xấu."],["剝不利有攸往","Bác: Bất lợi hữu du vãng.","Bác: không lợi khi có việc đi."],["咸其腓凶居吉","Hàm kỳ phì, hung, cư cát.","Cảm ở bắp chân, chạy theo thì xấu; ở yên thì tốt."],["噬嗑亨利用獄","Phệ Hạp: Hanh, lợi dụng ngục.","Phệ Hạp: hanh thông, lợi dùng việc hình ngục."],["女壯勿用取女","Nữ tráng, vật dụng thủ nữ.","Người con gái quá mạnh, lấn lướt, thì chớ lấy làm vợ."],["屨校滅趾无咎","Lũ giảo diệt chỉ, vô cữu.","Đeo cùm ở chân, mất ngón chân; không lỗi."],["括囊无咎无譽","Quát nang, vô cữu vô dự.","Thắt miệng túi lại: không lỗi, cũng không được khen."],["旅小亨旅貞吉","Lữ: Tiểu hanh, lữ trinh cát.","Lữ: hanh thông nhỏ; người đi xa giữ chính thì tốt."],["有孚光亨貞吉","Hữu phu, quang hanh. Trinh cát.","Có lòng tin thì sáng và thông; giữ chính thì tốt."],["漸女歸吉利貞","Tiệm: Nữ quy cát, lợi trinh.","Tiệm: con gái về nhà chồng thì tốt, lợi về chính bền."],["觀頤自求口實","Quan di, tự cầu khẩu thực.","Xem cách nuôi dưỡng, và tự tìm miếng ăn cho mình."],["謙亨君子有終","Khiêm: Hanh, quân tử hữu chung.","Khiêm: hanh thông, người quân tử có kết quả tốt đẹp đến cuối."],["豫利建侯行師","Dự: Lợi kiến hầu hành sư.","Dự: lợi về việc dựng tước hầu và ra quân."],["重明以麗乎正","trọng minh dĩ lệ hồ chính","Thoán Ly)"],["需于泥致寇至","Nhu vu nê, trí khấu chí.","Đợi ở bùn lầy, tự rước giặc đến."],["一陰一陽之謂道","nhất âm nhất dương chi vị đạo","một âm một dương gọi là đạo"],["上九何天之衢亨","Thượng cửu: Hà thiên chi cù, hanh.","Gánh lấy (đi trên) con đường lớn của trời, hanh thông."],["上九何校滅耳凶","Thượng cửu: Hà giảo diệt nhĩ, hung.","Mang gông ở cổ, ngập mất tai, xấu."],["上九肥遯无不利","Thượng cửu: Phì độn, vô bất lợi.","Lui ung dung thong thả, không gì không lợi."],["上六咸其輔頰舌","Thượng lục: Hàm kỳ phụ, giáp, thiệt.","Cảm ở hàm, má, lưỡi."],["上六敦臨吉无咎","Thượng lục: Đôn lâm, cát vô cữu.","Lấy lòng đôn hậu mà đến gần, tốt, không lỗi."],["上六无號終有凶","Thượng lục: Vô hào, chung hữu hung.","Không kêu than được nữa, cuối cùng có điều xấu."],["上六比之无首凶","Thượng lục: Tỷ chi vô thủ, hung.","Gần gũi mà không có đầu, xấu."],["九二不出門庭凶","Cửu nhị: Bất xuất môn đình, hung.","Không ra khỏi cổng sân, xấu."],["九二孚兌吉悔亡","Cửu nhị: Phu đoài, cát, hối vong.","Vui bằng lòng thành tín, tốt, hối mất."],["九二曳其輪貞吉","Cửu nhị: Duệ kỳ luân, trinh cát.","Kéo bánh xe lại, giữ chính thì tốt."],["九五井冽寒泉食","Cửu ngũ: Tỉnh liệt, hàn tuyền thực.","Giếng trong mát, nước suối lạnh được múc uống."],["九五咸其脢无悔","Cửu ngũ: Hàm kỳ mai, vô hối.","Cảm ở thịt sống lưng, không hối."],["九五孚于剝有厲","Cửu ngũ: Phu vu bác, hữu lệ.","Tin vào kẻ làm hại (tiểu nhân), có nguy."],["九四包无魚起凶","Cửu tứ: Bao vô ngư, khởi hung.","Trong bọc không có cá, dấy lên điều xấu."],["九四匪其尫无咎","Cửu tứ: Phỉ kỳ bàng, vô cữu.","Không phô trương sự đầy thịnh, không lỗi."],["六三師或輿尸凶","Lục tam: Sư hoặc dư thi, hung.","Quân có khi phải chở xác về, xấu."],["六三渙其躬无悔","Lục tam: Hoán kỳ cung, vô hối.","Làm tan cái riêng của bản thân, không hối."],["六三觀我生進退","Lục tam: Quan ngã sinh, tiến thoái.","Xem lại việc làm của chính mình để định tiến hay lui."],["六三頻復厲无咎","Lục tam: Tần phục, lệ vô cữu.","Quay về nhiều lần (lỡ rồi lại sửa), nguy nhưng không lỗi."],["六二同人于宗吝","Lục nhị: Đồng nhân vu tông, lận.","Chỉ hòa đồng trong họ hàng, đáng tiếc."],["六二窺觀利女貞","Lục nhị: Khuy quan, lợi nữ trinh.","Nhìn trộm qua khe cửa, lợi cho người con gái giữ chính."],["六五豶豕之牙吉","Lục ngũ: Phần thỉ chi nha, cát.","Răng của con heo đã thiến, tốt."],["六五貞疾恆不死","Lục ngũ: Trinh tật, hằng bất tử.","Bệnh lâu dài, nhưng luôn không chết."],["六四剝牀以膚凶","Lục tứ: Bác sàng dĩ phu, hung.","Gặm giường đến da thịt người nằm, xấu."],["六四外比之貞吉","Lục tứ: Ngoại tỷ chi, trinh cát.","Gần gũi ra bên ngoài (với người hiền ở trên), giữ chính thì tốt."],["六四師左次无咎","Lục tứ: Sư tả thứ, vô cữu.","Quân lui về đóng trại, không lỗi."],["六四无不利撝謙","Lục tứ: Vô bất lợi, huy khiêm.","Không gì không lợi, phát huy đức khiêm."],["六四艮其身无咎","Lục tứ: Cấn kỳ thân, vô cữu.","Dừng ở thân mình, không lỗi."],["初九素履往无咎","Sơ cửu: Tố lý, vãng vô cữu.","Bước đi giản dị mộc mạc, đi thì không lỗi."],["初九閑有家悔亡","Sơ cửu: Nhàn hữu gia, hối vong.","Phòng ngừa ngay từ lúc mới có nhà, hối mất."],["初六履霜堅冰至","Sơ lục: Lý sương, kiên băng chí.","Giẫm lên sương, biết rằng băng cứng sắp đến."],["利貞亨畜牝牛吉","lợi trinh hanh súc tẫn ngưu cát","lợi chính bền, hanh thông"],["勞謙君子有終吉","Lao khiêm quân tử, hữu chung cát.","Người quân tử có công mà khiêm, kết quả trọn vẹn, tốt."],["原筮元永貞无咎","Nguyên phệ nguyên vĩnh trinh, vô cữu.","Xét kỹ lại xem có đủ đức lớn, lâu dài, chính bền; như thế thì không lỗi."],["吉凶者貞勝者也","Cát hung giả, trinh thắng giả dã.","Tốt hay xấu, rốt cuộc cái chính bền sẽ thắng."],["君子以儉德辟難","quân tử dĩ kiệm đức tị nan","lấy đức tiết kiệm mà tránh nạn"],["君子以厚德載物","quân tử dĩ hậu đức tái vật","lấy đức dày mà chở vật"],["咸亨利貞取女吉","Hàm: Hanh, lợi trinh. Thủ nữ cát.","Hàm: hanh thông, lợi về chính bền. Lấy vợ thì tốt."],["壯于趾征凶有孚","Tráng vu chỉ, chinh hung, hữu phu.","Mạnh ở ngón chân mà đã đi thì xấu; điều ấy chắc chắn."],["姤女壯勿用取女","Cấu: Nữ tráng, vật dụng thủ nữ.","Cấu: người con gái mạnh mẽ (lấn lướt), chớ lấy làm vợ."],["師出以律否臧凶","Sư xuất dĩ luật, phủ tang, hung.","Ra quân phải theo kỷ luật; không giữ được kỷ luật thì xấu."],["師貞丈人吉无咎","Sư: Trinh, trượng nhân cát, vô cữu.","Sư: giữ chính; có bậc trưởng giả già dặn cầm quân thì tốt, không lỗi."],["歸妹征凶无攸利","Quy Muội: Chinh hung, vô du lợi.","Quy Muội: đi thì xấu, không có lợi gì."],["泰小往大來吉亨","Thái: Tiểu vãng đại lai, cát hanh.","Thái: cái nhỏ đi, cái lớn đến, tốt lành hanh thông."],["節亨苦節不可貞","Tiết: Hanh. Khổ tiết bất khả trinh.","Tiết: hanh thông. Tiết chế đến mức khắc khổ thì không thể giữ lâu."],["艮其背不獲其身","Cấn kỳ bối, bất hoạch kỳ thân.","Dừng ở lưng, không thấy thân mình: lòng yên, không bị kéo đi."],["賁亨小利有攸往","Bí: Hanh, tiểu lợi hữu du vãng.","Bí: hanh thông, lợi nhỏ khi có việc đi."],["車說輹夫妻反目","Dư thoát phúc, phu thê phản mục.","Xe tuột nan bánh, vợ chồng trợn mắt nhìn nhau."],["隨元亨利貞无咎","Tùy: Nguyên hanh, lợi trinh, vô cữu.","Tùy: rất hanh thông, lợi về chính bền, không lỗi."],["上九傾否先否後喜","Thượng cửu: Khuynh bĩ, tiên bĩ hậu hỉ.","Lật đổ bế tắc; trước tắc, sau vui."],["上九同人于郊無悔","Thượng cửu: Đồng nhân vu giao, vô hối.","Hòa đồng với người ở ngoài cõi xa, không hối."],["上九姤其角吝无咎","Thượng cửu: Cấu kỳ giác, lận, vô cữu.","Gặp ở chỗ sừng (cao cứng), đáng tiếc, không lỗi."],["上九有孚威如終吉","Thượng cửu: Hữu phu uy như, chung cát.","Có lòng thành và uy nghiêm, cuối cùng tốt."],["上六苦節貞凶悔亡","Thượng lục: Khổ tiết, trinh hung, hối vong.","Tiết chế khắc khổ, cố giữ thì xấu; (biết sửa) thì hối mất."],["上六齎資涕洟无咎","Thượng lục: Tê tư thế di, vô cữu.","Than thở, nước mắt nước mũi chảy ròng, không lỗi."],["不遠復无祇悔元吉","Bất viễn phục, vô kỳ hối, nguyên cát.","Đi chưa xa mà quay lại ngay, chưa đến nỗi phải hối; rất tốt."],["九三需于泥致寇至","Cửu tam: Nhu vu nê, trí khấu chí.","Chờ ở bùn lầy, tự rước giặc đến."],["九二咸臨吉无不利","Cửu nhị: Hàm lâm, cát vô bất lợi.","Cảm hóa mà đến, tốt, không gì không lợi."],["九二坎有險求小得","Cửu nhị: Khảm hữu hiểm, cầu tiểu đắc.","Ở trong hiểm còn có hiểm, cầu thì được chút ít."],["九二渙奔其机悔亡","Cửu nhị: Hoán bôn kỳ kỷ, hối vong.","Lúc ly tán chạy đến chỗ dựa của mình (cái ghế tựa), hối mất."],["九二遇主于巷无咎","Cửu nhị: Ngộ chủ vu hạng, vô cữu.","Gặp chủ ở ngõ hẻm, không lỗi."],["九五有孚攣如无咎","Cửu ngũ: Hữu phu luyến như, vô cữu.","Có lòng tin gắn kết chặt chẽ, không lỗi."],["九五甘節吉往有尚","Cửu ngũ: Cam tiết, cát; vãng hữu thượng.","Tiết chế một cách vui vẻ, tốt; đi thì được trọng."],["九五需于酒食貞吉","Cửu ngũ: Nhu vu tửu thực, trinh cát.","Chờ trong rượu và cơm, giữ chính thì tốt."],["九四或躍在淵无咎","Cửu tứ: Hoặc dược tại uyên, vô cữu.","Hoặc nhảy vọt lên, hoặc còn ở dưới vực; không lỗi."],["九四晉如鼫鼠貞厲","Cửu tứ: Tấn như thạch thử, trinh lệ.","Tiến lên như con chuột đồng, cố giữ thì nguy."],["九四棟隆吉有它吝","Cửu tứ: Đống long, cát. Hữu tha lận.","Xà nóc vồng lên vững, tốt. Nếu có lòng khác thì đáng tiếc."],["二人同心其利斷金","Nhị nhân đồng tâm, kỳ lợi đoạn kim.","Hai người cùng lòng, sức bén chặt được cả kim loại."],["人謀鬼謀百姓與能","nhân mưu quỷ mưu bách tính dữ năng","người mưu, quỷ thần mưu, dân thường cũng dự được"],["六三盱豫悔遲有悔","Lục tam: Hu dự, hối. Trì hữu hối.","Ngước nhìn (người trên) mà vui, có hối; chậm trễ cũng có hối."],["六二係小子失丈夫","Lục nhị: Hệ tiểu tử, thất trượng phu.","Buộc theo đứa trẻ con, mất người trượng phu."],["六二咸其腓凶居吉","Lục nhị: Hàm kỳ phì, hung, cư cát.","Cảm ở bắp chân, xấu; ở yên thì tốt."],["六二噬膚滅鼻无咎","Lục nhị: Phệ phu diệt tị, vô cữu.","Cắn vào thịt mềm, ngập mất mũi, không lỗi."],["六二比之自內貞吉","Lục nhị: Tỷ chi tự nội, trinh cát.","Gần gũi từ bên trong, giữ chính thì tốt."],["六五來章有慶譽吉","Lục ngũ: Lai chương, hữu khánh dự, cát.","Mời người có tài sáng đến, có phúc và tiếng khen, tốt."],["六五喪羊于易无悔","Lục ngũ: Táng dương vu dị, vô hối.","Mất dê ở bờ ruộng (dễ dàng), không hối."],["六五幹父之蠱用譽","Lục ngũ: Cán phụ chi cổ, dụng dự.","Sửa việc hỏng của cha, được tiếng khen."],["六四悔亡田獲三品","Lục tứ: Hối vong, điền hoạch tam phẩm.","Hối mất, đi săn được ba loại thú."],["六四括囊无咎无譽","Lục tứ: Quát nang, vô cữu vô dự.","Thắt miệng túi lại: không lỗi, cũng không được khen."],["六四童牛之告元吉","Lục tứ: Đồng ngưu chi cốc, nguyên cát.","Cây gác sừng của bò non, rất tốt."],["六四需于血出自穴","Lục tứ: Nhu vu huyết, xuất tự huyệt.","Chờ ở chỗ máu, ra khỏi hang."],["其亡其亡繫于包桑","Kỳ vong kỳ vong, hệ vu bao tang.","Luôn nghĩ sắp mất rồi, sắp mất rồi; như buộc vào gốc dâu cho vững."],["出涕沱若戚嗟若吉","Xuất thế đà nhược, thích ta nhược, cát.","Nước mắt tuôn rơi, lo buồn than thở; như thế là tốt."],["初九不出戶庭无咎","Sơ cửu: Bất xuất hộ đình, vô cữu.","Không ra khỏi cửa trong sân, không lỗi."],["初九同人于門無咎","Sơ cửu: Đồng nhân vu môn, vô cữu.","Hòa đồng với người ngay ở cửa, không lỗi."],["初九屨校滅趾无咎","Sơ cửu: Lũ giảo diệt chỉ, vô cữu.","Đeo cùm ở chân, mất ngón chân, không lỗi."],["初九虞吉有它不燕","Sơ cửu: Ngu cát, hữu tha bất yến.","Cân nhắc kỹ (người mình tin) thì tốt; có lòng khác thì không yên."],["初九鞏用黃牛之革","Sơ cửu: Củng dụng hoàng ngưu chi cách.","Buộc chặt bằng da bò vàng."],["初六藉用白茅无咎","Sơ lục: Tạ dụng bạch mao, vô cữu.","Lót bằng cỏ tranh trắng, không lỗi."],["密雲不雨自我西郊","Mật vân bất vũ, tự ngã tây giao.","Mây dày mà chưa mưa, kéo từ cõi tây của ta đến."],["尺蠖之屈以求信也","xích hoạch chi khuất dĩ cầu tín dã","con sâu đo co mình lại là để duỗi ra"],["履履虎尾不咥人亨","Lý hổ vĩ, bất điệt nhân, hanh.","Giẫm lên đuôi hổ, hổ không cắn người, hanh thông."],["復其見天地之心乎","phục kỳ kiến thiên địa chi tâm hồ","ở Phục thấy được lòng trời đất."],["損益盈虛與時偕行","tổn ích doanh hư dữ thời giai hành","bớt thêm đầy vơi, đi cùng thời"],["无平不陂无往不復","vô bình bất bí vô vãng bất phục","không chỗ bằng nào không nghiêng, không đi nào không trở lại"],["有孚惠心勿問元吉","Hữu phu huệ tâm, vật vấn nguyên cát.","Có lòng thành muốn làm ơn, không cần hỏi cũng rất tốt."],["有孚窒惕中吉終凶","Hữu phu, trất, dịch, trung cát, chung hung.","Có lòng thành mà bị ngăn lấp, nên lo sợ; dừng giữa chừng thì tốt, theo đến cùng thì xấu."],["有孚維心亨行有尚","Hữu phu, duy tâm hanh. Hành hữu thượng.","Có lòng tin, chỉ cái lòng ấy là thông; cứ đi thì được trọng."],["沖空卽起沖合卽開","xung không 卽 khởi xung hợp 卽 khai","xung hào không thì hào dậy, xung hào hợp thì hợp mở"],["用九見羣龍无首吉","Dụng cửu: Kiến quần long vô thủ, cát.","Thấy bầy rồng mà không con nào đứng đầu, tốt."],["甲子晉惠帝十四年","giáp tử tấn huệ đế thập tứ niên","năm Giáp Tý đời Tấn Huệ Đế thứ 14, tức năm 304."],["磐桓利居貞利建侯","Bàn hoàn, lợi cư trinh, lợi kiến hầu.","Còn quanh quẩn chưa đi được; nên ở yên giữ vững, nên gây dựng người giúp mình."],["觀乎天文以察時變","quan hồ thiên văn dĩ sát thời biến","xem văn của trời để xét sự đổi thay của thời"],["變動不居周流六虛","biến động bất cư chu lưu lục hư","biến động không ở yên, chảy khắp sáu chỗ trống"],["離利貞亨畜牝牛吉","Ly: Lợi trinh, hanh. Súc tẫn ngưu, cát.","Ly: lợi về chính bền, hanh thông. Nuôi bò cái thì tốt."],["雲雷屯君子以經綸","Vân lôi, Truân; quân tử dĩ kinh luân.","Mây và sấm là quẻ Truân; người quân tử noi đó mà sắp xếp, gây dựng việc lớn (như xe tơ dệt vải)."],["需于沙小有言終吉","Nhu vu sa, tiểu hữu ngôn, chung cát.","Đợi ở bãi cát, có chút lời ra tiếng vào; cuối cùng tốt."],["震來虩虩笑言啞啞","Chấn lai hích hích, tiếu ngôn ách ách.","Sấm đến làm sợ hãi rụt rè; rồi lại cười nói vui vẻ."],["鳴鶴在陰其子和之","Minh hạc tại âm, kỳ tử họa chi.","Hạc kêu trong bóng râm, hạc con họa theo."],["上九翰音登于天貞凶","Thượng cửu: Hàn âm đăng vu thiên, trinh hung.","Tiếng gà gáy bay lên trời, cố giữ thì xấu."],["上九觀其生君子无咎","Thượng cửu: Quan kỳ sinh, quân tử vô cữu.","Xem việc làm của mình (được người khác xem), người quân tử thì không lỗi."],["上六冥豫成有渝无咎","Thượng lục: Minh dự, thành hữu du, vô cữu.","Vui đến mê muội; việc đã thành mà biết đổi thì không lỗi."],["上六過涉滅頂凶无咎","Thượng lục: Quá thiệp diệt đính, hung, vô cữu.","Lội qua sông sâu ngập đầu, xấu, nhưng không có lỗi."],["九三勞謙君子有終吉","Cửu tam: Lao khiêm quân tử, hữu chung, cát.","Người quân tử có công lao mà khiêm, có kết quả trọn, tốt."],["九三賁如濡如永貞吉","Cửu tam: Bí như nhu như, vĩnh trinh cát.","Trang sức đẹp đẽ, thấm nhuần; giữ chính lâu dài thì tốt."],["九三車說輹夫妻反目","Cửu tam: Dư thoát phúc, phu thê phản mục.","Xe tuột nan bánh, vợ chồng trợn mắt nhìn nhau."],["九二井谷射鮒瓮敝漏","Cửu nhị: Tỉnh cốc xạ phụ, úng tệ lậu.","Nước giếng chỉ chảy xuống chỗ cá nhỏ, cái vò hỏng thủng."],["九二孚乃利用禴无咎","Cửu nhị: Phu nãi lợi dụng thược, vô cữu.","Có lòng thành thì lễ mọn cũng lợi dùng, không lỗi."],["九二幹母之蠱不可貞","Cửu nhị: Cán mẫu chi cổ, bất khả trinh.","Sửa việc hỏng của mẹ, không thể cứng nhắc."],["九五王假有家勿恤吉","Cửu ngũ: Vương cách hữu gia, vật tuất, cát.","Vua đến với nhà mình (lấy đạo cảm hóa cả nhà), chớ lo, tốt."],["九五觀我生君子无咎","Cửu ngũ: Quan ngã sinh, quân tử vô cữu.","Xem việc làm của mình, người quân tử thì không lỗi."],["九四乘其庸弗克攻吉","Cửu tứ: Thặng kỳ dung, phất khắc công, cát.","Cưỡi lên tường thành (định đánh) mà không đánh được, tốt."],["九四履虎尾愬愬終吉","Cửu tứ: Lý hổ vĩ, sóc sóc chung cát.","Giẫm đuôi hổ, sợ sệt dè dặt, cuối cùng tốt."],["九四悔亡有孚改命吉","Cửu tứ: Hối vong, hữu phu cải mệnh, cát.","Hối mất; có lòng thành mà đổi mệnh, tốt."],["九四有命无咎疇離祉","Cửu tứ: Hữu mệnh vô cữu, trù ly chỉ.","Có mệnh (trời, vua) thì không lỗi; bạn cùng loại đều được nhờ phúc."],["九四解而拇朋至斯孚","Cửu tứ: Giải nhi mẫu, bằng chí tư phu.","Cởi bỏ ngón chân cái của anh (kẻ bám theo), bạn bè đến mới tin."],["亢龍有悔盈不可久也","kháng long hữu hối doanh bất khả cửu dã","rồng quá cao có hối, vì đầy thì không lâu"],["六三震蘇蘇震行无眚","Lục tam: Chấn tô tô, chấn hành vô sảnh.","Sấm làm bàng hoàng mất hồn; nhân cơn chấn động mà đi (sửa đổi) thì không có họa."],["六二剝牀以辨蔑貞凶","Lục nhị: Bác sàng dĩ biện, miệt trinh, hung.","Gặm giường lên đến thành giường, hủy diệt điều chính, xấu."],["六五厥孚交如威如吉","Lục ngũ: Quyết phu giao như, uy như, cát.","Lấy lòng tin giao với người, lại có uy nghiêm, tốt."],["六五知臨大君之宜吉","Lục ngũ: Trí lâm, đại quân chi nghi, cát.","Lấy trí sáng suốt mà cai quản, là điều thích đáng của bậc vua lớn, tốt."],["六五箕子之明夷利貞","Lục ngũ: Cơ Tử chi minh di, lợi trinh.","Sự giấu sáng của Cơ Tử, lợi về chính bền."],["六五鼎黃耳金鉉利貞","Lục ngũ: Đỉnh hoàng nhĩ kim huyễn, lợi trinh.","Vạc có quai vàng, đòn khiêng bằng kim loại, lợi về chính bền."],["六四繻有衣袽終日戒","Lục tứ: Nhu hữu y như, chung nhật giới.","Thuyền rò có giẻ để bịt, suốt ngày đề phòng."],["六四裕父之蠱往見吝","Lục tứ: Dụ phụ chi cổ, vãng kiến lận.","Dung túng việc hỏng của cha, cứ đi như vậy thì thấy đáng tiếc."],["初九壯于趾征凶有孚","Sơ cửu: Tráng vu chỉ, chinh hung, hữu phu.","Mạnh ở ngón chân, đi thì xấu, chắc chắn như vậy."],["初九履錯然敬之无咎","Sơ cửu: Lý thác nhiên, kính chi vô cữu.","Bước đi lộn xộn (lúc mới bắt đầu), kính cẩn thì không lỗi."],["初九復自道何其咎吉","Sơ cửu: Phục tự đạo, hà kỳ cữu? Cát.","Trở về theo đường của mình, có lỗi gì đâu? Tốt."],["初九賁其趾舍車而徒","Sơ cửu: Bí kỳ chỉ, xả xa nhi đồ.","Trang sức ở ngón chân, bỏ xe mà đi bộ."],["初六剝牀以足蔑貞凶","Sơ lục: Bác sàng dĩ túc, miệt trinh, hung.","Gặm giường từ chân, hủy diệt điều chính, xấu."],["初六師出以律否臧凶","Sơ lục: Sư xuất dĩ luật, phủ tang hung.","Ra quân phải theo kỷ luật; không tốt (mất kỷ luật) thì xấu."],["初六浚恆貞凶无攸利","Sơ lục: Tuấn hằng, trinh hung, vô du lợi.","Đòi hỏi sự bền chặt sâu xa ngay từ đầu, cố giữ thì xấu, không lợi gì."],["初六用拯馬壯吉悔亡","Sơ lục: Dụng chửng mã tráng, cát.","Dùng ngựa khỏe để cứu, tốt."],["初六習坎入于坎窞凶","Sơ lục: Tập khảm, nhập vu khảm đạm, hung.","Hiểm chồng hiểm, sa vào đáy hố, xấu."],["初六進退利武人之貞","Sơ lục: Tiến thoái, lợi võ nhân chi trinh.","Tiến lui do dự, lợi ở sự chính bền của người võ."],["包蒙吉納婦吉子克家","Bao mông cát, nạp phụ cát, tử khắc gia.","Bao dung người còn tối, tốt; con sẽ gánh được việc nhà."],["匪我求童蒙童蒙求我","Phỉ ngã cầu đồng mông, đồng mông cầu ngã.","Không phải thầy đi tìm người học; người học phải tìm đến thầy."],["君子以思患而豫防之","quân tử dĩ tư hoạn nhi dự phòng chi","người quân tử nghĩ đến hoạn nạn mà phòng trước"],["大過棟橈利有攸往亨","Đại Quá: Đống nạo, lợi hữu du vãng, hanh.","Đại Quá: cây xà nóc cong oằn; lợi có việc đi, hanh thông."],["改邑不改井无喪无得","Cải ấp bất cải tỉnh, vô táng vô đắc.","Đổi làng mà không đổi giếng; giếng không mất không được, cứ nuôi người."],["有天地然後萬物生焉","hữu thiên địa nhiên hậu vạn vật sinh yên","Có trời đất rồi muôn vật mới sinh ra."],["益利有攸往利涉大川","Ích: Lợi hữu du vãng, lợi thiệp đại xuyên.","Ích: lợi có việc đi, lợi vượt sông lớn."],["神兆機於動動必有因","thần 兆 cơ ư động động tất hữu nhân","thần báo điềm ở chỗ động, động ắt có nguyên do"],["觀盥而不薦有孚顒若","Quan: Quán nhi bất tiến, hữu phu ngung nhược.","Quan: rửa tay (trước lễ) mà chưa dâng cúng, lòng thành kính nghiêm trang."],["豫必有隨故受之以隨","dự tất hữu tùy cố thụ chi dĩ tùy","Vui ắt có người theo, nên tiếp bằng Tùy."],["頤貞吉觀頤自求口實","Di: Trinh cát. Quan di, tự cầu khẩu thực.","Di: giữ chính thì tốt. Xem cách nuôi dưỡng, và xem cách tự tìm cái ăn cho miệng."],["上九不事王侯高尚其事","Thượng cửu: Bất sự vương hầu, cao thượng kỳ sự.","Không thờ vua chúa, giữ việc mình cao thượng."],["上九无妄行有眚无攸利","Thượng cửu: Vô vọng, hành hữu sảnh, vô du lợi.","Không càn bậy (mà vẫn) đi thì có họa, không có lợi gì."],["上九渙其血去逖出无咎","Thượng cửu: Hoán kỳ huyết, khứ địch xuất, vô cữu.","Làm tan sự thương tổn, rời xa và thoát ra, không lỗi."],["上九由頤厲吉利涉大川","Thượng cửu: Do di, lệ cát, lợi thiệp đại xuyên.","Mọi sự nuôi dưỡng đều do mình; biết nguy thì tốt, lợi vượt sông lớn."],["上九自天佑之吉无不利","Thượng cửu: Tự thiên hựu chi, cát vô bất lợi.","Từ trời giúp cho, tốt, không gì không lợi."],["上九視履考詳其旋元吉","Thượng cửu: Thị lý khảo tường, kỳ toàn nguyên cát.","Xem lại những bước đã đi, xét kỹ điềm lành dữ; trọn vẹn quay về thì rất tốt."],["上九鼎玉鉉大吉无不利","Thượng cửu: Đỉnh ngọc huyễn, đại cát, vô bất lợi.","Vạc có đòn khiêng bằng ngọc, rất tốt, không gì không lợi."],["上六乘馬班如泣血漣如","Thượng lục: Thặng mã ban như, khấp huyết liên như.","Cưỡi ngựa dùng dằng, khóc ra máu ròng ròng."],["上六井收勿幕有孚元吉","Thượng lục: Tỉnh thu vật mạc, hữu phu nguyên cát.","Giếng đã múc lên, đừng đậy lại; có lòng thành thì rất tốt."],["上六冥升利于不息之貞","Thượng lục: Minh thăng, lợi vu bất tức chi trinh.","Lên mãi trong mê muội; chỉ lợi khi giữ chính không ngừng."],["上六龍戰于野其血玄黃","Thượng lục: Long chiến vu dã, kỳ huyết huyền hoàng.","Rồng đánh nhau ngoài đồng, máu chảy đen vàng."],["不恆其德或承之羞貞吝","Bất hằng kỳ đức, hoặc thừa chi tu, trinh lận.","Không giữ bền đức của mình, có khi chuốc lấy hổ thẹn; cố giữ thì đáng tiếc."],["九三咸其股執其隨往吝","Cửu tam: Hàm kỳ cổ, chấp kỳ tùy, vãng lận.","Cảm ở bắp đùi, cứ khăng khăng chạy theo người, đi thì đáng tiếc."],["九二利貞征凶弗損益之","Cửu nhị: Lợi trinh, chinh hung, phất tổn ích chi.","Lợi giữ chính, đi thì xấu; không bớt mình mà vẫn làm ích được cho người."],["九二包有魚无咎不利賓","Cửu nhị: Bao hữu ngư, vô cữu, bất lợi tân.","Trong bọc có cá, không lỗi; không lợi để đãi khách."],["九二履道坦坦幽人貞吉","Cửu nhị: Lý đạo thản thản, u nhân trinh cát.","Con đường đi bằng phẳng, người ở ẩn giữ chính thì tốt."],["九二惕號莫夜有戎勿恤","Cửu nhị: Dịch hào, mộ dạ hữu nhung, vật tuất.","Cảnh giác mà hô hoán, đêm khuya có giặc cũng chớ lo."],["九二眇能視利幽人之貞","Cửu nhị: Diểu năng thị, lợi u nhân chi trinh.","Chột mà nhìn được, lợi cho người ở ẩn giữ chính."],["九二見龍在田利見大人","Cửu nhị: Hiện long tại điền, lợi kiến đại nhân.","Rồng hiện ra ở ruộng, lợi gặp bậc đại nhân."],["九二需于沙小有言終吉","Cửu nhị: Nhu vu sa, tiểu hữu ngôn, chung cát.","Chờ ở bãi cát; bị chút lời tiếng, cuối cùng tốt."],["九五坎不盈禔既平无咎","Cửu ngũ: Khảm bất doanh, chỉ ký bình, vô cữu.","Nước trong hố chưa đầy, nhưng đã đến mức bằng, không lỗi."],["九五大人虎變未占有孚","Cửu ngũ: Đại nhân hổ biến, vị chiêm hữu phu.","Bậc đại nhân biến đổi như con hổ (thay lông rực rỡ), chưa cần bói đã được tin."],["九五无妄之疾勿藥有喜","Cửu ngũ: Vô vọng chi tật, vật dược hữu hỉ.","Bệnh không do mình gây, đừng uống thuốc, sẽ có mừng."],["九五有孚攣如富以其鄰","Cửu ngũ: Hữu phu luyến như, phú dĩ kỳ lân.","Có lòng tin gắn bó, cùng giàu với láng giềng."],["九五莧陸夬夬中行无咎","Cửu ngũ: Hiện lục quải quải, trung hành vô cữu.","Rau sam (mềm, dễ sinh lại) phải quyết nhổ dứt khoát, theo đạo trung thì không lỗi."],["九五飛龍在天利見大人","Cửu ngũ: Phi long tại thiên, lợi kiến đại nhân.","Rồng bay trên trời, lợi gặp bậc đại nhân."],["九四商兌未寧介疾有喜","Cửu tứ: Thương đoài vị ninh, giới tật hữu hỉ.","Cân nhắc niềm vui (giữa đúng và sai) chưa yên; biết ngăn cách điều xấu thì có mừng."],["九四好遯君子吉小人否","Cửu tứ: Hiếu độn, quân tử cát, tiểu nhân bĩ.","Tuy có chỗ yêu mà vẫn lui; quân tử thì tốt, tiểu nhân thì không làm được."],["九四歸妹愆期遲歸有時","Cửu tứ: Quy muội khiên kỳ, trì quy hữu thời.","Em gái về nhà chồng lỡ hẹn, chậm lấy chồng là để đợi thời."],["六三不節若則嗟若无咎","Lục tam: Bất tiết nhược, tắc ta nhược, vô cữu.","Không biết tiết chế thì phải than thở; (tự mình gây ra) còn trách ai."],["六三未濟征凶利涉大川","Lục tam: Vị tế, chinh hung, lợi thiệp đại xuyên.","Chưa qua sông, đi (vội) thì xấu; (nhưng có sự giúp đỡ thì) lợi vượt sông lớn."],["六三歸妹以須反歸以娣","Lục tam: Quy muội dĩ tu, phản quy dĩ đệ.","Em gái về nhà chồng mà mong làm vợ cả, (rốt cuộc) quay về làm thiếp."],["六三負且乘致寇至貞吝","Lục tam: Phụ thả thặng, trí khấu chí, trinh lận.","Vừa đội đồ trên lưng vừa ngồi xe, gây cho giặc kéo đến; cố giữ thì đáng tiếc."],["六二介于石不終日貞吉","Lục nhị: Giới vu thạch, bất chung nhật, trinh cát.","Vững như đá, không đợi hết ngày (đã thấy cơ), giữ chính thì tốt."],["六二无攸遂在中饋貞吉","Lục nhị: Vô du toại, tại trung quỹ, trinh cát.","Không tự ý làm theo ý mình, lo việc bếp núc trong nhà, giữ chính thì tốt."],["六二王臣蹇蹇匪躬之故","Lục nhị: Vương thần kiển kiển, phỉ cung chi cố.","Bầy tôi của vua gặp gian nan chồng chất, không phải vì bản thân mình."],["六二直方大不習无不利","Lục nhị: Trực, phương, đại, bất tập vô bất lợi.","Thẳng, vuông, lớn; không cần tập luyện mà không gì không lợi."],["六五出涕沱若戚嗟若吉","Lục ngũ: Xuất thế đà nhược, thích ta nhược, cát.","Nước mắt tuôn rơi, lo buồn than thở, tốt."],["六五帝乙歸妹以祉元吉","Lục ngũ: Đế Ất quy muội, dĩ chỉ, nguyên cát.","Vua Đế Ất gả em gái, nhờ đó được phúc, rất tốt."],["六五艮其輔言有孚悔亡","Lục ngũ: Cấn kỳ phụ, ngôn hữu tự, hối vong.","Dừng ở hàm (giữ miệng), nói có thứ tự, hối mất."],["六四月既望馬匹亡无咎","Lục tứ: Nguyệt cơ vọng, mã thất vong, vô cữu.","Trăng gần rằm, ngựa mất bạn đôi, không lỗi."],["六四有孚血去惕出无咎","Lục tứ: Hữu phu, huyết khứ, dịch xuất, vô cữu.","Có lòng thành tín thì máu (tổn thương) đi, lo sợ hết, không lỗi."],["其匪正有眚不利有攸往","Kỳ phỉ chính hữu sảnh, bất lợi hữu du vãng.","Nếu không ngay thẳng thì có tai họa; đi tới không lợi."],["初九不遠復无祇悔元吉","Sơ cửu: Bất viễn phục, vô kỳ hối, nguyên cát.","Đi chưa xa đã quay lại, không đến nỗi hối, rất tốt."],["初九拔茅茹以其彙征吉","Sơ cửu: Bạt mao như dĩ kỳ vị, chinh cát.","Nhổ cỏ tranh thì cả chùm rễ liền nhau theo lên; cùng nhau tiến thì tốt."],["初九曳其輪濡其尾无咎","Sơ cửu: Duệ kỳ luân, nhu kỳ vĩ, vô cữu.","Kéo bánh xe lại, ướt đuôi (con cáo), không lỗi."],["初九磐桓利居貞利建侯","Sơ cửu: Bàn hoàn, lợi cư trinh, lợi kiến hầu.","Quanh quẩn chưa tiến được; lợi ở yên giữ chính, lợi dựng làm người giúp."],["初九需于郊利用恆无咎","Sơ cửu: Nhu vu giao, lợi dụng hằng, vô cữu.","Chờ ở ngoài đồng xa; lợi giữ bền như thường, không lỗi."],["初六井泥不食舊井无禽","Sơ lục: Tỉnh nê bất thực, cựu tỉnh vô cầm.","Giếng đầy bùn không ai uống, giếng cũ chim chóc cũng không đến."],["初六旅瑣瑣斯其所取災","Sơ lục: Lữ tỏa tỏa, tư kỳ sở thủ tai.","Người lữ khách nhỏ nhen vụn vặt, đó là tự chuốc lấy tai họa."],["初六艮其趾无咎利永貞","Sơ lục: Cấn kỳ chỉ, vô cữu, lợi vĩnh trinh.","Dừng ở ngón chân, không lỗi, lợi giữ chính lâu dài."],["初六遯尾厲勿用有攸往","Sơ lục: Độn vĩ, lệ, vật dụng hữu du vãng.","Lui ở đuôi, nguy; chớ có việc đi."],["初筮告再三瀆瀆則不告","sơ phệ cáo tái tam độc độc tắc bất cáo","bói lần đầu thì bảo, hỏi lại hai ba lần là nhờn, nhờn thì không bảo"],["吉凶悔吝者生乎動者也","cát hung hối lận giả sinh hồ động giả dã","cát hung hối lận sinh ra từ hành động (Hệ từ hạ)"],["君子尚消息盈虛天行也","quân tử thượng tiêu tức doanh hư thiên hành dã","quân tử coi trọng sự tiêu – tức – đầy – vơi, đó là vận hành của trời."],["君子藏器於身待時而動","Quân tử tàng khí ư thân, đãi thời nhi động.","Người quân tử giữ sẵn đồ nghề trong mình, đợi đúng lúc mới động."],["地勢坤君子以厚德載物","Địa thế khôn, quân tử dĩ hậu đức tải vật.","Thế đất thuận theo; người quân tử lấy đức dày mà chở muôn vật."],["天行健君子以自強不息","Thiên hành kiện, quân tử dĩ tự cường bất tức.","Trời vận hành mạnh mẽ; người quân tử noi theo mà tự cường không nghỉ."],["安而不忘危存而不忘亡","an nhi bất vong nguy tồn nhi bất vong vong","yên không quên nguy, còn không quên mất"],["寒往則暑來暑往則寒來","hàn vãng tắc thử lai thử vãng tắc hàn lai","lạnh đi thì nóng đến, nóng đi thì lạnh đến"],["小狐汔濟濡其尾无攸利","Tiểu hồ ngật tế, nhu kỳ vĩ, vô du lợi.","Con cáo nhỏ gần qua được sông thì ướt đuôi; không có lợi gì."],["恆亨无咎利貞利有攸往","Hằng: Hanh, vô cữu, lợi trinh, lợi hữu du vãng.","Hằng: hanh thông, không lỗi, lợi về chính bền, lợi có việc đi."],["既濟亨小利貞初吉終亂","Ký Tế: Hanh tiểu, lợi trinh. Sơ cát chung loạn.","Ký Tế: hanh thông ở việc nhỏ, lợi về chính bền. Lúc đầu tốt, cuối cùng rối loạn."],["易窮則變變則通通則久","Dịch cùng tắc biến, biến tắc thông, thông tắc cửu.","Đến cùng thì đổi, đổi thì thông, thông thì bền."],["洊雷震君子以恐懼修省","Tiến lôi, Chấn; quân tử dĩ khủng cụ tu tỉnh.","Sấm nổ liên tiếp là quẻ Chấn; người quân tử noi đó mà lo sợ, sửa mình và tự xét."],["節而信之故受之以中孚","tiết nhi tín chi cố thụ chi dĩ trung phu","Có mức mà người tin theo, nên tiếp bằng Trung Phu."],["緩必有所失故受之以損","hoãn tất hữu sở thất cố thụ chi dĩ tổn","Buông ra ắt có chỗ mất, nên tiếp bằng Tổn."],["羝羊觸藩不能退不能遂","Đê dương xúc phiên, bất năng thoái, bất năng toại.","Dê đực húc rào mắc sừng, không lùi được, không tiến được."],["習坎有孚維心亨行有尚","Tập Khảm: Hữu phu, duy tâm hanh, hành hữu thượng.","Tập Khảm (hiểm chồng hiểm): có lòng thành, chỉ có lòng là hanh thông; làm thì được tôn trọng (có công)."],["豐亨王假之勿憂宜日中","Phong: Hanh, vương cách chi, vật ưu, nghi nhật trung.","Phong: hanh thông, bậc vương mới đạt đến được; chớ lo, nên như mặt trời giữa trưa."],["貞大人吉无咎有言不信","Trinh đại nhân cát, vô cữu, hữu ngôn bất tín.","Người lớn giữ chính thì tốt, không lỗi; nhưng có nói cũng không ai tin."],["近而不相得則凶或害之","Cận nhi bất tương đắc, tắc hung hoặc hại chi.","Gần nhau mà không hợp nhau thì xấu, hoặc hại nhau."],["隨風巽君子以申命行事","Tùy phong, Tốn; quân tử dĩ thân mệnh hành sự.","Gió nối theo gió là quẻ Tốn; người quân tử noi đó mà nhắc lại mệnh lệnh, thi hành công việc."],["雷風恆君子以立不易方","Lôi phong, Hằng; quân tử dĩ lập bất dịch phương.","Sấm và gió là quẻ Hằng; người quân tử noi đó mà đứng vững, không đổi phương hướng."],["飲食必有訟故受之以訟","ẩm thực tất hữu tụng cố thụ chi dĩ tụng","Có ăn uống ắt có tranh chấp, nên tiếp bằng Tụng."],["麗澤兌君子以朋友講習","Lệ trạch, Đoài; quân tử dĩ bằng hữu giảng tập.","Hai đầm liền nhau là quẻ Đoài; người quân tử noi đó mà cùng bạn bè giảng giải, luyện tập."],["鼎折足覆公餗其刑渥凶","Đỉnh chiết túc, phúc công tốc, kỳ hình ốc, hung.","Vạc gãy chân, đổ cháo của vua, thân mình nhơ nhuốc; xấu."],["上九擊蒙不利為寇利禦寇","Thượng cửu: Kích mông, bất lợi vi khấu, lợi ngự khấu.","Đánh vào sự tối tăm; không lợi khi làm giặc, lợi khi chống giặc."],["上六往蹇來碩吉利見大人","Thượng lục: Vãng kiển lai thạc, cát; lợi kiến đại nhân.","Đi thì gặp khó, trở lại thì làm được việc lớn, tốt; lợi gặp bậc đại nhân."],["上六鳴謙利用行師征邑國","Thượng lục: Minh khiêm, lợi dụng hành sư, chinh ấp quốc.","Tiếng khiêm vang ra, lợi dùng quân để dẹp ấp nước của mình."],["上火下澤睽君子以同而異","Thượng hỏa hạ trạch, Khuê; quân tử dĩ đồng nhi dị.","Trên là lửa, dưới là đầm là quẻ Khuê; người quân tử noi đó mà đồng (với người ở chỗ chung) nhưng vẫn khác (giữ cái riêng đúng)."],["中孚豚魚吉利涉大川利貞","Trung Phu: Đồn ngư cát, lợi thiệp đại xuyên, lợi trinh.","Trung Phu: (lòng tin cảm đến cả) heo và cá thì tốt; lợi vượt sông lớn, lợi về chính bền."],["九三係遯有疾厲畜臣妾吉","Cửu tam: Hệ độn, hữu tật lệ; súc thần thiếp cát.","Muốn lui mà bị ràng buộc, có bệnh, nguy; nuôi bầy tôi, tì thiếp thì tốt."],["九三弗過防之從或戕之凶","Cửu tam: Phất quá phòng chi, tòng hoặc tường chi, hung.","Không đề phòng kỹ hơn mức, cứ theo (tiểu nhân) thì có kẻ hãm hại, xấu."],["九三艮其限裂其夤厲閽心","Cửu tam: Cấn kỳ hạn, liệt kỳ dần, lệ huân tâm.","Dừng ở ngang lưng, xé rách thịt sống lưng, nguy như lửa đốt lòng."],["九二包蒙吉納婦吉子克家","Cửu nhị: Bao mông, cát; nạp phụ, cát; tử khắc gia.","Bao dung kẻ tối tăm, tốt; lấy vợ, tốt; con gánh vác được việc nhà."],["九二大轝以載有攸往无咎","Cửu nhị: Đại dư dĩ tái, hữu du vãng, vô cữu.","Xe lớn để chở, có việc đi, không lỗi."],["九二田獲三狐得黃矢貞吉","Cửu nhị: Điền hoạch tam hồ, đắc hoàng thỉ, trinh cát.","Đi săn bắt được ba con cáo, được mũi tên vàng, giữ chính thì tốt."],["九五屯其膏小貞吉大貞凶","Cửu ngũ: Truân kỳ cao; tiểu trinh cát, đại trinh hung.","Ân trạch bị ách tắc; việc nhỏ giữ chính thì tốt, việc lớn cố giữ thì xấu."],["井道不可不革故受之以革","tỉnh đạo bất khả bất cách cố thụ chi dĩ cách","Đạo giếng không thể không đổi mới, nên tiếp bằng Cách."],["六三噬昔肉遇毒小吝无咎","Lục tam: Phệ tích nhục, ngộ độc; tiểu lận, vô cữu.","Cắn miếng thịt khô lâu năm, gặp độc; hơi đáng tiếc, không lỗi."],["六二包承小人吉大人否亨","Lục nhị: Bao thừa, tiểu nhân cát, đại nhân bĩ, hanh.","Ôm lòng chiều theo người trên: kẻ tiểu nhân thì tốt; đại nhân chịu bế tắc mà đạo lại hanh thông."],["六二婦喪其茀勿逐七日得","Lục nhị: Phụ táng kỳ phất, vật trục, thất nhật đắc.","Người đàn bà mất tấm rèm xe, chớ đuổi tìm, bảy ngày sẽ được."],["六二已日乃革之征吉无咎","Lục nhị: Dĩ nhật nãi cách chi, chinh cát, vô cữu.","Đến ngày thì thay đổi, đi thì tốt, không lỗi."],["六二引吉无咎孚乃利用禴","Lục nhị: Dẫn cát, vô cữu; phu nãi lợi dụng thược.","Được dẫn dắt (vào cuộc tụ họp) thì tốt, không lỗi; có lòng thành thì lễ mọn cũng lợi dùng."],["六二顛頤拂經于丘頤征凶","Lục nhị: Điên di, phất kinh, vu khâu di, chinh hung.","Ngược lại xin người dưới nuôi, trái lẽ thường; hoặc cầu người trên gò cao nuôi, đi thì xấu."],["六二鴻漸于磐飲食衎衎吉","Lục nhị: Hồng tiệm vu bàn, ẩm thực khản khản, cát.","Chim hồng tiến đến tảng đá lớn, ăn uống vui vẻ, tốt."],["六五射雉一矢亡終以譽命","Lục ngũ: Xạ trĩ, nhất thỉ vong, chung dĩ dự mệnh.","Bắn chim trĩ, mất một mũi tên, cuối cùng được tiếng khen và chức mệnh."],["六五悔亡厥宗噬膚往何咎","Lục ngũ: Hối vong, quyết tông phệ phu, vãng hà cữu.","Hối mất; người cùng tông (cửu nhị) gắn bó dễ như cắn vào thịt mềm, đi thì có lỗi gì."],["六五貫魚以宮人寵无不利","Lục ngũ: Quán ngư, dĩ cung nhân sủng, vô bất lợi.","Xâu cá thành chuỗi, dẫn các cung nhân đến được vua sủng ái; không gì không lợi."],["六五震往來厲億无喪有事","Lục ngũ: Chấn vãng lai lệ, ức vô táng, hữu sự.","Sấm đi rồi lại đến, nguy; liệu chừng không mất gì, vẫn giữ được việc của mình."],["六四損其疾使遄有喜无咎","Lục tứ: Tổn kỳ tật, sử thuyên hữu hỉ, vô cữu.","Bớt được bệnh của mình, khiến cho mau có mừng, không lỗi."],["六四王用享于岐山吉无咎","Lục tứ: Vương dụng hưởng vu Kỳ sơn, cát, vô cữu.","Vua dùng (người này) làm lễ tế ở núi Kỳ, tốt, không lỗi."],["六四觀國之光利用賓于王","Lục tứ: Quan quốc chi quang, lợi dụng tân vu vương.","Xem vẻ sáng của nước, lợi làm khách quý của vua."],["六爻不動則不變動則必變","lục hào bất động tắc bất biến động tắc tất biến","hào động (9 hoặc 6) biến ra hào khác, cả quái đổi theo"],["兼山艮君子以思不出其位","Kiêm sơn, Cấn; quân tử dĩ tư bất xuất kỳ vị.","Hai núi liền nhau là quẻ Cấn; người quân tử noi đó mà suy nghĩ không ra ngoài vị trí của mình."],["初九利用為大作元吉无咎","Sơ cửu: Lợi dụng vi đại tác, nguyên cát, vô cữu.","Lợi dùng để làm việc lớn; rất tốt thì mới không lỗi."],["初九壯于前趾往不勝為咎","Sơ cửu: Tráng vu tiền chỉ, vãng bất thắng vi cữu.","Mạnh ở ngón chân trước, đi mà không thắng là lỗi."],["初九无交害匪咎艱則无咎","Sơ cửu: Vô giao hại, phỉ cữu; gian tắc vô cữu.","Chưa dính líu đến điều hại, chẳng phải lỗi; biết gian nan mà giữ mình thì không lỗi."],["初九歸妹以娣跛能履征吉","Sơ cửu: Quy muội dĩ đệ, bả năng lý, chinh cát.","Em gái về nhà chồng làm thiếp, như người què mà đi được, đi thì tốt."],["初九祀事遄往无咎酌損之","Sơ cửu: Dĩ sự thuyên vãng, vô cữu, chước tổn chi.","Gác việc của mình mà nhanh chóng đi (giúp người), không lỗi; nhưng nên cân nhắc mà bớt."],["初九舍爾靈龜觀我朵頤凶","Sơ cửu: Xả nhĩ linh quy, quan ngã đóa di, hung.","Bỏ con rùa thiêng của mình, nhìn ta mà nhai trễ cả hàm (thèm thuồng), xấu."],["初六不永所事小有言終吉","Sơ lục: Bất vĩnh sở sự, tiểu hữu ngôn, chung cát.","Không theo đuổi lâu việc tranh chấp; có chút lời qua tiếng lại, cuối cùng tốt."],["初六拔茅茹以其彙貞吉亨","Sơ lục: Bạt mao như dĩ kỳ vị, trinh cát, hanh.","Nhổ cỏ tranh thì cả chùm rễ theo lên; giữ chính thì tốt, hanh thông."],["初六童觀小人无咎君子吝","Sơ lục: Đồng quan, tiểu nhân vô cữu, quân tử lận.","Xem như trẻ con: với kẻ tiểu nhân thì không lỗi, với quân tử thì đáng tiếc."],["初六謙謙君子用涉大川吉","Sơ lục: Khiêm khiêm quân tử, dụng thiệp đại xuyên, cát.","Người quân tử khiêm lại càng khiêm, dùng đức ấy mà vượt sông lớn, tốt."],["升而不已必困故受之以困","thăng nhi bất dĩ tất khốn cố thụ chi dĩ khốn","Lên mãi không ngừng thì ắt bí, nên tiếp bằng Khốn."],["小畜亨密雲不雨自我西郊","Tiểu Súc: Hanh. Mật vân bất vũ, tự ngã tây giao.","Tiểu Súc: hanh thông. Mây dày mà chưa mưa, mây từ cõi đồng phía tây của ta kéo đến."],["山上有澤咸君子以虛受人","Sơn thượng hữu trạch, Hàm; quân tử dĩ hư thụ nhân.","Trên núi có đầm là quẻ Hàm; người quân tử noi đó mà để lòng trống rỗng mà tiếp nhận người."],["山附地上剝上以厚下安宅","Sơn phụ địa thượng, Bác; thượng dĩ hậu hạ, an trạch.","Núi tựa sát trên đất là quẻ Bác; người trên noi đó mà vun dày cho người dưới để yên chỗ ở."],["巽小亨利有攸往利見大人","Tốn: Tiểu hanh, lợi hữu du vãng, lợi kiến đại nhân.","Tốn: hanh thông nhỏ, lợi có việc đi, lợi gặp bậc đại nhân."],["復則不妄矣故受之以无妄","phục tắc bất vọng hĩ cố thụ chi dĩ vô vọng","Trở lại rồi thì không còn làm bừa, nên tiếp bằng Vô Vọng."],["損而不已必益故受之以益","tổn nhi bất dĩ tất ích cố thụ chi dĩ ích","Bớt mãi không ngừng thì ắt thêm, nên tiếp bằng Ích."],["有過物者必濟故受之既濟","hữu quá vật giả tất tế cố thụ chi ký tế","Có vượt hơn vật thì ắt xong việc, nên tiếp bằng Ký Tế."],["澤无水困君子以致命遂志","Trạch vô thủy, Khốn; quân tử dĩ trí mệnh toại chí.","Đầm không có nước là quẻ Khốn; người quân tử noi đó mà liều cả tính mạng để thực hiện chí hướng."],["物不可以終通故受之以否","vật bất khả dĩ chung thông cố thụ chi dĩ bĩ","Vật không thể thông mãi, nên tiếp bằng Bĩ."],["物不可以終離故受之以節","vật bất khả dĩ chung ly cố thụ chi dĩ tiết","Vật không thể tan mãi, nên tiếp bằng Tiết."],["物不可終遯故受之以大壯","vật bất khả chung độn cố thụ chi dĩ đại tráng","Vật không thể lui mãi, nên tiếp bằng Đại Tráng."],["物大然後可觀故受之以觀","vật đại nhiên hậu khả quan cố thụ chi dĩ quan","Vật lớn rồi mới có thể được xem, nên tiếp bằng Quan."],["物畜然後有禮故受之以履","vật súc nhiên hậu hữu lễ cố thụ chi dĩ lý","Có tích chứa rồi mới có lễ, nên tiếp bằng Lý."],["臨元亨利貞至于八月有凶","Lâm: Nguyên hanh, lợi trinh. Chí vu bát nguyệt hữu hung.","Lâm: rất hanh thông, lợi về chính bền. Đến tháng tám thì có điều xấu."],["萬物之所成終而所成始也","vạn vật chi sở thành chung nhi sở thành thủy dã","nơi vạn vật kết thúc cũng là nơi bắt đầu"],["進必有所歸故受之以歸妹","tiến tất hữu sở quy cố thụ chi dĩ quy muội","Tiến ắt có nơi về, nên tiếp bằng Quy Muội."],["雷雨作解君子以赦過宥罪","Lôi vũ tác, Giải; quân tử dĩ xá quá hựu tội.","Sấm mưa nổi lên là quẻ Giải; người quân tử noi đó mà tha lỗi lầm, khoan giảm tội."],["雷電噬嗑先王以明罰敕法","Lôi điện, Phệ Hạp; tiên vương dĩ minh phạt sắc pháp.","Sấm và chớp là quẻ Phệ Hạp; các vua đời trước noi đó mà làm rõ hình phạt, sửa chỉnh pháp luật."],["需有孚光亨貞吉利涉大川","Nhu: Hữu phu, quang hanh, trinh cát, lợi thiệp đại xuyên.","Nhu: có lòng tin, sáng sủa hanh thông; giữ chính thì tốt, lợi qua sông lớn."],["革已日乃孚元亨利貞悔亡","Cách: Dĩ nhật nãi phu, nguyên hanh, lợi trinh, hối vong.","Cách: đến ngày (thời đã chín) mới được tin; rất hanh thông, lợi về chính bền, hối mất."],["革物者莫若鼎故受之以鼎","cách vật giả mạc nhược đỉnh cố thụ chi dĩ đỉnh","Đổi mới vật thì không gì bằng cái vạc, nên tiếp bằng Đỉnh."],["上九巽在牀下喪其資斧貞凶","Thượng cửu: Tốn tại sàng hạ, táng kỳ tư phủ, trinh hung.","Khiêm thuận đến mức nằm dưới giường, mất tiền của và cây rìu (sự quả quyết), cố giữ thì xấu."],["上九或錫之鞶帶終朝三褫之","Thượng cửu: Hoặc tích chi bàn đái, chung triêu tam sỉ chi.","Có khi được ban đai da (nhờ thắng kiện), nhưng chỉ trong một buổi sáng bị tước lại ba lần."],["不養則不可動故受之以大過","bất dưỡng tắc bất khả động cố thụ chi dĩ đại quá","Không nuôi thì không động được; động mạnh thì tiếp bằng Đại Quá."],["九三不恆其德或承之羞貞吝","Cửu tam: Bất hằng kỳ đức, hoặc thừa chi tu, trinh lận.","Không giữ bền đức của mình, có khi chuốc lấy sự hổ thẹn; cố giữ thì đáng tiếc."],["九三公用亨于天子小人弗克","Cửu tam: Công dụng hưởng vu thiên tử, tiểu nhân phất khắc.","Bậc công hầu đem dâng hiến lên thiên tử; kẻ tiểu nhân không làm được."],["九三幹父之蠱小有悔无大咎","Cửu tam: Cán phụ chi cổ, tiểu hữu hối, vô đại cữu.","Sửa việc hỏng của cha, hơi có hối, không lỗi lớn."],["九三征凶貞厲革言三就有孚","Cửu tam: Chinh hung, trinh lệ; cách ngôn tam tựu, hữu phu.","Đi (vội) thì xấu, cố giữ cũng nguy; lời bàn thay đổi đã qua ba lần xét kỹ thì được tin."],["九三旅焚其次喪其僮僕貞厲","Cửu tam: Lữ phần kỳ thứ, táng kỳ đồng bộc, trinh lệ.","Người lữ khách bị cháy quán trọ, mất đứa đầy tớ, cố giữ thì nguy."],["九二在師中吉无咎王三錫命","Cửu nhị: Tại sư trung, cát, vô cữu; vương tam tích mệnh.","Ở giữa quân (làm chủ tướng), tốt, không lỗi; vua ba lần ban mệnh."],["九五以杞包瓜含章有隕自天","Cửu ngũ: Dĩ khỉ bao qua, hàm chương, hữu vẫn tự thiên.","Lấy lá cây kỷ bọc quả dưa, ngậm giữ vẻ đẹp bên trong, có điều từ trời rơi xuống."],["九五渙汗其大號渙王居无咎","Cửu ngũ: Hoán hãn kỳ đại hiệu, hoán vương cư, vô cữu.","Ban hiệu lệnh lớn như mồ hôi tỏa ra (đi không trở lại), tán của kho vua cho dân, không lỗi."],["九四不克訟復即命渝安貞吉","Cửu tứ: Bất khắc tụng, phục tức mệnh du, an trinh cát.","Kiện không thắng, quay về theo lẽ phải, đổi lòng; yên giữ chính thì tốt."],["九四來荼荼困于金轝吝有終","Cửu tứ: Lai từ từ, khốn vu kim dư, lận, hữu chung.","Đến chậm rãi (nguyên văn chép 荼荼, đọc như 徐徐), bị khốn bởi xe bằng vàng; đáng tiếc, nhưng có kết quả."],["九四噬乾胏得金矢利艱貞吉","Cửu tứ: Phệ can trỉ, đắc kim thỉ, lợi gian trinh, cát.","Cắn miếng thịt khô có xương, được mũi tên đồng; lợi giữ chính trong gian nan, tốt."],["九四由豫大有得勿疑朋盍戠","Cửu tứ: Do dự, đại hữu đắc. Vật nghi, bằng hạp trâm.","Niềm vui do mình mà có, được nhiều. Chớ nghi ngờ, bạn bè sẽ tụ lại như tóc gom vào trâm."],["九四睽孤遇元夫交孚厲无咎","Cửu tứ: Khuê cô, ngộ nguyên phu, giao phu, lệ vô cữu.","Chia lìa cô độc, gặp được người tốt (sơ cửu), lấy lòng thành giao nhau; nguy mà không lỗi."],["九四鼎折足覆公餗其刑渥凶","Cửu tứ: Đỉnh chiết túc, phúc công tốc, kỳ hình ốc, hung.","Vạc gãy chân, đổ cháo của vua, thân mình nhơ nhuốc, xấu."],["以元經會以會經運以運經世","dĩ nguyên kinh hội dĩ hội kinh vận dĩ vận kinh thế","lấy Nguyên xếp Hội, lấy Hội xếp Vận, lấy Vận xếp Thế"],["億喪貝躋于九陵勿逐七日得","Ức táng bối, tê vu cửu lăng, vật trục, thất nhật đắc.","Liệu chừng mất của; lên chỗ cao mà đứng, chớ đuổi theo, bảy ngày sẽ được lại."],["六三得敵或鼓或罷或泣或歌","Lục tam: Đắc địch, hoặc cổ hoặc bãi, hoặc khấp hoặc ca.","Gặp đối thủ, khi thì đánh trống tiến, khi thì thôi, khi khóc khi hát."],["六三甘臨无攸利既憂之无咎","Lục tam: Cam lâm, vô du lợi. Ký ưu chi, vô cữu.","Lấy ngọt ngào mà đến gần, không có lợi gì. Đã biết lo mà sửa thì không lỗi."],["六二旅即次懷其資得僮僕貞","Lục nhị: Lữ tức thứ, hoài kỳ tư, đắc đồng bộc trinh.","Người lữ khách đến được quán trọ, mang theo tiền của, được đứa đầy tớ trung thành."],["六五噬乾肉得黃金貞厲无咎","Lục ngũ: Phệ can nhục, đắc hoàng kim, trinh lệ, vô cữu.","Cắn miếng thịt khô, được vàng; giữ chính, dè chừng nguy thì không lỗi."],["六五恆其德貞婦人吉夫子凶","Lục ngũ: Hằng kỳ đức, trinh; phụ nhân cát, phu tử hung.","Giữ bền đức của mình, chính bền; với người đàn bà thì tốt, với đàn ông thì xấu."],["六五拂經居貞吉不可涉大川","Lục ngũ: Phất kinh, cư trinh cát, bất khả thiệp đại xuyên.","Trái lẽ thường, ở yên giữ chính thì tốt, không thể vượt sông lớn."],["六四鴻漸于木或得其桷无咎","Lục tứ: Hồng tiệm vu mộc, hoặc đắc kỳ giác, vô cữu.","Chim hồng tiến lên cây, nếu được cành ngang (chỗ đậu bằng) thì không lỗi."],["初九官有渝貞吉出門交有功","Sơ cửu: Quan hữu du, trinh cát. Xuất môn giao hữu công.","Chủ kiến có thay đổi, giữ chính thì tốt. Ra khỏi cửa mà giao thiệp thì có công."],["初九震來虩虩後笑言啞啞吉","Sơ cửu: Chấn lai hích hích, hậu tiếu ngôn ách ách, cát.","Sấm đến làm sợ hãi, sau đó cười nói vui vẻ, tốt."],["升元亨用見大人勿恤南征吉","Thăng: Nguyên hanh, dụng kiến đại nhân, vật tuất, nam chinh cát.","Thăng: rất hanh thông, nên gặp bậc đại nhân, chớ lo, đi về phương nam thì tốt."],["困乎上者必反下故受之以井","khốn hồ thượng giả tất phản hạ cố thụ chi dĩ tỉnh","Bí ở trên thì ắt quay xuống dưới, nên tiếp bằng Tỉnh."],["困亨貞大人吉无咎有言不信","Khốn: Hanh, trinh, đại nhân cát, vô cữu. Hữu ngôn bất tín.","Khốn: hanh thông, giữ chính; bậc đại nhân thì tốt, không lỗi. Có nói cũng không ai tin."],["地中有水師君子以容民畜衆","Địa trung hữu thủy, Sư; quân tử dĩ dung dân súc chúng.","Trong đất có nước là quẻ Sư; người quân tử noi đó mà bao dung dân, nuôi dưỡng quần chúng."],["堯之前先天也堯之後後天也","nghiêu chi tiền tiên thiên dã nghiêu chi hậu hậu thiên dã","trước Nghiêu là Tiên thiên, sau Nghiêu là Hậu thiên)"],["大畜利貞不家食吉利涉大川","Đại Súc: Lợi trinh, bất gia thực cát, lợi thiệp đại xuyên.","Đại Súc: lợi về chính bền; không ăn cơm nhà (ra giúp đời, được nuôi bằng lộc) thì tốt; lợi vượt sông lớn."],["天下有風姤后以施命誥四方","Thiên hạ hữu phong, Cấu; hậu dĩ thi mệnh cáo tứ phương.","Dưới trời có gió là quẻ Cấu; bậc vua noi đó mà ban mệnh lệnh bá cáo bốn phương."],["天與火同人君子以類族辨物","Thiên dữ hỏa, Đồng Nhân; quân tử dĩ loại tộc biện vật.","Trời cùng lửa là quẻ Đồng Nhân; người quân tử noi đó mà xếp theo loài, phân biệt sự vật."],["夫易彰往而察來而微顯闡幽","phù dịch chương vãng nhi sát lai nhi vi hiển xiển u","Dịch làm rõ việc đã qua mà xét việc sắp tới, làm hiển cái vi tế, soi tỏ cái u ẩn (Hệ từ hạ)."],["山上有水蹇君子以反身修德","Sơn thượng hữu thủy, Kiển; quân tử dĩ phản thân tu đức.","Trên núi có nước là quẻ Kiển; người quân tử noi đó mà quay về tự xét mình, sửa đức."],["山下出泉蒙君子以果行育德","Sơn hạ xuất tuyền, Mông; quân tử dĩ quả hạnh dục đức.","Dưới núi có suối chảy ra là quẻ Mông; người quân tử noi đó mà quả quyết trong việc làm, nuôi dưỡng đức hạnh."],["山下有澤損君子以懲忿窒欲","Sơn hạ hữu trạch, Tổn; quân tử dĩ trừng phẫn trất dục.","Dưới núi có đầm là quẻ Tổn; người quân tử noi đó mà răn cơn giận, lấp lòng ham muốn."],["山下有風蠱君子以振民育德","Sơn hạ hữu phong, Cổ; quân tử dĩ chấn dân dục đức.","Dưới núi có gió là quẻ Cổ; người quân tử noi đó mà chấn hưng dân, nuôi dưỡng đức."],["幹父之蠱有子考无咎厲終吉","Cán phụ chi cổ, hữu tử khảo, vô cữu, lệ chung cát.","Sửa việc hỏng của cha, có con như thế thì cha không lỗi; nguy nhưng cuối cùng tốt."],["无平不陂无往不復艱貞无咎","Vô bình bất bí, vô vãng bất phục, gian trinh vô cữu.","Không chỗ bằng nào không nghiêng, không đi nào không trở lại; trong gian nan giữ chính thì không lỗi."],["明出地上晉君子以自昭明德","Minh xuất địa thượng, Tấn; quân tử dĩ tự chiêu minh đức.","Ánh sáng ra trên mặt đất là quẻ Tấn; người quân tử noi đó mà tự làm sáng đức sáng của mình."],["晉康侯用錫馬蕃庶晝日三接","Tấn: Khang hầu dụng tích mã phồn thứ, trú nhật tam tiếp.","Tấn: bậc hầu yên dân được ban ngựa rất nhiều, một ngày được vua tiếp ba lần."],["有大者不可以盈故受之以謙","hữu đại giả bất khả dĩ doanh cố thụ chi dĩ khiêm","Có lớn thì không được đầy tràn, nên tiếp bằng Khiêm."],["有大而能謙必豫故受之以豫","hữu đại nhi năng khiêm tất dự cố thụ chi dĩ dự","Có lớn mà biết nhún thì ắt vui, nên tiếp bằng Dự."],["木上有水井君子以勞民勸相","Mộc thượng hữu thủy, Tỉnh; quân tử dĩ lao dân khuyến tướng.","Trên gỗ có nước là quẻ Tỉnh; người quân tử noi đó mà khích lệ dân chăm làm, khuyên mọi người giúp đỡ nhau."],["木上有火鼎君子以正位凝命","Mộc thượng hữu hỏa, Đỉnh; quân tử dĩ chính vị ngưng mệnh.","Trên gỗ có lửa là quẻ Đỉnh; người quân tử noi đó mà làm ngay ngắn ngôi vị, ngưng tụ vững mệnh trời."],["比必有所畜也故受之以小畜","tỷ tất hữu sở súc dã cố thụ chi dĩ tiểu súc","Gắn bó thì ắt có chỗ tích chứa, nên tiếp bằng Tiểu Súc."],["渙亨王假有廟利涉大川利貞","Hoán: Hanh, vương cách hữu miếu, lợi thiệp đại xuyên, lợi trinh.","Hoán: hanh thông, vua đến nhà tông miếu, lợi vượt sông lớn, lợi về chính bền."],["澤中有火革君子以治歷明時","Trạch trung hữu hỏa, Cách; quân tử dĩ trị lịch minh thời.","Trong đầm có lửa là quẻ Cách; người quân tử noi đó mà soạn lịch, làm rõ thời tiết."],["物不可以終否故受之以同人","vật bất khả dĩ chung bĩ cố thụ chi dĩ đồng nhân","Vật không thể tắc mãi, nên tiếp bằng Đồng Nhân."],["碩果不食君子德車小人剝廬","Thạc quả bất thực, quân tử đắc dư, tiểu nhân bác lư.","Quả lớn còn lại không bị ăn; người quân tử giữ được xe, kẻ nhỏ phá nát nhà mình."],["窮大者必失其居故受之以旅","cùng đại giả tất thất kỳ cư cố thụ chi dĩ lữ","Lớn đến cùng thì ắt mất chỗ ở, nên tiếp bằng Lữ."],["聚而上者謂之升故受之以升","tụ nhi thượng giả vị chi thăng cố thụ chi dĩ thăng","Tụ rồi mà đi lên gọi là thăng, nên tiếp bằng Thăng."],["雲上於天需君子以飲食宴樂","Vân thượng ư thiên, Nhu; quân tử dĩ ẩm thực yến lạc.","Mây lên trên trời (chưa mưa) là quẻ Nhu; người quân tử noi đó mà ăn uống, yên vui chờ thời."],["雷電皆至豐君子以折獄致刑","Lôi điện giai chí, Phong; quân tử dĩ chiết ngục trí hình.","Sấm chớp cùng đến là quẻ Phong; người quân tử noi đó mà xét đoán việc ngục, thi hành hình phạt."],["風行天上小畜君子以懿文德","Phong hành thiên thượng, Tiểu Súc; quân tử dĩ ý văn đức.","Gió đi trên trời là quẻ Tiểu Súc; người quân tử noi đó mà trau dồi văn chương, đức hạnh."],["上九莫益之或擊之立心勿恆凶","Thượng cửu: Mạc ích chi, hoặc kích chi, lập tâm vật hằng, hung.","Không ai làm ích cho, lại có kẻ đánh; lập tâm không bền, xấu."],["上九鴻漸于陸其羽可用為儀吉","Thượng cửu: Hồng tiệm vu lục, kỳ vũ khả dụng vi nghi, cát.","Chim hồng tiến lên cõi cao, lông của nó có thể dùng làm đồ nghi lễ, tốt."],["上六不明晦初登于天後入于地","Thượng lục: Bất minh hối, sơ đăng vu thiên, hậu nhập vu địa.","Không sáng mà tối tăm; trước lên đến trời, sau sa vào đất."],["乖必有難故受之以蹇蹇者難也","quai tất hữu nan cố thụ chi dĩ kiển kiển giả nan dã","Lệch nhau ắt có khó, nên tiếp bằng Kiển; Kiển là khó."],["九三臀无膚其行次且厲无大咎","Cửu tam: Đồn vô phu, kỳ hành thư thả, lệ, vô đại cữu.","Mông không có da, đi đứng ngập ngừng; nguy nhưng không lỗi lớn."],["九四旅于處得其資斧我心不快","Cửu tứ: Lữ vu xứ, đắc kỳ tư phủ, ngã tâm bất khoái.","Người lữ khách có chỗ dừng tạm, được tiền của và rìu (phương tiện), mà lòng ta không vui."],["九四突如其來如焚如死如棄如","Cửu tứ: Đột như kỳ lai như, phần như, tử như, khí như.","Đột ngột mà đến, bốc cháy, chết, bị vứt bỏ."],["六三拂頤貞凶十年勿用无攸利","Lục tam: Phất di, trinh hung, thập niên vật dụng, vô du lợi.","Trái với đạo nuôi, cố giữ thì xấu; mười năm đừng dùng, không có lợi gì."],["六二不耕穫不菑畬則利有攸往","Lục nhị: Bất canh hoạch, bất tri dư, tắc lợi hữu du vãng.","Không cày mà gặt, không khai hoang mà có ruộng thuần (không mong kết quả mà kết quả đến); như thế thì lợi có việc đi."],["六二執之用黃牛之革莫之勝說","Lục nhị: Chấp chi dụng hoàng ngưu chi cách, mạc chi thắng thoát.","Buộc chặt bằng da bò vàng, không ai gỡ ra được."],["六二明夷夷于左股用拯馬壯吉","Lục nhị: Minh di, di vu tả cổ, dụng chửng mã tráng, cát.","Ánh sáng bị thương, thương ở đùi trái; dùng ngựa khỏe mà cứu thì tốt."],["六二艮其腓不拯其隨其心不快","Lục nhị: Cấn kỳ phì, bất chửng kỳ tùy, kỳ tâm bất khoái.","Dừng ở bắp chân, không cứu được người mình phải theo, lòng không vui."],["六五君子惟有解吉有孚于小人","Lục ngũ: Quân tử duy hữu giải, cát; hữu phu vu tiểu nhân.","Người quân tử chỉ có cởi gỡ thì tốt; lấy điều đó làm bằng chứng với tiểu nhân."],["六五悔亡矢得勿恤往吉无不利","Lục ngũ: Hối vong, thất đắc vật tuất, vãng cát vô bất lợi.","Hối mất; được mất chớ lo, đi thì tốt, không gì không lợi."],["六五貞吉无悔君子之光有孚吉","Lục ngũ: Trinh cát, vô hối. Quân tử chi quang, hữu phu, cát.","Giữ chính thì tốt, không hối. Ánh sáng của người quân tử, có lòng thành, tốt."],["六五賁於丘園束帛戔戔吝終吉","Lục ngũ: Bí vu khâu viên, thúc bạch tiên tiên; lận, chung cát.","Trang sức nơi gò vườn, bó lụa sơ sài ít ỏi; có vẻ keo kiệt nhưng cuối cùng tốt."],["六四中行告公從利用為依遷國","Lục tứ: Trung hành, cáo công tòng. Lợi dụng vi y thiên quốc.","Theo đạo trung, báo lên bậc công thì được nghe theo. Lợi dùng làm chỗ dựa để dời đô."],["六四翩翩不富以其鄰不戒以孚","Lục tứ: Phiên phiên, bất phú dĩ kỳ lân, bất giới dĩ phu.","Bay rập rờn (xuống), không cậy giàu mà cùng láng giềng, không cần răn bảo mà vẫn tin nhau."],["初九遇其配主雖旬无咎往有尚","Sơ cửu: Ngộ kỳ phối chủ, tuy tuần vô cữu, vãng hữu thượng.","Gặp người chủ xứng đôi (cửu tứ), tuy ngang nhau mà không lỗi, đi thì được trọng."],["初六晉如摧如貞吉罔孚裕无咎","Sơ lục: Tấn như, tồi như, trinh cát. Võng phu, dụ vô cữu.","Tiến lên mà bị cản lại, giữ chính thì tốt. Chưa được tin, cứ rộng rãi thong thả thì không lỗi."],["初六鴻漸于干小子厲有言无咎","Sơ lục: Hồng tiệm vu can, tiểu tử lệ, hữu ngôn, vô cữu.","Chim hồng tiến dần đến bờ nước; người trẻ gặp nguy, bị lời ra tiếng vào, nhưng không lỗi."],["天與水違行訟君子以作事謀始","Thiên dữ thủy vi hành, Tụng; quân tử dĩ tác sự mưu thủy.","Trời và nước đi ngược nhau là quẻ Tụng; người quân tử noi đó mà làm việc phải mưu tính ngay từ đầu."],["家人嗃嗃悔厲吉婦子嘻嘻終吝","Gia nhân hạc hạc, hối lệ cát; phụ tử hi hi, chung lận.","Nhà nghiêm quá có tiếng kêu ca, tuy nguy mà tốt; nhà cười đùa buông thả thì cuối cùng đáng tiếc."],["屯元亨利貞勿用有攸往利建侯","Truân: Nguyên hanh, lợi trinh. Vật dụng hữu du vãng, lợi kiến hầu.","Truân: rất hanh thông, lợi về chính bền. Chớ vội đi tới; lợi về việc dựng người giúp (lập tước hầu)."],["山上有木漸君子以居賢德善俗","Sơn thượng hữu mộc, Tiệm; quân tử dĩ cư hiền đức thiện tục.","Trên núi có cây là quẻ Tiệm; người quân tử noi đó mà giữ đức hiền, làm tốt phong tục."],["明兩作離大人以繼明照于四方","Minh lưỡng tác, Ly; đại nhân dĩ kế minh chiếu vu tứ phương.","Sáng hai lần dấy lên là quẻ Ly; bậc đại nhân noi đó mà nối tiếp ánh sáng soi khắp bốn phương."],["有其信者必行之故受之以小過","hữu kỳ tín giả tất hành chi cố thụ chi dĩ tiểu quá","Có lòng tin thì ắt làm theo, nên tiếp bằng Tiểu Quá."],["有无妄然後可畜故受之以大畜","hữu vô vọng nhiên hậu khả súc cố thụ chi dĩ đại súc","Không bừa rồi mới tích chứa lớn được, nên tiếp bằng Đại Súc."],["未濟亨小狐汔濟濡其尾无攸利","Vị Tế: Hanh. Tiểu hồ ngật tế, nhu kỳ vĩ, vô du lợi.","Vị Tế: hanh thông. Con cáo nhỏ gần qua được sông thì ướt đuôi, không có lợi gì."],["澤上有雷歸妹君子以永終知敝","Trạch thượng hữu lôi, Quy Muội; quân tử dĩ vĩnh chung tri tệ.","Trên đầm có sấm là quẻ Quy Muội; người quân tử noi đó mà giữ sự trọn vẹn lâu dài, biết trước chỗ hư hỏng."],["澤上有風中孚君子以議獄緩死","Trạch thượng hữu phong, Trung Phu; quân tử dĩ nghị ngục hoãn tử.","Trên đầm có gió là quẻ Trung Phu; người quân tử noi đó mà bàn xét kỹ việc ngục, hoãn án tử hình."],["澤中有雷隨君子以嚮晦入宴息","Trạch trung hữu lôi, Tùy; quân tử dĩ hướng hối nhập yến tức.","Trong đầm có sấm là quẻ Tùy; người quân tử noi đó mà khi trời tối thì vào nhà nghỉ ngơi."],["物不可窮也故受之以未濟終焉","vật bất khả cùng dã cố thụ chi dĩ vị tế chung yên","Vật không thể cùng tận, nên tiếp bằng Vị Tế; đến đây là hết."],["聖人設卦觀象繫辭焉而明吉凶","thánh nhân thiết quái quan tượng hệ từ yên nhi minh cát hung","thánh nhân đặt quẻ, xem tượng, gắn lời để rõ tốt xấu"],["雷在天上大壯君子以非禮弗履","Lôi tại thiên thượng, Đại Tráng; quân tử dĩ phi lễ phất lý.","Sấm ở trên trời là quẻ Đại Tráng; người quân tử noi đó mà điều gì trái lễ thì không làm."],["風行水上渙先王以享于帝立廟","Phong hành thủy thượng, Hoán; tiên vương dĩ hưởng vu đế, lập miếu.","Gió đi trên nước là quẻ Hoán; các vua đời trước noi đó mà tế Thượng đế, lập tông miếu."],["上九碩果不食君子德車小人剝廬","Thượng cửu: Thạc quả bất thực, quân tử đắc dư, tiểu nhân bác lư.","Trái lớn không bị ăn; quân tử được xe, tiểu nhân thì phá nát nhà mình."],["上六大君有命開國承家小人勿用","Thượng lục: Đại quân hữu mệnh, khai quốc thừa gia, tiểu nhân vật dụng.","Vua lớn có mệnh, phong nước, lập nhà; kẻ tiểu nhân chớ dùng."],["上天下澤履君子以辨上下定民志","Thượng thiên hạ trạch, Lý; quân tử dĩ biện thượng hạ, định dân chí.","Trên là trời, dưới là đầm, là quẻ Lý; người quân tử noi đó mà phân rõ trên dưới, định yên lòng dân."],["九三伏戎于莽升其高陵三歲不興","Cửu tam: Phục nhung vu mãng, thăng kỳ cao lăng, tam tuế bất hưng.","Phục binh trong bụi rậm, leo lên gò cao (dòm ngó), ba năm không dám dấy lên."],["九三君子終日乾乾夕惕若厲无咎","Cửu tam: Quân tử chung nhật càn càn, tịch dịch nhược; lệ, vô cữu.","Người quân tử suốt ngày hăng hái không nghỉ, tối vẫn dè dặt lo sợ; tuy nguy nhưng không lỗi."],["九三无平不陂无往不復艱貞无咎","cửu tam vô bình bất bí vô vãng bất phục gian trinh vô cữu","Không chỗ bằng nào không có lúc dốc, không đi nào không có lúc về; chịu khó giữ vững thì không lỗi."],["九二巽在牀下用史巫紛若吉无咎","Cửu nhị: Tốn tại sàng hạ, dụng sử vu phân nhược, cát vô cữu.","Khiêm thuận đến mức nằm dưới giường; dùng các quan sử, thầy cúng nhiều người (để bày tỏ lòng thành), tốt, không lỗi."],["九二鼎有實我仇有疾不我能即吉","Cửu nhị: Đỉnh hữu thực, ngã cừu hữu tật, bất ngã năng tức, cát.","Vạc có đồ đầy; kẻ thù của ta có bệnh (ghen ghét), không đến gần ta được, tốt."],["九五萃有位无咎匪孚元永貞悔亡","Cửu ngũ: Tụy hữu vị, vô cữu. Phỉ phu, nguyên vĩnh trinh, hối vong.","Tụ họp mà có ngôi, không lỗi. Nếu có người chưa tin, thì giữ đức lớn, lâu dài, chính bền, hối sẽ mất."],["九四豐其蔀日中見斗遇其夷主吉","Cửu tứ: Phong kỳ bộ, nhật trung kiến đẩu; ngộ kỳ di chủ, cát.","Thịnh mà bị màn che dày, giữa trưa thấy sao Bắc đẩu; gặp người chủ ngang hàng (sơ cửu), tốt."],["九四貞吉悔亡憧憧往來朋從爾思","Cửu tứ: Trinh cát hối vong; đồng đồng vãng lai, bằng tòng nhĩ tư.","Giữ chính thì tốt, hối hận mất. Nếu lăng xăng qua lại (cảm có tính toán), thì chỉ bạn bè theo ý nghĩ của anh."],["乾天也故稱乎父坤地也故稱乎母","Càn, thiên dã, cố xưng hồ phụ; Khôn, địa dã, cố xưng hồ mẫu;","Càn là trời nên gọi là cha; Khôn là đất nên gọi là mẹ."],["傷於外者必反其家故受之以家人","thương ư ngoại giả tất phản kỳ gia cố thụ chi dĩ gia nhân","Bị thương ở ngoài thì ắt quay về nhà, nên tiếp bằng Gia Nhân."],["入而后說之故受之以兌兌者說也","nhập nhi hậu duyệt chi cố thụ chi dĩ đoài đoài giả duyệt dã","Vào được rồi thì vui, nên tiếp bằng Đoài; Đoài là vui."],["六三含章可貞或從王事无成有終","Lục tam: Hàm chương khả trinh. Hoặc tòng vương sự, vô thành hữu chung.","Ngậm giữ vẻ đẹp bên trong, có thể giữ chính. Nếu theo việc của vua, đừng nhận thành công về mình thì có kết quả tốt."],["六三萃如嗟如无攸利往无咎小吝","Lục tam: Tụy như, ta như, vô du lợi; vãng vô cữu, tiểu lận.","Muốn tụ họp mà than thở, không lợi gì; đi thì không lỗi, hơi đáng tiếc."],["六五不富以其鄰利用侵伐无不利","Lục ngũ: Bất phú dĩ kỳ lân, lợi dụng xâm phạt, vô bất lợi.","Không cậy giàu mà được láng giềng theo; lợi dùng việc chinh phạt, không gì không lợi."],["六五或益之十朋之龜弗克違元吉","Lục ngũ: Hoặc ích chi, thập bằng chi quy phất khắc vi, nguyên cát.","Có người làm ích cho, (quý như) con rùa giá mười bằng cũng không thể từ chối, rất tốt."],["六四乘馬班如求婚媾往吉无不利","Lục tứ: Thặng mã ban như, cầu hôn cấu; vãng cát, vô bất lợi.","Cưỡi ngựa dùng dằng; đi cầu hôn, đi thì tốt, không gì không lợi."],["六四渙其群元吉渙有丘匪夷所思","Lục tứ: Hoán kỳ quần, nguyên cát. Hoán hữu khâu, phỉ di sở tư.","Làm tan bè phái, rất tốt. Tan rồi lại tụ thành gò lớn, không phải điều người thường nghĩ tới."],["六四賁如皤如白馬翰如匪寇婚媾","Lục tứ: Bí như bà như, bạch mã hàn như, phỉ khấu hôn cấu.","Trang sức mà trắng mộc, ngựa trắng phi như bay; chẳng phải giặc cướp, mà là người cầu hôn."],["初六幹父之蠱有子考无咎厲終吉","Sơ lục: Cán phụ chi cổ, hữu tử, khảo vô cữu; lệ chung cát.","Sửa việc hỏng của cha, có con như thế thì cha không lỗi; dù nguy nhưng cuối cùng tốt."],["否否之匪人不利君子貞大往小來","Bĩ chi phỉ nhân, bất lợi quân tử trinh, đại vãng tiểu lai.","Bế tắc vì kẻ chẳng phải người (không hợp đạo người), không lợi cho sự chính bền của quân tử; cái lớn đi, cái nhỏ đến."],["地上有水比先王以建萬國親諸侯","Địa thượng hữu thủy, Tỷ; tiên vương dĩ kiến vạn quốc, thân chư hầu.","Trên đất có nước là quẻ Tỷ; các vua đời trước noi đó mà dựng muôn nước, thân với chư hầu."],["家道窮必乖故受之以睽睽者乖也","gia đạo cùng tất quai cố thụ chi dĩ khuê khuê giả quai dã","Đạo nhà đến cùng ắt lệch nhau, nên tiếp bằng Khuê; Khuê là lệch."],["山下有雷頤君子以慎言語節飲食","Sơn hạ hữu lôi, Di; quân tử dĩ thận ngôn ngữ, tiết ẩm thực.","Dưới núi có sấm là quẻ Di; người quân tử noi đó mà cẩn thận lời nói, tiết độ ăn uống."],["數往者順知來者逆是故易逆數也","số vãng giả thuận tri lai giả nghịch thị cố dịch nghịch số dã","Đếm việc đã qua là thuận, biết việc sắp tới là ngược"],["旅而無所容故受之以巽巽者入也","lữ nhi vô sở dung cố thụ chi dĩ tốn tốn giả nhập dã","Đi trọ mà không được chứa, nên tiếp bằng Tốn; Tốn là vào."],["月將乃當權之帥萬卜以之爲綱領","nguyệt tướng nãi đương quyền chi suý vạn bốc dĩ chi vi 綱 lĩnh","tướng cầm quyền, cương lĩnh của mọi quẻ"],["水洊至習坎君子以常德行習教事","Thủy tiến chí, Tập Khảm; quân tử dĩ thường đức hạnh, tập giáo sự.","Nước chảy đến liên tiếp là quẻ Tập Khảm; người quân tử noi đó mà giữ đức hạnh thường hằng, luyện tập việc dạy dỗ."],["決必有所遇故受之以姤姤者遇也","quyết tất hữu sở ngộ cố thụ chi dĩ cấu cấu giả ngộ dã","Quyết rồi ắt có chỗ gặp, nên tiếp bằng Cấu; Cấu là gặp."],["澤上于地萃君子以除戎器戒不虞","Trạch thượng vu địa, Tụy; quân tử dĩ trừ nhung khí, giới bất ngu.","Đầm ở trên đất là quẻ Tụy; người quân tử noi đó mà sửa sang binh khí, đề phòng việc bất ngờ."],["澤上有水節君子以制數度議德行","Trạch thượng hữu thủy, Tiết; quân tử dĩ chế số độ, nghị đức hạnh.","Trên đầm có nước là quẻ Tiết; người quân tử noi đó mà đặt ra số lượng, mức độ, bàn bạc về đức hạnh."],["火在水上未濟君子以慎辨物居方","Hỏa tại thủy thượng, Vị Tế; quân tử dĩ thận biện vật cư phương.","Lửa ở trên nước là quẻ Vị Tế; người quân tử noi đó mà thận trọng phân biệt sự vật, đặt mỗi thứ vào đúng chỗ của nó."],["物不可終難故受之以解解者緩也","vật bất khả chung nan cố thụ chi dĩ giải giải giả hoãn dã","Vật không thể khó mãi, nên tiếp bằng Giải; Giải là buông ra."],["眾必有所比故受之以比比者比也","chúng tất hữu sở tỷ cố thụ chi dĩ tỷ tỷ giả tỷ dã","Đông người ắt phải có chỗ gắn bó, nên tiếp bằng Tỷ; Tỷ là gần gũi."],["與人同者物必歸焉故受之以大有","dữ nhân đồng giả vật tất quy yên cố thụ chi dĩ đại hữu","Biết chung với người thì vật ắt về, nên tiếp bằng Đại Hữu."],["訟必有眾起故受之以師師者眾也","tụng tất hữu chúng khởi cố thụ chi dĩ sư sư giả chúng dã","Tranh chấp ắt có đám đông nổi lên, nên tiếp bằng Sư; Sư là đông người."],["說而后散之故受之以渙渙者離也","duyệt nhi hậu tán chi cố thụ chi dĩ hoán hoán giả ly dã","Vui rồi thì tan ra, nên tiếp bằng Hoán; Hoán là tan."],["蹇利西南不利東北利見大人貞吉","Kiển: Lợi tây nam, bất lợi đông bắc; lợi kiến đại nhân, trinh cát.","Kiển: lợi ở tây nam, không lợi ở đông bắc; lợi gặp bậc đại nhân, giữ chính thì tốt."],["陷必有所麗故受之以離離者麗也","hãm tất hữu sở lệ cố thụ chi dĩ ly ly giả lệ dã","Sa vào hố ắt phải có chỗ bám, nên tiếp bằng Ly; Ly là bám, là sáng."],["風行地上觀先王以省方觀民設教","Phong hành địa thượng, Quan; tiên vương dĩ tỉnh phương, quan dân thiết giáo.","Gió đi trên mặt đất là quẻ Quan; các vua đời trước noi đó mà đi xem xét các phương, xem dân mà đặt giáo hóa."],["風雷益君子以見善則遷有過則改","Phong lôi, Ích; quân tử dĩ kiến thiện tắc thiên, hữu quá tắc cải.","Gió và sấm là quẻ Ích; người quân tử noi đó mà thấy điều thiện thì theo, có lỗi thì sửa."],["上九晉其角維用伐邑厲吉无咎貞吝","Thượng cửu: Tấn kỳ giác, duy dụng phạt ấp, lệ cát vô cữu, trinh lận.","Tiến đến chỗ sừng (tột cùng), chỉ nên dùng để đánh dẹp trong ấp mình; nguy mà tốt, không lỗi, cố giữ thì đáng tiếc."],["上六係用徽纆寘于叢棘三歲不得凶","Thượng lục: Hệ dụng huy mặc, trí vu tùng cức, tam tuế bất đắc, hung.","Bị trói bằng dây thừng, bỏ vào giữa bụi gai, ba năm không thoát, xấu."],["上六君子豹變小人革面征凶居貞吉","Thượng lục: Quân tử báo biến, tiểu nhân cách diện; chinh hung, cư trinh cát.","Người quân tử biến đổi như con báo, kẻ tiểu nhân thay đổi bộ mặt; đi nữa thì xấu, ở yên giữ chính thì tốt."],["上六城復于隍勿用師自邑告命貞吝","Thượng lục: Thành phục vu hoàng, vật dụng sư, tự ấp cáo mệnh, trinh lận.","Tường thành đổ xuống hào, chớ dùng quân; chỉ ra lệnh trong ấp mình, cố giữ thì đáng tiếc."],["上六女承筐无實士刲羊无血无攸利","Thượng lục: Nữ thừa khuông vô thực, sĩ khuê dương vô huyết, vô du lợi.","Người nữ bưng giỏ mà không có gì, người nam mổ dê mà không có máu, không có lợi gì."],["上六弗遇過之飛鳥離之凶是謂災眚","Thượng lục: Phất ngộ quá chi, phi điểu ly chi, hung, thị vị tai sảnh.","Không gặp mà vượt quá, chim bay mắc lưới, xấu, đó gọi là tai họa."],["上六拘係之乃從維之王用亨于西山","Thượng lục: Câu hệ chi, nãi tòng duy chi. Vương dụng hưởng vu tây sơn.","Níu buộc lấy, lại theo mà ràng giữ chặt. Vua dùng lòng ấy để tế ở núi tây."],["九三家人嗃嗃悔厲吉婦子嘻嘻終吝","Cửu tam: Gia nhân hạc hạc, hối lệ cát; phụ tử hi hi, chung lận.","Người trong nhà kêu ca vì quá nghiêm, có hối, nguy mà tốt; vợ con cười đùa hi hi, cuối cùng đáng tiếc."],["九三明夷于南狩得其大首不可疾貞","Cửu tam: Minh di vu nam thú, đắc kỳ đại thủ, bất khả tật trinh.","Ánh sáng bị thương trong cuộc săn phía nam, bắt được kẻ cầm đầu; không thể vội vàng cố giữ."],["九三豐其沛日中見沬折其右肱无咎","Cửu tam: Phong kỳ bái, nhật trung kiến muội, chiết kỳ hữu quăng, vô cữu.","Thịnh mà bị rèm che kín hơn, giữa trưa thấy cả sao nhỏ; gãy cánh tay phải, không lỗi."],["九三高宗伐鬼方三年克之小人勿用","Cửu tam: Cao Tông phạt Quỷ Phương, tam niên khắc chi, tiểu nhân vật dụng.","Vua Cao Tông đánh nước Quỷ Phương, ba năm mới thắng; kẻ tiểu nhân chớ dùng."],["九二枯楊生稊老夫得其女妻无不利","Cửu nhị: Khô dương sinh đề, lão phu đắc kỳ nữ thê, vô bất lợi.","Cây dương khô đâm chồi non, ông già lấy được vợ trẻ, không gì không lợi."],["九五休否大人吉其亡其亡繫于包桑","Cửu ngũ: Hưu bĩ, đại nhân cát. Kỳ vong kỳ vong, hệ vu bao tang.","Làm cho bế tắc dừng lại, đại nhân thì tốt. Hãy nghĩ: sắp mất rồi, sắp mất rồi! – như buộc vào khóm dâu (cho vững)."],["九五同人先號啕而後笑大師克相遇","Cửu ngũ: Đồng nhân, tiên hào đào nhi hậu tiếu. Đại sư khắc tương ngộ.","Hòa đồng với người, trước kêu khóc mà sau cười. Đại quân thắng được (kẻ ngăn trở) rồi mới gặp nhau."],["九五有孚惠心勿問元吉有孚惠我德","Cửu ngũ: Hữu phu huệ tâm, vật vấn nguyên cát. Hữu phu huệ ngã đức.","Có lòng thành muốn ban ơn, không cần hỏi cũng rất tốt. Dân thành tâm mến đức của ta."],["九四隨有獲貞凶有孚在道以明何咎","Cửu tứ: Tùy hữu hoạch, trinh hung. Hữu phu tại đạo, dĩ minh, hà cữu?","Được người theo, có thu hoạch; cố giữ thì xấu. Có lòng thành, theo đạo, sáng suốt thì lỗi gì?"],["元神生用神須要旺相方可生得用神","nguyên thần sinh dụng thần tu yếu 旺 tương phương khả sinh đắc dụng thần","nguyên thần tuy sinh dụng thần nhưng phải vượng tướng mới sinh nổi"],["六三來之坎坎險且枕入于坎窞勿用","Lục tam: Lai chi khảm khảm, hiểm thả chẩm, nhập vu khảm đạm, vật dụng.","Đến hay đi đều là hiểm, hiểm lại dựa vào hiểm, sa vào đáy hố; chớ dùng (chớ hành động)."],["六三係丈夫失小子隨有求得利居貞","Lục tam: Hệ trượng phu, thất tiểu tử. Tùy hữu cầu đắc, lợi cư trinh.","Buộc theo người trượng phu, bỏ đứa trẻ con. Theo mà cầu thì được, lợi ở yên giữ chính."],["六三勿用取女見金夫不有躬无攸利","Lục tam: Vật dụng thú nữ, kiến kim phu, bất hữu cung, vô du lợi.","Chớ cưới người con gái ấy: thấy kẻ lắm tiền thì không giữ được mình; chẳng có gì lợi."],["六三食舊德貞厲終吉或從王事无成","Lục tam: Thực cựu đức, trinh lệ, chung cát. Hoặc tòng vương sự, vô thành.","Hưởng lộc cũ (giữ phần vốn có), giữ chính tuy nguy, cuối cùng tốt. Nếu theo việc vua, đừng nhận thành công về mình."],["六四入于左腹獲明夷之心于出門庭","Lục tứ: Nhập vu tả phúc, hoạch minh di chi tâm, vu xuất môn đình.","Vào bụng bên trái, biết được lòng của kẻ làm tổn thương ánh sáng, bèn ra khỏi cửa sân."],["六四尊酒簋貳用缶内約自牖終无咎","Lục tứ: Tôn tửu, quỹ nhị, dụng phẫu; nạp ước tự dũ, chung vô cữu.","Một chén rượu, hai bát cơm, đựng bằng đồ sành; dâng lời ước hẹn qua cửa sổ, cuối cùng không lỗi."],["六四顛頤吉虎視眈眈其欲逐逐无咎","Lục tứ: Điên di cát, hổ thị đam đam, kỳ dục trục trục, vô cữu.","Ngược lại xin người dưới nuôi mà tốt; như hổ nhìn chằm chằm, lòng muốn nối nhau không dứt, không lỗi."],["其上易知本末也初辭擬之卒成之終","Kỳ thượng dị tri, bản mạt dã. Sơ từ nghĩ chi, tốt thành chi chung.","Bước cuối dễ biết, vì nó là ngọn của gốc. Lời hào đầu chỉ mới ướm; đến hào cuối việc thành hình trọn vẹn, nên dễ nhìn ra."],["初九悔亡喪馬勿逐自復見惡人无咎","Sơ cửu: Hối vong, táng mã vật trục, tự phục; kiến ác nhân vô cữu.","Hối mất; mất ngựa chớ đuổi, nó tự về; gặp kẻ xấu (vẫn tiếp) thì không lỗi."],["初六發蒙利用刑人用說桎梏以往吝","Sơ lục: Phát mông, lợi dụng hình nhân, dụng thoát chất cốc; dĩ vãng lận.","Mở mang sự tối tăm, lợi dùng hình phạt để răn người, để cởi gông cùm (của sự ngu tối); nếu cứ thế mà đi thì đáng tiếc."],["初六臀困于株木入于幽谷三歲不覿","Sơ lục: Đồn khốn vu châu mộc, nhập vu u cốc, tam tuế bất địch.","Mông ngồi khốn trên gốc cây trụi, sa vào hang tối, ba năm không thấy ai."],["初六鼎顛趾利出否得妾以其子无咎","Sơ lục: Đỉnh điên chỉ, lợi xuất bĩ, đắc thiếp dĩ kỳ tử, vô cữu.","Vạc lật chân lên, lợi đổ bỏ cặn bẩn; lấy vợ lẽ vì có con, không lỗi."],["同人同人于野亨利涉大川利君子貞","Đồng nhân vu dã, hanh. Lợi thiệp đại xuyên, lợi quân tử trinh.","Hòa đồng với người ở nơi đồng nội (rộng khắp), hanh thông. Lợi vượt sông lớn, lợi cho quân tử giữ chính."],["地中生木升君子以順德積小以高大","Địa trung sinh mộc, Thăng; quân tử dĩ thuận đức, tích tiểu dĩ cao đại.","Trong đất mọc cây là quẻ Thăng; người quân tử noi đó mà thuận theo đức, tích từng chút nhỏ mà thành cao lớn."],["天下有山遯君子以遠小人不惡而嚴","Thiên hạ hữu sơn, Độn; quân tử dĩ viễn tiểu nhân, bất ác nhi nghiêm.","Dưới trời có núi là quẻ Độn; người quân tử noi đó mà xa lánh tiểu nhân, không ghét bỏ mà nghiêm trang."],["履而泰然後安故受之以泰泰者通也","lý nhi thái nhiên hậu an cố thụ chi dĩ thái thái giả thông dã","Đi đúng mà thông suốt, rồi mới yên, nên tiếp bằng Thái; Thái là thông."],["山下有火賁君子以明庶政无敢折獄","Sơn hạ hữu hỏa, Bí; quân tử dĩ minh thứ chính, vô cảm chiết ngục.","Dưới núi có lửa là quẻ Bí; người quân tử noi đó mà làm sáng tỏ các việc chính sự thường, không dám dựa vào đó mà quyết đoán việc ngục."],["明入地中明夷君子以蒞眾用晦而明","Minh nhập địa trung, Minh Di; quân tử dĩ lỵ chúng, dụng hối nhi minh.","Ánh sáng vào trong đất là quẻ Minh Di; người quân tử noi đó mà đến với mọi người, dùng sự tối (khiêm, kín đáo) mà vẫn sáng."],["有事而后可大故受之以臨臨者大也","hữu sự nhi hậu khả đại cố thụ chi dĩ lâm lâm giả đại dã","Có việc rồi mới có thể lớn, nên tiếp bằng Lâm; Lâm là lớn."],["水在火上既濟君子以思患而豫防之","Thủy tại hỏa thượng, Ký Tế; quân tử dĩ tư hoạn nhi dự phòng chi.","Nước ở trên lửa là quẻ Ký Tế; người quân tử noi đó mà nghĩ đến tai họa để phòng trước."],["物不可以終壯故受之以晉晉者進也","vật bất khả dĩ chung tráng cố thụ chi dĩ tấn tấn giả tiến dã","Vật không thể mạnh mãi, nên tiếp bằng Tấn; Tấn là tiến."],["物不可以終止故受之以漸漸者進也","vật bất khả dĩ chung chỉ cố thụ chi dĩ tiệm tiệm giả tiến dã","Vật không thể dừng mãi, nên tiếp bằng Tiệm; Tiệm là tiến từ từ."],["物不可以終過故受之以坎坎者陷也","vật bất khả dĩ chung quá cố thụ chi dĩ khảm khảm giả hãm dã","Vật không thể quá mãi, nên tiếp bằng Khảm; Khảm là sa vào hố."],["物畜然後可養故受之以頤頤者養也","vật súc nhiên hậu khả dưỡng cố thụ chi dĩ di di giả dưỡng dã","Có tích chứa rồi mới nuôi được, nên tiếp bằng Di; Di là nuôi."],["物相遇而后聚故受之以萃萃者聚也","vật tương ngộ nhi hậu tụ cố thụ chi dĩ tụy tụy giả tụ dã","Vật gặp nhau rồi mới tụ lại, nên tiếp bằng Tụy; Tụy là tụ."],["益而不已必決故受之以夬夬者決也","ích nhi bất dĩ tất quyết cố thụ chi dĩ quải quải giả quyết dã","Thêm mãi không ngừng thì ắt phải quyết, nên tiếp bằng Quải; Quải là quyết."],["蠱元亨利涉大川先甲三日後甲三日","Cổ: Nguyên hanh, lợi thiệp đại xuyên. Tiên giáp tam nhật, hậu giáp tam nhật.","Cổ: rất hanh thông, lợi vượt sông lớn. Trước ngày Giáp ba ngày, sau ngày Giáp ba ngày."],["進必有所傷故受之以明夷夷者傷也","tiến tất hữu sở thương cố thụ chi dĩ minh di di giả thương dã","Tiến ắt có chỗ bị thương, nên tiếp bằng Minh Di; Di là thương."],["點卦由下而上故裝五行也由下而上","điểm quái do hạ nhi thượng cố 裝 ngũ hành dã do hạ nhi thượng","vạch quẻ từ dưới lên nên gắn ngũ hành cũng từ dưới lên"],["上九有孚于飲酒无咎濡其首有孚失是","Thượng cửu: Hữu phu vu ẩm tửu, vô cữu. Nhu kỳ thủ, hữu phu thất thị.","Tin tưởng mà uống rượu (chờ thời), không lỗi. Nếu say đến ướt đầu thì dù có tin cũng mất điều phải."],["上九王用出征有嘉折首獲匪其醜无咎","Thượng cửu: Vương dụng xuất chinh, hữu gia chiết thủ, hoạch phỉ kỳ xú, vô cữu.","Vua dùng (người này) ra quân, có công tốt: chém kẻ cầm đầu, bắt mà không truy kẻ theo, không lỗi."],["上六公用射隼于高墉之上獲之无不利","Thượng lục: Công dụng xạ chuẩn vu cao dung chi thượng, hoạch chi, vô bất lợi.","Bậc công bắn con chim cắt đậu trên tường thành cao, bắt được, không gì không lợi."],["上六困于葛藟于臲卼曰動悔有悔征吉","Thượng lục: Khốn vu cát lũy, vu niết ngột, viết động hối. Hữu hối, chinh cát.","Khốn vì dây sắn quấn, ở chỗ chênh vênh, tự bảo: động thì hối. Biết hối mà đi thì tốt."],["主器者莫若長子故受之以震震者動也","chủ khí giả mạc nhược trưởng tử cố thụ chi dĩ chấn chấn giả động dã","Giữ vạc thì không ai bằng con trưởng, nên tiếp bằng Chấn; Chấn là động."],["九二不克訟歸而逋其邑人三百戶无眚","Cửu nhị: Bất khắc tụng, quy nhi bô, kỳ ấp nhân tam bách hộ vô sảnh.","Kiện không thắng, về mà lánh đi; ấp nhỏ ba trăm hộ của mình không bị tai vạ."],["九五劓刖困于赤紱乃徐有說利用祭祀","Cửu ngũ: Tị nguyệt, khốn vu xích phất; nãi từ hữu duyệt, lợi dụng tế tự.","Bị xẻo mũi chặt chân (tổn hại trên dưới), khốn vì người dải đỏ (bề tôi); rồi dần dần có vui, lợi dùng tế lễ."],["九五枯楊生華老婦得其士夫无咎无譽","Cửu ngũ: Khô dương sinh hoa, lão phụ đắc kỳ sĩ phu, vô cữu vô dự.","Cây dương khô nở hoa, bà già lấy được chồng trẻ; không lỗi, không khen."],["九五顯比王用三敺失前禽邑人不誡吉","Cửu ngũ: Hiển tỷ. Vương dụng tam khu, thất tiền cầm; ấp nhân bất giới, cát.","Gần gũi một cách quang minh. Vua đi săn chỉ vây ba mặt, để mất con thú chạy phía trước; người trong ấp không phải răn đe, tốt."],["九五鴻漸于陵婦三歲不孕終莫之勝吉","Cửu ngũ: Hồng tiệm vu lăng, phụ tam tuế bất dựng, chung mạc chi thắng, cát.","Chim hồng tiến lên gò cao; vợ ba năm không có thai, nhưng cuối cùng không gì ngăn được, tốt."],["九四无咎弗過遇之往厲必戒勿用永貞","Cửu tứ: Vô cữu, phất quá ngộ chi. Vãng lệ tất giới, vật dụng vĩnh trinh.","Không lỗi, không vượt quá mà gặp được. Đi thì nguy, phải răn; chớ cố chấp mãi."],["九四貞吉悔亡藩決不羸壯于大轝之腹","Cửu tứ: Trinh cát hối vong, phiên quyết bất luy, tráng vu đại dư chi phúc.","Giữ chính thì tốt, hối mất; rào mở ra không bị mắc, mạnh như trục xe lớn."],["六三三人行則損一人一人行則得其友","Lục tam: Tam nhân hành tắc tổn nhất nhân; nhất nhân hành tắc đắc kỳ hữu.","Ba người đi thì bớt một người; một người đi thì được bạn."],["六三見輿曳其牛其人天且劓无初有終","Lục tam: Kiến dư duệ, kỳ ngưu xế, kỳ nhân thiên thả tị, vô sơ hữu chung.","Thấy xe bị kéo lại, bò bị níu, người thì bị thích chữ vào trán và xẻo mũi; lúc đầu không tốt, sau có kết quả."],["六二晉如愁如貞吉受茲介福于其王母","Lục nhị: Tấn như, sầu như, trinh cát. Thụ tư giới phúc, vu kỳ vương mẫu.","Tiến lên mà lo buồn, giữ chính thì tốt. Sẽ nhận phúc lớn từ bà vương mẫu."],["六五密雲不雨自我西郊公弋取彼在穴","Lục ngũ: Mật vân bất vũ, tự ngã tây giao; công dặc thủ bỉ tại huyệt.","Mây dày mà không mưa, từ cõi tây của ta; bậc công bắn tên có dây bắt con vật trong hang."],["凡用神旺相而遇旬空出空之日則出矣","phàm dụng thần 旺 tương nhi ngộ tuần không xuất không chi nhật tắc xuất hĩ","hào không mà vượng thì đợi ngày ra khỏi không là ứng"],["占財物以此爲劫神占謀事以此爲阻神","chiêm tài vật dĩ thử vi kiếp thần chiêm mưu sự dĩ thử vi trở thần","hỏi tiền thì nó cướp tài, hỏi việc thì nó cản"],["地中有山謙君子以裒多益寡稱物平施","Địa trung hữu sơn, Khiêm; quân tử dĩ bầu đa ích quả, xứng vật bình thi.","Trong đất có núi là quẻ Khiêm; người quân tử noi đó mà bớt chỗ nhiều, bù chỗ ít, cân nhắc sự vật mà ban phát công bằng."],["山上有火旅君子以明慎用刑而不留獄","Sơn thượng hữu hỏa, Lữ; quân tử dĩ minh thận dụng hình, nhi bất lưu ngục.","Trên núi có lửa là quẻ Lữ; người quân tử noi đó mà sáng suốt, thận trọng khi dùng hình phạt, không giam giữ án lâu."],["得其所歸者必大故受之以豐豐者大也","đắc kỳ sở quy giả tất đại cố thụ chi dĩ phong phong giả đại dã","Được nơi về thì ắt lớn, nên tiếp bằng Phong; Phong là lớn, là đầy."],["无妄之災或繫之牛行人之得邑人之災","Vô vọng chi tai, hoặc hệ chi ngưu, hành nhân chi đắc, ấp nhân chi tai.","Họa không do mình: có người buộc bò, kẻ qua đường dắt mất, người trong ấp bị vạ."],["无妄元亨利貞其匪正有眚不利有攸往","Vô Vọng: Nguyên hanh, lợi trinh. Kỳ phỉ chính hữu sảnh, bất lợi hữu du vãng.","Vô Vọng: rất hanh thông, lợi về chính bền. Nếu không chính thì có tai họa, không lợi có việc đi."],["日中則昃月盈則食天地盈虛與時消息","nhật trung tắc trắc nguyệt doanh tắc thực thiên địa doanh hư dữ thời tiêu tức","mặt trời đứng bóng thì xế, trăng tròn thì khuyết"],["比吉原筮元永貞无咎不寧方來後夫凶","Tỷ: Cát. Nguyên phệ, nguyên vĩnh trinh, vô cữu. Bất ninh phương lai, hậu phu hung.","Tỷ: tốt. Xét kỹ lại (như bói lần nữa) xem có đủ đức lớn, lâu dài, chính bền thì không lỗi. Kẻ chưa yên đang kéo đến; kẻ đến sau thì xấu."],["澤上于天夬君子以施祿及下居德則忌","Trạch thượng vu thiên, Quải; quân tử dĩ thi lộc cập hạ, cư đức tắc kỵ.","Nước đầm dâng lên trời là quẻ Quải; người quân tử noi đó mà ban lộc xuống người dưới, ỷ vào đức (giữ khư khư) là điều kiêng."],["澤滅木大過君子以獨立不懼遯世无悶","Trạch diệt mộc, Đại Quá; quân tử dĩ độc lập bất cụ, độn thế vô muộn.","Đầm nước ngập cây là quẻ Đại Quá; người quân tử noi đó mà đứng một mình không sợ, lánh đời không buồn."],["物不可以終盡剝窮上反下故受之以復","vật bất khả dĩ chung tận bác cùng thượng phản hạ cố thụ chi dĩ phục","Vật không thể hết mãi; rụng đến cùng ở trên thì quay về từ dưới, nên tiếp bằng Phục."],["解利西南无所往其來復吉有攸往夙吉","Giải: Lợi tây nam. Vô sở vãng, kỳ lai phục cát. Hữu du vãng, túc cát.","Giải: lợi ở tây nam. Không còn chỗ phải đi thì trở về (nếp cũ) là tốt. Có việc phải đi thì đi sớm là tốt."],["風自火出家人君子以言有物而行有恆","Phong tự hỏa xuất, Gia Nhân; quân tử dĩ ngôn hữu vật, nhi hành hữu hằng.","Gió từ lửa mà ra là quẻ Gia Nhân; người quân tử noi đó mà nói có thực chất, làm có thường hằng."],["上六入于穴有不速之客三人來敬之終吉","Thượng lục: Nhập vu huyệt, hữu bất tốc chi khách tam nhân lai, kính chi chung cát.","Vào hang; có ba người khách không mời mà đến, kính trọng họ thì cuối cùng tốt."],["九三日昃之離不鼓缶而歌則大耋之差凶","Cửu tam: Nhật trắc chi ly, bất cổ phẫu nhi ca, tắc đại điệt chi ta, hung.","Ánh sáng lúc mặt trời xế; không gõ chậu mà hát (vui với số phận), thì than thở vì tuổi già, xấu."],["九三良馬逐利艱貞吉日閑輿衛利有攸往","Cửu tam: Lương mã trục, lợi gian trinh, cát. Nhật nhàn dư vệ, lợi hữu du vãng.","Ngựa tốt rong ruổi; lợi giữ chính trong gian nan, tốt. Ngày ngày tập luyện xe cộ và phòng vệ, lợi có việc đi."],["九二包荒用馮河不遐遺朋亡得尚于中行","Cửu nhị: Bao hoang, dụng bằng hà, bất hà di; bằng vong. Đắc thượng vu trung hành.","Bao dung cả kẻ thô lỗ, dám lội qua sông, không bỏ sót kẻ ở xa, không kéo bè kéo cánh; như thế là hợp đạo trung."],["九五東鄰殺牛不如西鄰之禴祭實受其福","Cửu ngũ: Đông lân sát ngưu, bất như tây lân chi thược tế, thực thụ kỳ phúc.","Láng giềng phía đông giết bò (tế lễ lớn), không bằng láng giềng phía tây làm lễ Thược đơn sơ mà thật được hưởng phúc."],["九四臀无膚其行次且牽羊悔亡聞言不信","Cửu tứ: Đồn vô phu, kỳ hành thư thả. Khiên dương hối vong, văn ngôn bất tín.","Mông không có da, đi đứng ngập ngừng. Dắt dê (đi theo sau bầy) thì hối mất, nhưng nghe lời mà không tin."],["以喜隨人者必有事故受之以蠱蠱者事也","dĩ hỉ tùy nhân giả tất hữu sự cố thụ chi dĩ cổ cổ giả sự dã","Vì vui mà theo người thì ắt có việc hỏng phải sửa, nên tiếp bằng Cổ; Cổ là việc."],["六三益之用凶事无咎有孚中行告公用圭","Lục tam: Ích chi dụng hung sự, vô cữu. Hữu phu trung hành, cáo công dụng khuê.","Được ích nhờ dùng vào việc hung hiểm (cứu nạn), không lỗi. Có lòng thành, theo đạo trung, cầm ngọc khuê báo lên bậc công."],["六二過其祖遇其妣不及其君遇其臣无咎","Lục nhị: Quá kỳ tổ, ngộ kỳ tỷ; bất cập kỳ quân, ngộ kỳ thần, vô cữu.","Vượt qua ông, gặp được bà; không với tới vua, gặp được bề tôi; không lỗi."],["六二震來厲億喪貝躋于九陵勿逐七日得","Lục nhị: Chấn lai lệ, ức táng bối, tê vu cửu lăng, vật trục, thất nhật đắc.","Sấm đến nguy hiểm, liệu chừng mất của cải; leo lên chín lớp gò cao, chớ đuổi theo, bảy ngày sẽ được lại."],["初六有孚比之无咎有孚盈缶終來有它吉","Sơ lục: Hữu phu tỷ chi, vô cữu. Hữu phu doanh phẫu, chung lai hữu tha, cát.","Có lòng thành mà gần gũi, không lỗi. Lòng thành đầy như chum, sau rốt còn có điều tốt khác đến."],["卽是枯根木逢生生之不起逢傷更傷者重","卽 thị khô căn mộc 逢 sinh sinh chi bất khởi 逢 thương canh thương giả trọng","như cây khô rễ, gặp sinh không dậy, gặp thương càng nặng."],["可觀而后有所合故受之以噬嗑嗑者合也","khả quan nhi hậu hữu sở hợp cố thụ chi dĩ phệ hạp hạp giả hợp dã","Đáng xem rồi mới có chỗ hợp lại, nên tiếp bằng Phệ Hạp; Hạp là hợp."],["天下雷行物與无妄先王以茂對時育萬物","Thiên hạ lôi hành, vật dữ vô vọng; tiên vương dĩ mậu đối thời, dục vạn vật.","Dưới trời sấm đi, muôn vật đều không càn bậy; các vua đời trước noi đó mà gắng sức thuận theo thời, nuôi dưỡng muôn vật."],["天地不交否君子以儉德辟難不可榮以祿","Thiên địa bất giao, Bĩ; quân tử dĩ kiệm đức tị nạn, bất khả vinh dĩ lộc.","Trời đất không giao là quẻ Bĩ; người quân tử noi đó mà thu giữ đức để tránh nạn, không thể lấy bổng lộc làm vinh."],["天地定位山澤通氣雷風相薄水火不相射","thiên địa định vị sơn trạch thông khí lôi phong tương bạc thủy hỏa bất tương xạ","Trời đất định vị, núi đầm thông khí, sấm gió xô nhau, nước lửa không bắn nhau"],["易之興也其於中古乎作易者其有憂患乎","Dịch chi hưng dã, kỳ ư trung cổ hồ! Tác Dịch giả, kỳ hữu ưu hoạn hồ!","Dịch hưng thịnh có lẽ vào thời trung cổ chăng! Người làm ra Dịch có lẽ mang nỗi lo âu chăng!"],["澤上有地臨君子以教思无窮容保民无疆","Trạch thượng hữu địa, Lâm; quân tử dĩ giáo tư vô cùng, dung bảo dân vô cương.","Trên đầm có đất là quẻ Lâm; người quân tử noi đó mà nghĩ việc dạy dân không cùng, bao dung bảo vệ dân không bờ bến."],["火在天上大有君子以遏惡揚善順天休命","Hỏa tại thiên thượng, Đại Hữu; quân tử dĩ át ác dương thiện, thuận thiên hưu mệnh.","Lửa ở trên trời là quẻ Đại Hữu; người quân tử noi đó mà ngăn điều ác, nêu điều thiện, thuận theo mệnh tốt của trời."],["物不可以久居其所故受之以遯遯者退也","vật bất khả dĩ cửu cư kỳ sở cố thụ chi dĩ độn độn giả thoái dã","Vật không thể ở mãi một chỗ, nên tiếp bằng Độn; Độn là lui."],["物不可以終動止之故受之以艮艮者止也","vật bất khả dĩ chung động chỉ chi cố thụ chi dĩ cấn cấn giả chỉ dã","Vật không thể động mãi, phải dừng, nên tiếp bằng Cấn; Cấn là dừng."],["物不可以苟合而已故受之以賁賁者飾也","vật bất khả dĩ cẩu hợp nhi dĩ cố thụ chi dĩ bí bí giả sức dã","Vật không thể hợp bừa cho xong, nên tiếp bằng Bí; Bí là trang sức."],["物生必蒙故受之以蒙蒙者蒙也物之穉也","vật sinh tất mông cố thụ chi dĩ mông mông giả mông dã vật chi trĩ dã","Vật sinh ra ắt còn mờ tối, nên tiếp bằng Mông; Mông là mờ, là vật còn non."],["致飾然後亨則盡矣故受之以剝剝者剝也","trí sức nhiên hậu hanh tắc tận hĩ cố thụ chi dĩ bác bác giả bác dã","Trau chuốt đến cùng thì thông, nhưng cũng hết, nên tiếp bằng Bác; Bác là rụng."],["艮艮其背不獲其身行其庭不見其人无咎","Cấn kỳ bối, bất hoạch kỳ thân; hành kỳ đình, bất kiến kỳ nhân, vô cữu.","Dừng ở lưng, không thấy thân mình; đi trong sân mà không thấy người, không lỗi."],["三多凶五多功貴賤之等也其柔危其剛勝邪","Tam đa hung, ngũ đa công, quý tiện chi đẳng dã. Kỳ nhu nguy, kỳ cương thắng da?","Hào Ba nhiều rủi, hào Năm nhiều công, vì thấp cao khác bậc. Mềm thì nguy, cứng thì hơn chăng?"],["上九弗損益之无咎貞吉利有攸往得臣无家","Thượng cửu: Phất tổn ích chi, vô cữu, trinh cát, lợi hữu du vãng, đắc thần vô gia.","Không bớt (của dân) mà vẫn làm ích, không lỗi, giữ chính thì tốt, lợi có việc đi; được bề tôi (lòng người) không kể nhà riêng."],["上九鳥焚其巢旅人先笑後號咷喪牛于易凶","Thượng cửu: Điểu phần kỳ sào, lữ nhân tiên tiếu hậu hào đào. Táng ngưu vu dị, hung.","Chim bị cháy tổ, người lữ khách trước cười sau kêu khóc. Mất bò ở bờ ruộng (lúc dễ dàng không để ý), xấu."],["上六羝羊觸藩不能退不能遂无攸利艱則吉","Thượng lục: Đê dương xúc phiên, bất năng thoái, bất năng toại, vô du lợi; gian tắc cát.","Dê đực húc rào, không lùi được, không tiến được, không lợi gì; biết gian nan mà giữ thì tốt."],["九三鴻漸于陸夫征不復婦孕不育凶利禦寇","Cửu tam: Hồng tiệm vu lục, phu chinh bất phục, phụ dựng bất dục, hung; lợi ngự khấu.","Chim hồng tiến lên đất bằng; chồng đi không về, vợ có thai không nuôi được, xấu; lợi chống giặc."],["九三鼎耳革其行塞雉膏不食方雨虧悔終吉","Cửu tam: Đỉnh nhĩ cách, kỳ hành tắc, trĩ cao bất thực; phương vũ khuy hối, chung cát.","Quai vạc bị đổi (hỏng), khó di chuyển, mỡ chim trĩ không ai ăn; khi mưa xuống thì hối vơi đi, cuối cùng tốt."],["九二困于酒食朱紱方來利用亨祀征凶无咎","Cửu nhị: Khốn vu tửu thực, chu phất phương lai, lợi dụng hưởng tự; chinh hung, vô cữu.","Khốn vì rượu thịt (đủ ăn mà chí chưa thành), dải áo đỏ (người trên) sắp đến; lợi dùng việc tế lễ (thành tâm); đi thì xấu, không lỗi."],["九四貞吉悔亡震用伐鬼方三年有賞于大國","Cửu tứ: Trinh cát, hối vong. Chấn dụng phạt Quỷ Phương, tam niên hữu thưởng vu đại quốc.","Giữ chính thì tốt, hối mất. Ra sức đánh nước Quỷ Phương, ba năm được nước lớn ban thưởng."],["六三困于石據于蒺蔾入于其宮不見其妻凶","Lục tam: Khốn vu thạch, cứ vu tật lê, nhập vu kỳ cung, bất kiến kỳ thê, hung.","Khốn vì đá (trước mặt), dựa vào bụi gai tật lê, vào trong nhà không thấy vợ, xấu."],["六三无妄之災或繫之牛行人之得邑人之災","Lục tam: Vô vọng chi tai, hoặc hệ chi ngưu, hành nhân chi đắc, ấp nhân chi tai.","Tai họa không do mình gây: có người buộc con bò, kẻ qua đường dắt mất, người trong ấp bị vạ (bị nghi)."],["六二豐其蔀日中見斗往得疑疾有孚發若吉","Lục nhị: Phong kỳ bộ, nhật trung kiến đẩu; vãng đắc nghi tật, hữu phu phát nhược, cát.","Thịnh mà bị màn che dày, giữa trưa thấy sao Bắc đẩu; đi thì bị ngờ ghét; có lòng thành để khơi mở thì tốt."],["初六系于金柅貞吉有攸往見凶羸豕孚蹢躅","Sơ lục: Hệ vu kim nệ, trinh cát; hữu du vãng, kiến hung. Luy thỉ phu trịch trục.","Buộc vào cọc hãm xe bằng sắt, giữ chính thì tốt; nếu để đi, thấy xấu. Con heo gầy chắc chắn sẽ nhảy nhót (khi có dịp)."],["易有太極是生兩儀兩儀生四象四象生八卦","dịch hữu thái cực thị sinh lưỡng nghi lưỡng nghi sinh tứ tượng tứ tượng sinh bát quái","\"Dịch có Thái cực, sinh ra Lưỡng nghi"],["訟有孚窒惕中吉終凶利見大人不利涉大川","Tụng: Hữu phu, trất, dịch, trung cát, chung hung. Lợi kiến đại nhân, bất lợi thiệp đại xuyên.","Tụng: có lòng thành mà bị ngăn lấp, nên lo sợ; giữa chừng dừng lại thì tốt, theo đến cùng thì xấu. Lợi gặp bậc đại nhân, không lợi qua sông lớn."],["震亨震來虩虩笑言啞啞震驚百里不喪匕鬯","Chấn: Hanh. Chấn lai hích hích, tiếu ngôn ách ách. Chấn kinh bách lý, bất táng chủy sưởng.","Chấn: hanh thông. Sấm đến làm sợ hãi rụt rè, (sau đó) cười nói vui vẻ. Sấm làm kinh động trăm dặm, (người chủ tế) không đánh rơi muỗng và rượu tế."],["上九既雨既處尚得載婦貞厲月幾望君子征凶","Thượng cửu: Ký vũ ký xứ, thượng đắc tái; phụ trinh lệ. Nguyệt cơ vọng, quân tử chinh hung.","Mưa đã rơi, đã yên chỗ; đức được tích đầy. Đàn bà cố giữ thì nguy. Trăng gần rằm, quân tử đi thì xấu."],["九三井渫不食為我心惻可用汲王明並受其福","Cửu tam: Tỉnh tiết bất thực, vi ngã tâm trắc; khả dụng cấp, vương minh, tịnh thụ kỳ phúc.","Giếng đã vét trong mà không ai uống, khiến lòng ta xót xa; có thể múc dùng được; vua sáng suốt thì mọi người cùng được phúc."],["九三小人用壯君子用罔貞厲羝羊觸藩羸其角","Cửu tam: Tiểu nhân dụng tráng, quân tử dụng võng, trinh lệ. Đê dương xúc phiên, luy kỳ giác.","Tiểu nhân dùng sức mạnh, quân tử thì coi như không; cố giữ thì nguy. Dê đực húc rào, mắc kẹt sừng."],["九二鳴鶴在陰其子和之我有好爵吾與爾靡之","Cửu nhị: Minh hạc tại âm, kỳ tử họa chi. Ngã hữu hảo tước, ngô dữ nhĩ mỹ chi.","Hạc kêu trong bóng râm, hạc con họa theo. Ta có chén rượu ngon, ta cùng ngươi chia nhau."],["六三即鹿无虞惟入于林中君子幾不如舍往吝","Lục tam: Tức lộc vô ngu, duy nhập vu lâm trung; quân tử cơ, bất như xả, vãng lận.","Đuổi hươu mà không có người coi rừng dẫn đường, chỉ lạc vào giữa rừng; người quân tử thấy cơ, chẳng bằng bỏ đi, cứ đi thì đáng tiếc."],["其初難知其上易知本末也初辭擬之卒成之終","Kỳ sơ nan tri, kỳ thượng dị tri, bản mạt dã. Sơ từ nghĩ chi, tốt thành chi chung.","Bước đầu khó biết, bước cuối dễ biết, vì một đằng là gốc, một đằng là ngọn. Lời hào đầu chỉ mới ướm thử; đến hào cuối việc mới thành hình trọn vẹn."],["天在山中大畜君子以多識前言往行以畜其德","Thiên tại sơn trung, Đại Súc; quân tử dĩ đa thức tiền ngôn vãng hạnh, dĩ súc kỳ đức.","Trời ở trong núi là quẻ Đại Súc; người quân tử noi đó mà ghi nhớ nhiều lời nói, việc làm của người xưa để chứa đức của mình."],["夫婦之道不可以不久也故受之以恆恆者久也","phù phụ chi đạo bất khả dĩ bất cửu dã cố thụ chi dĩ hằng hằng giả cửu dã","Đạo vợ chồng không thể không bền lâu, nên tiếp bằng Hằng; Hằng là lâu."],["物穉不可不養也故受之以需需者飲食之道也","vật trĩ bất khả bất dưỡng dã cố thụ chi dĩ nhu nhu giả ẩm thực chi đạo dã","Vật non không thể không nuôi, nên tiếp bằng Nhu; Nhu là đạo ăn uống."],["上六豐其屋蔀其家窺其戶闃其无人三歲不觌凶","Thượng lục: Phong kỳ ốc, bộ kỳ gia, khuy kỳ hộ, khuých kỳ vô nhân, tam tuế bất địch, hung.","Nhà cửa to lớn, che kín cả nhà; nhòm qua cửa, vắng lặng không người, ba năm không thấy ai, xấu."],["二與四同功而異位其善不同二多譽四多懼近也","Nhị dữ tứ đồng công nhi dị vị, kỳ thiện bất đồng: nhị đa dự, tứ đa cụ, cận dã.","Hào Hai và hào Bốn cùng một loại vị trí nhưng khác chỗ, nên cái tốt khác nhau: hào Hai được khen nhiều, hào Bốn lo sợ nhiều, vì hào Bốn ở sát người trên."],["六三眇能視跛能履履虎尾咥人凶武人為于大君","Lục tam: Diểu năng thị, bả năng lý, lý hổ vĩ, điệt nhân, hung. Võ nhân vi vu đại quân.","Chột mà tưởng mình nhìn được, què mà tưởng mình đi được; giẫm đuôi hổ, bị hổ cắn, xấu. Kẻ võ biền muốn làm vua lớn."],["六五田有禽利執言无咎長子帥師弟子輿尸貞凶","Lục ngũ: Điền hữu cầm, lợi chấp ngôn, vô cữu. Trưởng tử suất sư, đệ tử dư thi, trinh hung.","Ruộng có thú (giặc vào bờ cõi), lợi nêu lời chính đáng mà đánh, không lỗi. Con trưởng cầm quân; nếu để kẻ em xen vào thì chở xác về, dù chính cũng xấu."],["占病者若得六沖卦近病不藥而愈久病妙藥難調","chiêm bệnh giả nhược đắc lục xung quái cận bệnh bất dược nhi dũ cửu bệnh diệu dược nan 調","bệnh mới gặp quẻ lục xung không thuốc cũng khỏi, bệnh lâu thì thuốc hay cũng khó"],["君子居則觀其象而玩其辭動則觀其變而玩其占","quân tử cư tắc quan kỳ tượng nhi ngoạn kỳ từ động tắc quan kỳ biến nhi ngoạn kỳ chiêm","lúc yên thì xem tượng, ngẫm lời"],["夬揚于王庭孚號有厲告自邑不利即戎利有攸往","Quải: Dương vu vương đình, phu hào, hữu lệ; cáo tự ấp, bất lợi tức nhung, lợi hữu du vãng.","Quải: tuyên bố ở sân vua, lấy lòng thành mà hiệu triệu, vẫn có nguy; báo cáo từ trong ấp mình, không lợi dùng binh, lợi có việc đi."],["萃王假有廟利見大人亨利貞用大牲吉利有攸往","Tụy: Vương cách hữu miếu, lợi kiến đại nhân, hanh, lợi trinh. Dụng đại sinh cát, lợi hữu du vãng.","Tụy: vua đến nhà tông miếu, lợi gặp bậc đại nhân, hanh thông, lợi về chính bền. Dùng lễ vật lớn thì tốt, lợi có việc đi."],["變出之爻能生克沖合本位之動爻不能生克他爻","biến xuất chi hào năng sinh khắc xung hợp bản vị chi động hào bất năng sinh khắc 他 hào","hào biến chỉ tác động hào động sinh ra nó"],["雷在地中復先王以至日閉關商旅不行后不省方","Lôi tại địa trung, Phục; tiên vương dĩ chí nhật bế quan, thương lữ bất hành, hậu bất tỉnh phương.","Sấm ở trong đất là quẻ Phục; các vua đời trước noi đó mà ngày Đông chí đóng cửa ải, khách buôn không đi lại, vua không đi xem xét các phương."],["九三壯于頄有凶君子夬夬獨行遇雨若濡有慍无咎","Cửu tam: Tráng vu cầu, hữu hung. Quân tử quải quải, độc hành ngộ vũ, nhược nhu hữu uấn, vô cữu.","Mạnh lộ ra ở gò má, có điều xấu. Người quân tử quyết đoán dứt khoát, một mình đi gặp mưa, bị ướt, bị người giận, nhưng không lỗi."],["六二或益之十朋之龜弗克違永貞吉王用享于帝吉","Lục nhị: Hoặc ích chi, thập bằng chi quy phất khắc vi, vĩnh trinh cát. Vương dụng hưởng vu đế, cát.","Có người làm ích cho, con rùa giá mười bằng cũng không thể từ chối; giữ chính lâu dài thì tốt. Vua dùng (người này) tế Thượng đế, tốt."],["六五帝乙歸妹其君之袂不如其娣之袂良月幾望吉","Lục ngũ: Đế Ất quy muội, kỳ quân chi duệ bất như kỳ đệ chi duệ lương; nguyệt cơ vọng, cát.","Vua Đế Ất gả em gái, tay áo của nàng (chính thất) không đẹp bằng tay áo của người em theo hầu; trăng gần rằm, tốt."],["初六有孚不終乃亂乃萃若號一握為笑勿恤往无咎","Sơ lục: Hữu phu bất chung, nãi loạn nãi tụy; nhược hào, nhất ác vi tiếu, vật tuất, vãng vô cữu.","Có lòng thành mà không giữ đến cùng, khi thì rối loạn khi thì tụ họp; nếu kêu lên (cầu người), thì một nắm tay đã cười vui lại; chớ lo, đi thì không lỗi."],["山上有雷小過君子以行過乎恭喪過乎哀用過乎儉","Sơn thượng hữu lôi, Tiểu Quá; quân tử dĩ hành quá hồ cung, tang quá hồ ai, dụng quá hồ kiệm.","Trên núi có sấm là quẻ Tiểu Quá; người quân tử noi đó mà việc làm hơi quá về cung kính, việc tang hơi quá về thương xót, việc tiêu dùng hơi quá về tiết kiệm."],["損有孚元吉无咎可貞利有攸往曷之用二簋可用享","Tổn: Hữu phu, nguyên cát, vô cữu, khả trinh, lợi hữu du vãng. Hạt chi dụng? Nhị quỹ khả dụng hưởng.","Tổn: có lòng thành thì rất tốt, không lỗi, có thể giữ chính, lợi có việc đi. Dùng gì để tế? Hai bát cơm cũng có thể dâng cúng."],["易簡而天下之理得矣天下之理得而成位乎其中矣","Dị giản, nhi thiên hạ chi lý đắc hĩ. Thiên hạ chi lý đắc, nhi thành vị hồ kỳ trung hĩ.","Dễ và giản thì được cái lý của thiên hạ. Được cái lý của thiên hạ thì (người) đứng vững được ở giữa (trời đất)."],["經世之未二千一百五十六甲辰唐帝堯肇位于平陽","kinh thế chi vị nhị thiên nhất bách ngũ thập lục giáp thìn 唐 đế nghiêu 肇 vị vu bình dương","vua Nghiêu lên ngôi năm Giáp Thìn trong thế 2156"],["聖人設卦觀象繫辭焉而明吉凶剛柔相推而生變化","Thánh nhân thiết quái quan tượng, hệ từ yên nhi minh cát hung; cương nhu tương thôi nhi sinh biến hóa.","Thánh nhân đặt ra quẻ, xem hình tượng, rồi gắn lời vào để làm rõ cát hung; cứng mềm đẩy nhau mà sinh ra biến hóa."],["雷出地奮豫先王以作樂崇德殷薦之上帝以配祖考","Lôi xuất địa phấn, Dự; tiên vương dĩ tác nhạc sùng đức, ân tiến chi thượng đế, dĩ phối tổ khảo.","Sấm ra khỏi đất vang dội là quẻ Dự; các vua đời trước noi đó mà làm nhạc để tôn đức, long trọng dâng lên Thượng đế, phối thờ cùng tổ tiên."],["九三无平不陂无往不復艱貞无咎勿恤其孚于食有福","Cửu tam: Vô bình bất bí, vô vãng bất phục, gian trinh vô cữu. Vật tuất kỳ phu, vu thực hữu phúc.","Không có chỗ bằng nào mà không nghiêng, không có đi nào mà không trở lại; trong gian nan giữ chính thì không lỗi. Đừng lo không được tin, cứ thế mà hưởng lộc có phúc."],["九五貞吉悔亡无不利无初有終先庚三日後庚三日吉","Cửu ngũ: Trinh cát hối vong, vô bất lợi. Vô sơ hữu chung. Tiên canh tam nhật, hậu canh tam nhật, cát.","Giữ chính thì tốt, hối mất, không gì không lợi. Lúc đầu không tốt mà cuối có kết quả. Trước ngày Canh ba ngày, sau ngày Canh ba ngày, tốt."],["倘若用神無根謂之元神有力亦難生忌神無力何足喜","倘 nhược dụng thần vô căn vị chi nguyên thần hữu lực diệc nan sinh kỵ thần vô lực hà túc hỉ","dụng thần không gốc thì nguyên thần có lực cũng khó sinh, kỵ thần vô lực cũng chẳng đáng mừng"],["天地交泰后以財成天地之道輔相天地之宜以左右民","Thiên địa giao, Thái; hậu dĩ tài thành thiên địa chi đạo, phụ tướng thiên địa chi nghi, dĩ tả hữu dân.","Trời đất giao nhau là quẻ Thái; bậc quân vương noi đó mà điều chỉnh cho thành đạo trời đất, giúp đỡ cho hợp lẽ trời đất, để nâng đỡ dân."],["復亨出入无疾朋來无咎反復其道七日來復利有攸往","Phục: Hanh. Xuất nhập vô tật, bằng lai vô cữu. Phản phục kỳ đạo, thất nhật lai phục, lợi hữu du vãng.","Phục: hanh thông. Ra vào không bệnh tật, bạn đến không lỗi. Trở đi trở lại theo đạo của nó, bảy ngày thì trở lại; lợi có việc đi."],["三與五同功而異位其遇不同三多凶五多功貴賤之等也","Tam dữ ngũ đồng công nhi dị vị, kỳ ngộ bất đồng: tam đa hung, ngũ đa công, quý tiện chi đẳng dã.","Hào Ba và hào Năm cùng loại vị trí nhưng khác chỗ, nên gặp phải khác nhau: hào Ba nhiều rủi, hào Năm nhiều công, vì một đằng thấp một đằng cao."],["六二屯如邅如乘馬班如匪寇婚媾女子貞不字十年乃字","Lục nhị: Truân như chiên như, thặng mã ban như; phỉ khấu hôn cấu. Nữ tử trinh bất tự, thập niên nãi tự.","Khó khăn, chần chừ, cưỡi ngựa mà dùng dằng; chẳng phải giặc cướp, mà là người cầu hôn. Con gái giữ trinh chưa hứa gả, mười năm mới hứa."],["凡用神元神宜於逢生月建生日建生動爻生動化回頭生","phàm dụng thần nguyên thần nghi ư 逢 sinh nguyệt kiến sinh nhật kiến sinh động hào sinh động hóa hồi đầu sinh","dụng thần, nguyên thần nên được sinh (tháng sinh, ngày sinh, hào động sinh, hóa hồi đầu sinh)"],["艮東北之卦也萬物之所成終而所成始也故曰成言乎艮","Cấn, đông bắc chi quái dã, vạn vật chi sở thành, chung nhi sở thành thủy dã, cố viết thành ngôn hồ Cấn.","Cấn là quẻ Đông Bắc, nơi muôn vật hoàn thành: kết thúc cái cũ mà khởi đầu cái mới, nên nói \"hoàn thành ở Cấn\"."],["蒙亨匪我求童蒙童蒙求我初筮告再三瀆瀆則不告利貞","Mông: Hanh. Phỉ ngã cầu đồng mông, đồng mông cầu ngã. Sơ phệ cốc, tái tam độc, độc tắc bất cốc. Lợi trinh.","Mông: hanh thông. Không phải ta tìm trẻ thơ dại, mà trẻ thơ dại tìm ta. Bói lần đầu thì bảo cho; hỏi lại hai ba lần là nhờn, nhờn thì không bảo. Lợi về chính bền."],["顯諸仁藏諸用鼓萬物而不與聖人同憂盛德大業至矣哉","Hiển chư nhân, tàng chư dụng, cổ vạn vật nhi bất dữ thánh nhân đồng ưu, thịnh đức đại nghiệp chí hĩ tai!","(Đạo) hiện ra ở lòng nhân, ẩn giấu trong công dụng; cổ động muôn vật mà không cùng lo như thánh nhân; đức thịnh, nghiệp lớn thật là tột bậc!"],["上六震索索視矍矍征凶震不于其躬于其鄰无咎婚媾有言","Thượng lục: Chấn tác tác, thị quặc quặc, chinh hung. Chấn bất vu kỳ cung, vu kỳ lân, vô cữu. Hôn cấu hữu ngôn.","Sấm làm run rẩy, mắt nhìn ngơ ngác, đi thì xấu. Sấm chưa đến thân mình mà mới đến láng giềng (đã biết răn), thì không lỗi. Người thân thích có lời chê trách."],["乾健也坤順也震動也巽入也坎陷也離麗也艮止也兌說也","Càn, kiện dã. Khôn, thuận dã. Chấn, động dã. Tốn, nhập dã. Khảm, hãm dã. Ly, lệ dã. Cấn, chỉ dã. Đoài, duyệt dã.","Càn là mạnh. Khôn là thuận. Chấn là động. Tốn là vào. Khảm là sa hãm. Ly là bám vào. Cấn là dừng. Đoài là vui."],["乾為首坤為腹震為足巽為股坎為耳離為目艮為手兌為口","Càn vi thủ, Khôn vi phúc, Chấn vi túc, Tốn vi cổ, Khảm vi nhĩ, Ly vi mục, Cấn vi thủ, Đoài vi khẩu.","Càn là đầu, Khôn là bụng, Chấn là chân, Tốn là đùi, Khảm là tai, Ly là mắt, Cấn là tay, Đoài là miệng."],["乾為馬坤為牛震為龍巽為雞坎為豕離為雉艮為狗兌為羊","Càn vi mã, Khôn vi ngưu, Chấn vi long, Tốn vi kê, Khảm vi thỉ, Ly vi trĩ, Cấn vi cẩu, Đoài vi dương.","Càn là ngựa, Khôn là trâu (bò), Chấn là rồng, Tốn là gà, Khảm là lợn, Ly là chim trĩ, Cấn là chó, Đoài là dê."],["井改邑不改井无喪无得往來井井汔至亦未繘井羸其瓶凶","Tỉnh: Cải ấp bất cải tỉnh, vô táng vô đắc, vãng lai tỉnh tỉnh. Ngật chí diệc vị duật tỉnh, luy kỳ bình, hung.","Tỉnh: đổi ấp mà không đổi giếng, không mất không được; người qua kẻ lại đều dùng giếng. Gần tới nơi mà dây chưa thả tới nước giếng, làm vỡ cái bình, xấu."],["初九明夷于飛垂其翼君子于行三日不食有攸往主人有言","Sơ cửu: Minh di vu phi, thùy kỳ dực. Quân tử vu hành, tam nhật bất thực; hữu du vãng, chủ nhân hữu ngôn.","Ánh sáng bị thương lúc bay, cụp cánh xuống. Quân tử ra đi, ba ngày không ăn; có việc đi thì chủ nhà có lời chê trách."],["小過亨利貞可小事不可大事飛鳥遺之音不宜上宜下大吉","Tiểu Quá: Hanh, lợi trinh. Khả tiểu sự, bất khả đại sự. Phi điểu di chi âm, bất nghi thượng nghi hạ, đại cát.","Tiểu Quá: hanh thông, lợi về chính bền. Có thể làm việc nhỏ, không thể làm việc lớn. Chim bay để lại tiếng kêu, không nên bay lên mà nên xuống, rất tốt."],["故水火相逮雷風不相悖山澤通氣然後能變化既成萬物也","Cố thủy hỏa tương đãi, lôi phong bất tương bội, sơn trạch thông khí, nhiên hậu năng biến hóa, ký thành vạn vật dã.","Cho nên nước lửa với tới nhau, sấm gió không trái nhau, núi đầm thông khí với nhau, sau đó mới biến hóa được và làm thành muôn vật."],["二多譽四多懼近也柔之為道不利近者其要無咎其用柔中也","Nhị đa dự, tứ đa cụ, cận dã. Nhu chi vi đạo, bất lợi cận giả, kỳ yếu vô cữu, kỳ dụng nhu trung dã.","Hào Hai được khen nhiều, hào Bốn lo sợ nhiều, vì ở sát người trên. Cái mềm thì không lợi khi ở sát; cốt sao không lỗi, nhờ biết mềm mà giữ mức."],["天地變化草木蕃天地閉賢人隱易曰括囊无咎无譽蓋言謹也","Thiên địa biến hóa, thảo mộc phồn; thiên địa bế, hiền nhân ẩn. Dịch viết: \"Quát nang, vô cữu, vô dự.\" Cái ngôn cẩn dã.","Trời đất biến hóa thì cỏ cây tươi tốt; trời đất bế tắc thì người hiền ẩn mình. Dịch nói \"thắt miệng túi, không lỗi, không khen\" là nói về sự cẩn trọng."],["日月如天能生克動爻靜爻變爻飛爻伏爻而諸爻不能傷日月","nhật nguyệt như thiên năng sinh khắc động hào tĩnh hào biến hào phi hào phục hào nhi chư hào bất năng thương nhật nguyệt","nhật nguyệt như trời, sinh khắc được mọi hào mà không hào nào hại được"],["盈天地之間者唯萬物故受之以屯屯者盈也屯者物之始生也","doanh thiên địa chi gián giả duy vạn vật cố thụ chi dĩ truân truân giả doanh dã truân giả vật chi thủy sinh dã","Đầy khoảng trời đất chỉ có muôn vật, nên tiếp bằng Truân; Truân là đầy, là lúc vật mới sinh."],["一念只占一事不妨早占晚占心懷兩三事者半夜求神亦有錯矣","nhất niệm chỉ chiêm nhất sự bất 妨 tảo chiêm vãn chiêm tâm hoài lưỡng tam sự giả bán dạ cầu thần diệc hữu thác hĩ","một niệm chỉ hỏi một việc, sớm hỏi tối hỏi không sao, chứ ôm hai ba việc một lúc thì nửa đêm cầu thần cũng sai"],["知幾其神乎幾者動之微吉之先見者也君子見幾而作不俟終日","tri cơ kỳ thần hồ cơ giả động chi vi cát chi tiên kiến giả dã quân tử kiến cơ nhi tác bất sĩ chung nhật","“Biết cơ thì thần diệu thay! … Cơ là cái nhỏ nhặt của sự động, là cái điềm tốt hiện ra trước"],["萬物出乎震震東方也齊乎巽巽東南也齊也者言萬物之潔齊也","Vạn vật xuất hồ Chấn, Chấn, đông phương dã. Tề hồ Tốn, Tốn, đông nam dã; tề dã giả, ngôn vạn vật chi khiết tề dã.","Muôn vật ra ở Chấn; Chấn là phương Đông. Đều đặn ở Tốn; Tốn là Đông Nam; \"tề\" là nói muôn vật sạch sẽ, đều đặn."],["上六迷復凶有災眚用行師終有大敗以其國君凶至于十年不克征","Thượng lục: Mê phục, hung, hữu tai sảnh. Dụng hành sư, chung hữu đại bại, dĩ kỳ quốc quân, hung; chí vu thập niên bất khắc chinh.","Mê muội không quay về, xấu, có tai họa. Dùng quân thì cuối cùng thua lớn, vạ lây đến vua, xấu; đến mười năm cũng không thể ra quân."],["君子黃中通理正位居體美在其中而暢於四支發於事業美之至也","Quân tử hoàng trung thông lý, chính vị cư thể, mỹ tại kỳ trung, nhi sướng ư tứ chi, phát ư sự nghiệp, mỹ chi chí dã.","Quân tử có đức trung (màu vàng) bên trong mà thông suốt lý lẽ, ở đúng ngôi, giữ đúng thể; vẻ đẹp ở bên trong mà tràn ra tay chân, phát ra thành sự nghiệp – đó là cái đẹp tột bậc."],["九三重剛而不中上不在天下不在田故乾乾因其時而惕雖危无咎矣","Cửu tam, trùng cương nhi bất trung, thượng bất tại thiên, hạ bất tại điền; cố càn càn nhân kỳ thời nhi dịch, tuy nguy, vô cữu hĩ.","Cửu tam là cứng chồng cứng mà không ở giữa, trên chưa tới trời, dưới không còn ở ruộng; cho nên hăng hái theo thời mà lo sợ, tuy nguy mà không lỗi."],["兌為澤為少女為巫為口舌為毀折為附決其於地也為剛鹵為妾為羊","Đoài vi trạch, vi thiếu nữ, vi vu, vi khẩu thiệt, vi hủy chiết, vi phụ quyết. Kỳ ư địa dã, vi cương lỗ, vi thiếp, vi dương.","Đoài là đầm, là gái út, là đồng cốt, là miệng lưỡi, là hủy gãy, là bám vào mà quyết tách ra. Với đất thì là đất cứng mặn; là vợ lẽ, là dê."],["兼三才而兩之故易六畫而成卦分陰分陽迭用柔剛故易六位而成章","Kiêm tam tài nhi lưỡng chi, cố Dịch lục họa nhi thành quái. Phân âm phân dương, điệt dụng nhu cương, cố Dịch lục vị nhi thành chương.","Gồm ba tài mà nhân đôi, nên Dịch sáu vạch thành một quẻ. Chia ngôi âm ngôi dương, dùng xen kẽ nhu và cương, nên Dịch có sáu ngôi mà thành văn vẻ."],["損益盛衰之始也大畜時也无妄災也萃聚而升不來也謙輕而豫怠也","Tổn Ích, thịnh suy chi thủy dã. Đại Súc thời dã, Vô Vọng tai dã. Tụy tụ, nhi Thăng bất lai dã. Khiêm khinh, nhi Dự đãi dã.","Tổn và Ích là khởi đầu của suy và thịnh. Đại Súc là gặp thời, Vô Vọng là tai họa (bất ngờ). Tụy là tụ lại, còn Thăng là đi lên không trở lại. Khiêm là coi nhẹ mình, còn Dự là lười nhác."],["是故剛柔相摩八卦相荡鼓之以雷霆潤之以風雨日月運行一寒一暑","Thị cố cương nhu tương ma, bát quái tương đãng, cổ chi dĩ lôi đình, nhuận chi dĩ phong vũ, nhật nguyệt vận hành, nhất hàn nhất thử.","Cho nên cứng mềm cọ xát nhau, tám quẻ xô đẩy nhau; lấy sấm sét mà làm cho động, lấy gió mưa mà thấm nhuần; mặt trời mặt trăng vận hành, một lạnh một nóng."],["上九睽孤見豕負涂載鬼一車先張之弧後說之弧匪寇婚媾往遇雨則吉","Thượng cửu: Khuê cô, kiến thỉ phụ đồ, tái quỷ nhất xa, tiên trương chi hồ, hậu thoát chi hồ; phỉ khấu hôn cấu, vãng ngộ vũ tắc cát.","Chia lìa cô độc, thấy con heo đội bùn, một xe đầy ma; trước giương cung, sau buông cung; chẳng phải giặc cướp mà là người cầu hôn; đi gặp mưa thì tốt."],["亢龍有悔子曰貴而无位高而无民賢人在下位而无輔是以動而有悔也","\"Kháng long hữu hối.\" Tử viết: \"Quý nhi vô vị, cao nhi vô dân, hiền nhân tại hạ vị nhi vô phụ, thị dĩ động nhi hữu hối dã.\"","\"Rồng lên quá cao, có hối.\" (hào Thượng cửu quẻ Càn). Khổng Tử nói: \"Sang mà không có ngôi thực, cao mà không có dân theo, người hiền ở dưới mà không giúp, cho nên hễ động là có hối.\""],["帝出乎震齊乎巽相見乎離致役乎坤說言乎兌戰乎乾勞乎坎成言乎艮","Đế xuất hồ Chấn, tề hồ Tốn, tương kiến hồ Ly, trí dịch hồ Khôn, duyệt ngôn hồ Đoài, chiến hồ Càn, lao hồ Khảm, thành ngôn hồ Cấn.","Chủ tể (sinh khí) ra ở Chấn, làm cho đều đặn ở Tốn, cho thấy nhau ở Ly, dốc sức nuôi dưỡng ở Khôn, vui vẻ ở Đoài, giao chiến ở Càn, mỏi mệt (quy về nghỉ) ở Khảm, hoàn thành ở Cấn."],["坤元亨利牝馬之貞君子有攸往先迷後得主利西南得朋東北喪朋安貞吉","Khôn: Nguyên hanh, lợi tẫn mã chi trinh. Quân tử hữu du vãng, tiên mê hậu đắc chủ. Lợi tây nam đắc bằng, đông bắc táng bằng. An trinh, cát.","Khôn: khởi đầu lớn, hanh thông, lợi về sự chính bền như ngựa cái. Người quân tử có việc đi: đi trước thì lạc, theo sau thì được người làm chủ. Lợi ở tây nam được bạn, đông bắc mất bạn. Yên lòng giữ chính thì tốt."],["是故易有太極是生兩儀兩儀生四象四象生八卦八卦定吉凶吉凶生大業","Thị cố Dịch hữu Thái cực, thị sinh Lưỡng nghi, Lưỡng nghi sinh Tứ tượng, Tứ tượng sinh Bát quái, Bát quái định cát hung, cát hung sinh đại nghiệp.","Cho nên Dịch có Thái cực, Thái cực sinh ra Lưỡng nghi (âm, dương); Lưỡng nghi sinh ra Tứ tượng; Tứ tượng sinh ra Bát quái; Bát quái định cát hung; cát hung sinh ra sự nghiệp lớn."],["經元之甲一經會之午七經運之辛一百八十八經世之子二千二百四十五","kinh nguyên chi giáp nhất kinh hội chi ngọ thất kinh vận chi tân nhất bách bát thập bát kinh thế chi tử nhị thiên nhị bách tứ thập ngũ","nghĩa là: Nguyên Giáp thứ 1, Hội Ngọ thứ 7, Vận Tân thứ 188, Thế Tý thứ 2245 (quyển 6 trung)"],["九四重剛而不中上不在天下不在田中不在人故或之或之者疑之也故无咎","Cửu tứ, trùng cương nhi bất trung, thượng bất tại thiên, hạ bất tại điền, trung bất tại nhân, cố hoặc chi. Hoặc chi giả, nghi chi dã, cố vô cữu.","Cửu tứ là cứng chồng cứng mà không ở giữa, trên chưa tới trời, dưới không ở ruộng, giữa không ở chỗ người; cho nên nói \"hoặc\". \"Hoặc\" là còn ngờ, (vì biết ngờ mà thận trọng) nên không lỗi."],["君子學以聚之問以辯之寬以居之仁以行之易曰見龍在田利見大人君德也","Quân tử học dĩ tụ chi, vấn dĩ biện chi, khoan dĩ cư chi, nhân dĩ hành chi. Dịch viết: \"Hiện long tại điền, lợi kiến đại nhân.\" Quân đức dã.","Quân tử học để gom góp (hiểu biết), hỏi để phân biệt, rộng lượng để ở, lấy nhân mà làm. Dịch nói \"rồng hiện ở ruộng, lợi gặp đại nhân\" – ấy là đức của bậc quân vương."],["夫易廣矣大矣以言乎遠則不禦以言乎邇則靜而正以言乎天地之間則備矣","Phù Dịch, quảng hĩ! Đại hĩ! Dĩ ngôn hồ viễn tắc bất ngự, dĩ ngôn hồ nhĩ tắc tĩnh nhi chính, dĩ ngôn hồ thiên địa chi gian tắc bị hĩ!","Dịch thật rộng thay, lớn thay! Nói về xa thì không gì ngăn được; nói về gần thì yên tĩnh mà ngay chính; nói về khoảng giữa trời đất thì đầy đủ cả."],["易无思也无為也寂然不動感而遂通天下之故非天下之至神其孰能與於此","Dịch, vô tư dã, vô vi dã, tịch nhiên bất động, cảm nhi toại thông thiên hạ chi cố. Phi thiên hạ chi chí thần, kỳ thục năng dự ư thử!","Dịch không suy nghĩ, không làm gì, lặng yên bất động; có cảm thì thông suốt mọi lẽ của thiên hạ. Nếu không phải là cái thần diệu bậc nhất thiên hạ thì sao dự được vào việc này!"],["陰雖有美含之以從王事弗敢成也地道也妻道也臣道也地道无成而代有終也","Âm tuy hữu mỹ, hàm chi. Dĩ tòng vương sự, phất cảm thành dã. Địa đạo dã, thê đạo dã, thần đạo dã. Địa đạo vô thành, nhi đại hữu chung dã.","Âm tuy có vẻ đẹp, nhưng ngậm giữ lại; để theo việc của vua, không dám nhận phần thành công. Đó là đạo của đất, đạo của vợ, đạo của bề tôi. Đạo đất không nhận phần thành, mà thay (trời) làm cho trọn vẹn đến cuối."],["離也者明也萬物皆相見南方之卦也聖人南面而聽天下嚮明而治蓋取諸此也","Ly dã giả, minh dã, vạn vật giai tương kiến, nam phương chi quái dã. Thánh nhân nam diện nhi thính thiên hạ, hướng minh nhi trị, cái thủ chư thử dã.","Ly là sáng; muôn vật đều thấy rõ nhau; là quẻ của phương Nam. Thánh nhân quay mặt về Nam mà nghe việc thiên hạ, hướng về chỗ sáng mà cai trị, là lấy ý ở đây."],["雷以動之風以散之雨以潤之日以烜之艮以止之兌以說之乾以君之坤以藏之","Lôi dĩ động chi, phong dĩ tán chi, vũ dĩ nhuận chi, nhật dĩ huyên chi, Cấn dĩ chỉ chi, Đoài dĩ duyệt chi, Càn dĩ quân chi, Khôn dĩ tàng chi.","Sấm để làm động, gió để làm tan tỏa, mưa để thấm nhuần, mặt trời để hong ấm, Cấn để làm dừng, Đoài để làm vui, Càn để làm chủ, Khôn để tàng chứa."],["乾剛坤柔比樂師憂臨觀之義或與或求屯見而不失其居蒙雜而著震起也艮止也","Càn cương Khôn nhu, Tỷ lạc Sư ưu. Lâm Quan chi nghĩa, hoặc dữ hoặc cầu. Truân hiện nhi bất thất kỳ cư, Mông tạp nhi trứ. Chấn khởi dã, Cấn chỉ dã.","Càn cứng, Khôn mềm; Tỷ vui, Sư lo. Nghĩa của Lâm và Quan: một bên ban cho, một bên tìm kiếm. Truân là hiện ra mà không mất chỗ đứng; Mông là lẫn lộn rồi sáng tỏ. Chấn là dấy lên, Cấn là dừng lại."],["君子以成德為行日可見之行也潛之為言也隱而未見行而未成是以君子弗用也","Quân tử dĩ thành đức vi hạnh, nhật khả kiến chi hạnh dã. Tiềm chi vi ngôn dã, ẩn nhi vị hiện, hành nhi vị thành, thị dĩ quân tử phất dụng dã.","Quân tử lấy việc thành đức làm hành động, là hành động có thể thấy hằng ngày. Chữ \"tiềm\" nghĩa là ẩn mà chưa hiện, làm mà chưa thành, nên quân tử chưa dùng."],["坤也者地也萬物皆致養焉故曰致役乎坤兌正秋也萬物之所說也故曰說言乎兌","Khôn dã giả, địa dã, vạn vật giai trí dưỡng yên, cố viết trí dịch hồ Khôn. Đoài, chính thu dã, vạn vật chi sở duyệt dã, cố viết duyệt ngôn hồ Đoài.","Khôn là đất, muôn vật đều được nuôi dưỡng ở đó, nên nói \"dốc sức ở Khôn\". Đoài là giữa mùa thu, lúc muôn vật vui (vì kết quả), nên nói \"vui ở Đoài\"."],["坤為地為母為布為釜為吝嗇為均為子母牛為大輿為文為眾為柄其於地也為黑","Khôn vi địa, vi mẫu, vi bố, vi phủ, vi lận sắc, vi quân, vi tử mẫu ngưu, vi đại dư, vi văn, vi chúng, vi bính. Kỳ ư địa dã vi hắc.","Khôn là đất, là mẹ, là vải, là nồi, là keo kiệt, là đều bằng, là bò mẹ con, là xe lớn, là văn vẻ, là đông người, là cán (chuôi). Với đất thì là màu đen."],["是以明於天之道而察於民之故是興神物以前民用聖人以此齊戒以神明其德夫","Thị dĩ minh ư thiên chi đạo, nhi sát ư dân chi cố, thị hưng thần vật dĩ tiền dân dụng; thánh nhân dĩ thử trai giới dĩ thần minh kỳ đức phù!","Vì vậy (thánh nhân) sáng tỏ đạo trời, xét rõ việc của dân, bèn dấy lên vật thiêng (cỏ thi, mai rùa) để dẫn đường trước cho dân dùng. Thánh nhân lấy đó mà trai giới, làm cho đức mình sáng suốt thần diệu vậy!"],["坤至柔而動也剛至靜而德方後得主而有常含萬物而化光坤道其順乎承天而時行","Khôn chí nhu nhi động dã cương, chí tĩnh nhi đức phương. Hậu đắc chủ nhi hữu thường, hàm vạn vật nhi hóa quang. Khôn đạo kỳ thuận hồ! Thừa thiên nhi thời hành.","Khôn rất mềm mà khi động thì cứng; rất tĩnh mà đức thì vuông vức. Theo sau thì được người làm chủ và có lẽ thường; bao chứa muôn vật mà công hóa dục sáng rỡ. Đạo Khôn là thuận chăng! Vâng theo trời mà làm đúng thời."],["子孫福德之神爲制鬼之神爲解憂之神爲剝官之神諸事見之爲喜獨占功名者忌之","tử tôn phúc đức chi thần vi chế quỷ chi thần vi giải ưu chi thần vi bác quan chi thần chư sự kiến chi vi hỉ độc chiêm công danh giả kỵ chi","thần phúc đức, chế được quỷ, giải lo, nhưng cũng \"bóc quan\", nên riêng hỏi công danh thì kỵ"],["上九曰亢龍有悔何謂也子曰貴而无位高而无民賢人在下位而无輔是以動而有悔也","Thượng cửu viết: \"Kháng long, hữu hối.\" Hà vị dã? Tử viết: \"Quý nhi vô vị, cao nhi vô dân, hiền nhân tại hạ vị nhi vô phụ, thị dĩ động nhi hữu hối dã.\"","Hào Thượng cửu nói: \"Rồng lên quá cao, có hối.\" Nghĩa là gì? Khổng Tử nói: \"Sang mà không có ngôi, cao mà không có dân, người hiền ở dưới mà không giúp mình, cho nên động thì có hối.\""],["乾為天為圜為君為父為玉為金為寒為冰為大赤為良馬為老馬為瘠馬為駁馬為木果","Càn vi thiên, vi viên, vi quân, vi phụ, vi ngọc, vi kim, vi hàn, vi băng, vi đại xích, vi lương mã, vi lão mã, vi tích mã, vi bác mã, vi mộc quả.","Càn là trời, là hình tròn, là vua, là cha, là ngọc, là kim loại, là lạnh, là băng, là màu đỏ thắm, là ngựa tốt, ngựa già, ngựa gầy, ngựa vằn (ngựa dữ), là quả trên cây."],["噬嗑食也賁无色也兌見而巽伏也隨无故也蠱則飭也剝爛也復反也晉晝也明夷誅也","Phệ Hạp thực dã, Bí vô sắc dã. Đoài hiện, nhi Tốn phục dã. Tùy vô cố dã, Cổ tắc sức dã. Bác lạn dã, Phục phản dã. Tấn trú dã, Minh Di tru dã.","Phệ Hạp là ăn (cắn hợp); Bí là không màu (vẻ đẹp mộc). Đoài là lộ ra, còn Tốn là ẩn nấp. Tùy là bỏ cái cũ (không giữ việc cũ), Cổ là chỉnh sửa. Bác là mục nát, Phục là trở về. Tấn là ban ngày, Minh Di là bị tổn hại."],["天地定位山澤通氣雷風相薄水火不相射八卦相錯數往者順知來者逆是故易逆數也","Thiên địa định vị, sơn trạch thông khí, lôi phong tương bạc, thủy hỏa bất tương xạ. Bát quái tương thác, số vãng giả thuận, tri lai giả nghịch. Thị cố Dịch nghịch số dã.","Trời đất định ngôi, núi đầm thông khí, sấm gió xô nhau, nước lửa không bắn phá nhau. Tám quẻ đan xen nhau; đếm cái đã qua là thuận, biết cái sắp tới là ngược. Cho nên Dịch là phép đếm ngược."],["是故易者象也象也者像也彖者材也爻也者效天下之動者也是故吉凶生而悔吝著也","Thị cố Dịch giả, tượng dã. Tượng dã giả, tượng dã. Thoán giả, tài dã. Hào dã giả, hiệu thiên hạ chi động giả dã. Thị cố cát hung sinh nhi hối lận trứ dã.",""],["天地之大德曰生聖人之大寶曰位何以守位曰仁何以聚人曰財理財正辭禁民為非曰義","Thiên địa chi đại đức viết sinh, thánh nhân chi đại bảo viết vị, hà dĩ thủ vị viết nhân, hà dĩ tụ nhân viết tài, lý tài chính từ, cấm dân vi phi viết nghĩa.","Đức lớn của trời đất là sinh; của báu lớn của thánh nhân là ngôi vị. Lấy gì giữ ngôi? Là nhân. Lấy gì tụ người? Là của cải. Quản lý của cải, chính đáng lời lẽ, ngăn dân làm điều sai, gọi là nghĩa."],["履以和行謙以制禮復以自知恒以一德損以遠害益以興利困以寡怨井以辯義巽以行權","Lý, dĩ hòa hành. Khiêm, dĩ chế lễ. Phục, dĩ tự tri. Hằng, dĩ nhất đức. Tổn, dĩ viễn hại. Ích, dĩ hưng lợi. Khốn, dĩ quả oán. Tỉnh, dĩ biện nghĩa. Tốn, dĩ hành quyền.","Lý để hành động hòa nhã. Khiêm để điều tiết lễ. Phục để tự biết mình. Hằng để giữ đức trước sau như một. Tổn để tránh xa tai hại. Ích để làm hưng lợi. Khốn để ít oán trách. Tỉnh để phân biệt điều nghĩa. Tốn để biết quyền biến."],["將叛者其辭慚中心疑者其辭枝吉人之辭寡躁人之辭多誣善之人其辭游失其守者其辭屈","Tương bạn giả kỳ từ tàm, trung tâm nghi giả kỳ từ chi; cát nhân chi từ quả, táo nhân chi từ đa; vu thiện chi nhân kỳ từ du, thất kỳ thủ giả kỳ từ khuất.","Kẻ sắp phản bội thì lời nói ngượng ngùng; kẻ trong lòng ngờ vực thì lời nói rẽ nhánh; người tốt thì lời ít; người nóng nảy thì lời nhiều; kẻ vu khống người lành thì lời trôi nổi; kẻ mất chỗ giữ (mất lập trường) thì lời nói cong khuất."],["艮為山為徑路為小石為門闕為果蓏為閽寺為指為狗為鼠為黔喙之屬其於木也為堅多節","Cấn vi sơn, vi kính lộ, vi tiểu thạch, vi môn khuyết, vi quả lỏa, vi hôn tự, vi chỉ, vi cẩu, vi thử, vi kiềm uế chi thuộc. Kỳ ư mộc dã, vi kiên đa tiết.","Cấn là núi, là đường tắt nhỏ, là đá nhỏ, là cổng cửa, là quả trên cây và dưa dưới đất, là người giữ cửa, là ngón tay, là chó, là chuột, là loài chim mỏ đen. Với cây thì là cây cứng nhiều mắt."],["乾坤其易之縕邪乾坤成列而易立乎其中矣乾坤毀則无以見易易不可見則乾坤或幾乎息矣","Càn Khôn, kỳ Dịch chi uẩn da! Càn Khôn thành liệt, nhi Dịch lập hồ kỳ trung hĩ. Càn Khôn hủy, tắc vô dĩ kiến Dịch; Dịch bất khả kiến, tắc Càn Khôn hoặc cơ hồ tức hĩ.","Càn Khôn là chỗ chứa đựng của Dịch chăng! Càn Khôn bày thành hàng thì Dịch đứng ở giữa. Càn Khôn bị hủy thì không lấy gì thấy được Dịch; Dịch không thấy được thì Càn Khôn cũng gần như ngừng nghỉ."],["井通而困相遇也咸速也恒久也渙離也節止也解緩也蹇難也睽外也家人內也否泰反其類也","Tỉnh thông, nhi Khốn tương ngộ dã. Hàm tốc dã, Hằng cửu dã. Hoán ly dã, Tiết chỉ dã. Giải hoãn dã, Kiển nạn dã. Khuê ngoại dã, Gia Nhân nội dã. Bĩ Thái, phản kỳ loại dã.","Tỉnh là thông suốt, còn Khốn là gặp phải (trở ngại). Hàm là nhanh, Hằng là lâu. Hoán là lìa tan, Tiết là dừng lại. Giải là thư thả, Kiển là khó khăn. Khuê là hướng ra ngoài (xa cách), Gia Nhân là hướng vào trong. Bĩ và Thái là trái ngược loại nhau."],["八卦成列象在其中矣因而重之爻在其中矣剛柔相推變在其中矣繫辭焉而命之動在其中矣","Bát quái thành liệt, tượng tại kỳ trung hĩ; nhân nhi trùng chi, hào tại kỳ trung hĩ; cương nhu tương suy, biến tại kỳ trung hĩ; hệ từ yên nhi mệnh chi, động tại kỳ trung hĩ.","Tám quái bày thành hàng thì tượng ở trong đó; nhân đó mà chồng lên nhau thì hào ở trong đó; cương nhu đẩy nhau thì biến ở trong đó; buộc lời vào mà chỉ bảo thì sự động ở trong đó."],["參伍以變錯綜其數通其變遂成天下之文極其數遂定天下之象非天下之至變其孰能與於此","Tham ngũ dĩ biến, thác tổng kỳ số, thông kỳ biến, toại thành thiên hạ chi văn; cực kỳ số, toại định thiên hạ chi tượng; phi thiên hạ chi chí biến, kỳ thục năng dự ư thử!","Lấy ba lấy năm mà biến đổi, đan xen tổng hợp các con số; thông suốt sự biến thì thành văn vẻ của thiên hạ; đi tới cùng các con số thì định được hình tượng của thiên hạ. Nếu không phải là cái biến hóa bậc nhất thiên hạ thì sao dự được vào việc này!"],["同人先號咷而後笑子曰君子之道或出或處或默或語二人同心其利斷金同心之言其臭如蘭","\"Đồng nhân, tiên hào đào nhi hậu tiếu.\" Tử viết: \"Quân tử chi đạo, hoặc xuất hoặc xử, hoặc mặc hoặc ngữ. Nhị nhân đồng tâm, kỳ lợi đoạn kim. Đồng tâm chi ngôn, kỳ xú như lan.\"","\"Hòa đồng với người, trước kêu khóc mà sau cười.\" (hào Cửu ngũ quẻ Đồng Nhân). Khổng Tử nói: \"Đạo của người quân tử, khi ra làm việc khi ở ẩn, khi im lặng khi lên tiếng (bề ngoài khác nhau). Hai người cùng một lòng thì sắc bén chặt đứt cả kim loại. Lời của những người cùng lòng thơm như hoa lan.\""],["八純卦自初爻續變至五爻返變四爻成遊魂卦內卦再變八純成歸魂卦此八者構成各宮八卦象","bát thuần quái tự sơ hào tục biến chí ngũ hào phản biến tứ hào thành du hồn quái nội quái tái biến bát thuần thành quy hồn quái thử bát giả cấu thành các cung bát quái tượng","quẻ thuần biến hào 1 đến hào 5 được năm quẻ (nhất thế … ngũ thế), quay lại biến hào 4 được quẻ"],["子曰德薄而位尊知小而謀大力小而任重鮮不及矣易曰鼎折足覆公餗其形渥凶言不勝其任也","Tử viết: \"Đức bạc nhi vị tôn, trí tiểu nhi mưu đại, lực tiểu nhi nhiệm trọng, tiển bất cập hĩ. Dịch viết: 'Đỉnh chiết túc, phúc công tốc, kỳ hình ốc, hung.' Ngôn bất thăng kỳ nhiệm dã.\"","Khổng Tử nói: \"Đức mỏng mà ngôi cao, trí nhỏ mà mưu lớn, sức yếu mà gánh nặng, ít khi không gặp họa. Dịch nói: 'Vạc gãy chân, đổ thức ăn của bậc công, thân bị ướt bẩn, hung' (hào Cửu tứ quẻ Đỉnh), ý nói không kham nổi trách nhiệm.\""],["彖者言乎象者也爻者言乎變者也吉凶者言乎其失得也悔吝者言乎其小疵也无咎者善補過也","Thoán giả, ngôn hồ tượng giả dã. Hào giả, ngôn hồ biến giả dã. Cát hung giả, ngôn hồ kỳ thất đắc dã. Hối lận giả, ngôn hồ kỳ tiểu tì dã. Vô cữu giả, thiện bổ quá dã.","Lời thoán là nói về tượng (của cả quẻ). Lời hào là nói về sự biến. Cát hung là nói về chỗ được mất. Hối lận là nói về vết lỗi nhỏ. Vô cữu là khéo bù đắp lỗi lầm."],["復則不妄矣故受之以无妄有无妄然後可畜故受之以大畜物畜然後可養故受之以頤頤者養也","Phục tắc bất vọng hĩ, cố thụ chi dĩ Vô Vọng. Hữu vô vọng nhiên hậu khả súc, cố thụ chi dĩ Đại Súc. Vật súc nhiên hậu khả dưỡng, cố thụ chi dĩ Di; Di giả dưỡng dã.","Trở về (đạo chính) thì không càn bậy, nên tiếp bằng Vô Vọng. Có sự không càn bậy rồi mới tích chứa được, nên tiếp bằng Đại Súc. Vật tích chứa rồi mới nuôi được, nên tiếp bằng Di; Di là nuôi."],["戰乎乾乾西北之卦也言陰陽相薄也坎者水也正北方之卦也勞卦也萬物之所歸也故曰勞乎坎","Chiến hồ Càn, Càn, tây bắc chi quái dã, ngôn âm dương tương bạc dã. Khảm giả, thủy dã, chính bắc phương chi quái dã, lao quái dã, vạn vật chi sở quy dã, cố viết lao hồ Khảm.","Giao chiến ở Càn; Càn là quẻ Tây Bắc, nói âm dương xô xát nhau. Khảm là nước, là quẻ chính Bắc, là quẻ mỏi mệt, chỗ muôn vật trở về, nên nói \"mỏi mệt ở Khảm\"."],["直其正也方其義也君子敬以直內義以方外敬義立而德不孤直方大不習无不利則不疑其所行也","Trực kỳ chính dã, phương kỳ nghĩa dã. Quân tử kính dĩ trực nội, nghĩa dĩ phương ngoại, kính nghĩa lập nhi đức bất cô. \"Trực phương đại, bất tập vô bất lợi.\" Tắc bất nghi kỳ sở hành dã.","\"Thẳng\" là sự chính trực; \"vuông\" là sự hợp nghĩa. Quân tử lấy kính để giữ bên trong ngay thẳng, lấy nghĩa để giữ bên ngoài vuông vức; kính và nghĩa đã lập thì đức không cô độc. \"Thẳng, vuông, lớn, không tập mà không gì không lợi\" – tức là không còn ngờ vực điều mình làm."],["不養則不可動故受之以大過物不可以終過故受之以坎坎者陷也陷必有所麗故受之以離離者麗也","Bất dưỡng tắc bất khả động, cố thụ chi dĩ Đại Quá. Vật bất khả dĩ chung quá, cố thụ chi dĩ Khảm; Khảm giả hãm dã. Hãm tất hữu sở lệ, cố thụ chi dĩ Ly; Ly giả lệ dã.","Không nuôi thì không động được, nên tiếp bằng Đại Quá. Vật không thể mãi quá mức, nên tiếp bằng Khảm; Khảm là sa hãm. Sa hãm thì ắt phải có chỗ bám, nên tiếp bằng Ly; Ly là bám vào."],["斷木為杵掘地為臼臼杵之利萬民以濟蓋取諸小過弦木為弧剡木為矢弧矢之利以威天下蓋取諸睽","Đoạn mộc vi chử, quật địa vi cữu, cữu chử chi lợi, vạn dân dĩ tế, cái thủ chư Tiểu Quá. Huyền mộc vi hồ, diệm mộc vi thỉ, hồ thỉ chi lợi, dĩ uy thiên hạ, cái thủ chư Khuê.","Chặt gỗ làm chày, đào đất làm cối; cái lợi của chày cối giúp được muôn dân, có lẽ lấy ý ở quẻ Tiểu Quá. Căng dây lên gỗ làm cung, vót gỗ làm tên; cái lợi của cung tên là để ra oai với thiên hạ, có lẽ lấy ý ở quẻ Khuê."],["昔者聖人之作易也將以順性命之理是以立天之道曰陰與陽立地之道曰柔與剛立人之道曰仁與義","Tích giả, thánh nhân chi tác Dịch dã, tương dĩ thuận tính mệnh chi lý. Thị dĩ lập thiên chi đạo, viết âm dữ dương; lập địa chi đạo, viết nhu dữ cương; lập nhân chi đạo, viết nhân dữ nghĩa.","Xưa thánh nhân làm Dịch là để thuận theo cái lý của tính mệnh. Cho nên lập đạo của trời gọi là âm và dương; lập đạo của đất gọi là nhu và cương; lập đạo của người gọi là nhân và nghĩa."],["陰疑於陽必戰為其嫌於无陽也故稱龍焉猶未離其類也故稱血焉夫玄黃者天地之雜也天玄而地黃","Âm nghi ư dương tất chiến, vị kỳ hiềm ư vô dương dã, cố xưng long yên. Do vị ly kỳ loại dã, cố xưng huyết yên. Phù huyền hoàng giả, thiên địa chi tạp dã. Thiên huyền nhi địa hoàng.","Âm thịnh ngang ngửa với dương thì ắt đánh nhau; vì sợ người ta ngỡ (lúc ấy) không còn dương nên gọi là \"rồng\". Vẫn chưa lìa loại của mình (vẫn là âm) nên gọi là \"máu\". Đen và vàng là màu trời đất lẫn lộn: trời màu đen huyền, đất màu vàng."],["是故形而上者謂之道形而下者謂之器化而裁之謂之變推而行之謂之通舉而錯之天下之民謂之事業","Thị cố hình nhi thượng giả vị chi đạo, hình nhi hạ giả vị chi khí, hóa nhi tài chi vị chi biến, suy nhi hành chi vị chi thông, cử nhi thố chi thiên hạ chi dân vị chi sự nghiệp.","Cho nên cái ở trên hình thể gọi là đạo, cái ở dưới hình thể gọi là khí (vật cụ thể). Theo sự biến hóa mà cắt đặt gọi là biến; đẩy ra mà thực hành gọi là thông; đem áp dụng cho dân trong thiên hạ gọi là sự nghiệp."],["九四曰或躍在淵无咎何謂也子曰上下无常非為邪也進退无恒非離羣也君子進德脩業欲及時也故无咎","Cửu tứ viết: \"Hoặc dược tại uyên, vô cữu.\" Hà vị dã? Tử viết: \"Thượng hạ vô thường, phi vi tà dã. Tiến thoái vô hằng, phi ly quần dã. Quân tử tiến đức tu nghiệp, dục cập thời dã. Cố vô cữu.\"","Hào Cửu tứ nói: \"Hoặc nhảy lên, hoặc ở dưới vực, không lỗi.\" Nghĩa là gì? Khổng Tử nói: \"Lên xuống không cố định, không phải vì làm điều tà; tiến lui không thường, không phải vì rời bỏ bạn bè. Quân tử tiến đức sửa nghiệp là muốn kịp thời. Cho nên không lỗi.\""],["是故吉凶者失得之象也悔吝者憂虞之象也變化者進退之象也剛柔者晝夜之象也六爻之動三極之道也","Thị cố cát hung giả, thất đắc chi tượng dã. Hối lận giả, ưu ngu chi tượng dã. Biến hóa giả, tiến thoái chi tượng dã. Cương nhu giả, trú dạ chi tượng dã. Lục hào chi động, tam cực chi đạo dã.","Cho nên cát hung là hình tượng của được và mất. Hối lận là hình tượng của lo lắng, băn khoăn. Biến hóa là hình tượng của tiến và lui. Cương nhu là hình tượng của ngày và đêm. Sự động của sáu hào là đạo của ba cực (trời, đất, người)."],["亢之為言也知進而不知退知存而不知亡知得而不知喪其唯聖人乎知進退存亡而不失其正者其唯聖人乎","Kháng chi vi ngôn dã, tri tiến nhi bất tri thoái, tri tồn nhi bất tri vong, tri đắc nhi bất tri táng; kỳ duy thánh nhân hồ? Tri tiến thoái tồn vong nhi bất thất kỳ chính giả, kỳ duy thánh nhân hồ!","Chữ \"kháng\" (quá cao) nghĩa là chỉ biết tiến mà không biết lui, chỉ biết còn mà không biết mất, chỉ biết được mà không biết thua. Chỉ có thánh nhân chăng? Biết tiến lui, còn mất mà không mất sự chính đáng, chỉ có thánh nhân mà thôi!"],["離為火為日為電為中女為甲冑為戈兵其於人也為大腹為乾卦為鱉為蟹為蠃為蚌為龜其於木也為科上槁","Ly vi hỏa, vi nhật, vi điện, vi trung nữ, vi giáp trụ, vi qua binh. Kỳ ư nhân dã, vi đại phúc, vi can quái, vi miết, vi giải, vi loa, vi bạng, vi quy. Kỳ ư mộc dã, vi khoa thượng cảo.","Ly là lửa, là mặt trời, là chớp, là gái giữa, là áo giáp mũ trụ, là giáo mác binh khí. Với người thì là bụng to, là quẻ khô; là con ba ba, con cua, con ốc, con trai, con rùa. Với cây thì là cây rỗng ruột, ngọn khô."],["一陰一陽之謂道繼之者善也成之者性也仁者見之謂之仁知者見之謂之知百姓日用而不知故君子之道鮮矣","Nhất âm nhất dương chi vị đạo: kế chi giả thiện dã, thành chi giả tính dã; nhân giả kiến chi vị chi nhân, trí giả kiến chi vị chi trí; bách tính nhật dụng nhi bất tri, cố quân tử chi đạo tiển hĩ.","Một âm một dương (luân phiên) gọi là Đạo. Nối tiếp nó là điều thiện, làm thành nó là bản tính. Người nhân thấy nó thì gọi là nhân, người trí thấy nó thì gọi là trí; dân chúng hằng ngày dùng nó mà không biết; cho nên đạo của người quân tử ít ai thấu."],["履和而至謙尊而光復小而辨於物恒雜而不厭損先難而後易益長裕而不没困窮而通井居其所而遷巽稱而隱","Lý, hòa nhi chí. Khiêm, tôn nhi quang. Phục, tiểu nhi biện ư vật. Hằng, tạp nhi bất yếm. Tổn, tiên nan nhi hậu dị. Ích, trưởng dụ nhi bất một. Khốn, cùng nhi thông. Tỉnh, cư kỳ sở nhi thiên. Tốn, xứng nhi ẩn.","Lý: hòa nhã mà đạt tới. Khiêm: được tôn trọng mà sáng rỡ. Phục: nhỏ mà phân biệt được sự vật. Hằng: phức tạp mà không chán. Tổn: trước khó sau dễ. Ích: lớn lên dư dật mà không gượng ép. Khốn: cùng quẫn mà thông. Tỉnh: ở yên chỗ mình mà (ân trạch) lan đi. Tốn: cân nhắc mà kín đáo."],["陽卦多陰陰卦多陽其故何也陽卦奇陰卦偶其德行何也陽一君而二民君子之道也陰二君而一民小人之道也","Dương quái đa âm, âm quái đa dương, kỳ cố hà dã? Dương quái cơ, âm quái ngẫu. Kỳ đức hạnh hà dã? Dương nhất quân nhi nhị dân, quân tử chi đạo dã; âm nhị quân nhi nhất dân, tiểu nhân chi đạo dã.","Quẻ dương nhiều hào âm, quẻ âm nhiều hào dương, vì sao vậy? Vì quẻ dương (tổng số) lẻ, quẻ âm (tổng số) chẵn. Đức hạnh của chúng thế nào? Dương là một vua hai dân – đạo của người quân tử; âm là hai vua một dân – đạo của kẻ tiểu nhân."],["大壯則止遯則退也大有眾也同人親也革去故也鼎取新也小過過也中孚信也豐多故也親寡旅也離上而坎下也","Đại Tráng tắc chỉ, Độn tắc thoái dã. Đại Hữu chúng dã, Đồng Nhân thân dã. Cách khứ cố dã, Đỉnh thủ tân dã. Tiểu Quá quá dã, Trung Phu tín dã. Phong đa cố dã, thân quả Lữ dã. Ly thượng, nhi Khảm hạ dã.","Đại Tráng thì phải dừng, Độn thì lui. Đại Hữu là nhiều người, Đồng Nhân là thân nhau. Cách là bỏ cũ, Đỉnh là lấy mới. Tiểu Quá là vượt quá, Trung Phu là tin. Phong là nhiều chuyện, ít người thân là Lữ. Ly đi lên, còn Khảm đi xuống."],["富有之謂大業日新之謂盛德生生之謂易成象之謂乾效法之謂坤極數知來之謂占通變之謂事陰陽不測之謂神","Phú hữu chi vị đại nghiệp, nhật tân chi vị thịnh đức, sinh sinh chi vị Dịch, thành tượng chi vị Càn, hiệu pháp chi vị Khôn, cực số tri lai chi vị chiêm, thông biến chi vị sự, âm dương bất trắc chi vị thần.","Giàu có (bao gồm muôn vật) gọi là nghiệp lớn; mỗi ngày một mới gọi là đức thịnh; sinh rồi lại sinh gọi là Dịch; làm thành hình tượng gọi là Càn; mô phỏng theo mà thành hình thể gọi là Khôn; xét cùng số mà biết điều sắp tới gọi là chiêm; thông được sự biến gọi là việc; âm dương không lường được gọi là thần."],["勞謙君子有終吉子曰勞而不伐有功而不德厚之至也語以其功下人者也德言盛禮言恭謙也者致恭以存其位者也","\"Lao khiêm, quân tử hữu chung, cát.\" Tử viết: \"Lao nhi bất phạt, hữu công nhi bất đức, hậu chi chí dã; ngữ dĩ kỳ công hạ nhân giả dã. Đức ngôn thịnh, lễ ngôn cung; khiêm dã giả, trí cung dĩ tồn kỳ vị giả dã.\"","\"Có công lao mà khiêm tốn, người quân tử có kết cục tốt, cát.\" (hào Cửu tam quẻ Khiêm). Khổng Tử nói: \"Khó nhọc mà không khoe, có công mà không kể là ơn của mình, đó là đôn hậu tột bậc; ý nói người có công mà vẫn hạ mình dưới người khác. Đức thì cốt ở thịnh, lễ thì cốt ở cung kính; khiêm là hết mực cung kính để giữ được địa vị của mình.\""],["子曰夫易何為者也夫易開物成務冒天下之道如斯而已者也是故聖人以通天下之志以定天下之業以斷天下之疑","Tử viết: \"Phù Dịch, hà vi giả dã? Phù Dịch, khai vật thành vụ, mạo thiên hạ chi đạo, như tư nhi dĩ giả dã.\" Thị cố thánh nhân dĩ thông thiên hạ chi chí, dĩ định thiên hạ chi nghiệp, dĩ đoán thiên hạ chi nghi.","Khổng Tử nói: \"Dịch để làm gì? Dịch mở mang sự vật, hoàn thành công việc, bao trùm đạo của thiên hạ, chỉ như thế mà thôi.\" Cho nên thánh nhân dùng nó để thông suốt chí hướng của thiên hạ, định sự nghiệp của thiên hạ, quyết đoán mối nghi của thiên hạ."],["是故履德之基也謙德之柄也復德之本也恒德之固也損德之脩也益德之裕也困德之辨也井德之地也巽德之制也","Thị cố: Lý, đức chi cơ dã. Khiêm, đức chi bính dã. Phục, đức chi bản dã. Hằng, đức chi cố dã. Tổn, đức chi tu dã. Ích, đức chi dụ dã. Khốn, đức chi biện dã. Tỉnh, đức chi địa dã. Tốn, đức chi chế dã.","Cho nên: Lý là nền của đức. Khiêm là cán (chỗ nắm) của đức. Phục là gốc của đức. Hằng là sự vững bền của đức. Tổn là sự tu sửa của đức. Ích là sự dư dật của đức. Khốn là chỗ phân biệt (thử thách) đức. Tỉnh là đất (chỗ đứng) của đức. Tốn là sự chế ngự (uyển chuyển) của đức."],["與人同者物必歸焉故受之以大有有大者不可以盈故受之以謙有大而能謙必豫故受之以豫豫必有隨故受之以隨","Dữ nhân đồng giả, vật tất quy yên, cố thụ chi dĩ Đại Hữu. Hữu đại giả bất khả dĩ doanh, cố thụ chi dĩ Khiêm. Hữu đại nhi năng khiêm, tất dự, cố thụ chi dĩ Dự. Dự tất hữu tùy, cố thụ chi dĩ Tùy.","Hòa đồng với người thì vật ắt quy về, nên tiếp bằng Đại Hữu. Có lớn thì không được để đầy tràn, nên tiếp bằng Khiêm. Có lớn mà biết khiêm thì ắt vui, nên tiếp bằng Dự. Vui thì ắt có người theo, nên tiếp bằng Tùy."],["不出戶庭无咎子曰亂之所生也則言語以為階君不密則失臣臣不密則失身幾事不密則害成是以君子慎密而不出也","\"Bất xuất hộ đình, vô cữu.\" Tử viết: \"Loạn chi sở sinh dã, tắc ngôn ngữ dĩ vi giai. Quân bất mật tắc thất thần, thần bất mật tắc thất thân, cơ sự bất mật tắc hại thành; thị dĩ quân tử thận mật nhi bất xuất dã.\"","\"Không ra khỏi sân trong, không lỗi.\" (hào Sơ cửu quẻ Tiết). Khổng Tử nói: \"Rối loạn sinh ra thường lấy lời nói làm bậc thang. Vua không kín thì mất bề tôi, bề tôi không kín thì mất thân, việc hệ trọng mà không kín thì hỏng việc thành. Vì vậy người quân tử thận trọng giữ kín mà không để lộ ra.\""],["天尊地卑乾坤定矣卑高以陳貴賤位矣動靜有常剛柔斷矣方以類聚物以羣分吉凶生矣在天成象在地成形變化見矣","Thiên tôn địa ti, Càn Khôn định hĩ. Ti cao dĩ trần, quý tiện vị hĩ. Động tĩnh hữu thường, cương nhu đoán hĩ. Phương dĩ loại tụ, vật dĩ quần phân, cát hung sinh hĩ. Tại thiên thành tượng, tại địa thành hình, biến hóa hiện hĩ.","Trời cao, đất thấp, nên Càn Khôn được định. Thấp cao bày ra, nên sang hèn có ngôi thứ. Động tĩnh có lẽ thường, nên cứng mềm phân biệt rõ. Mọi việc theo loại mà tụ lại, muôn vật theo bầy mà chia ra, nên cát hung sinh ra. Ở trời thành hình tượng, ở đất thành hình thể, nên sự biến hóa hiện ra."],["子曰易其至矣乎夫易聖人所以崇德而廣業也知崇禮卑崇效天卑法地天地設位而易行乎其中矣成性存存道義之門","Tử viết: \"Dịch kỳ chí hĩ hồ! Phù Dịch, thánh nhân sở dĩ sùng đức nhi quảng nghiệp dã. Trí sùng lễ ti, sùng hiệu thiên, ti pháp địa. Thiên địa thiết vị, nhi Dịch hành hồ kỳ trung hĩ. Thành tính tồn tồn, đạo nghĩa chi môn.\"","Khổng Tử nói: \"Dịch là tột bậc thay! Dịch là cái thánh nhân dùng để nâng cao đức và mở rộng sự nghiệp. Trí thì cao, lễ thì thấp; cao là bắt chước trời, thấp là noi theo đất. Trời đất đặt ngôi, mà Dịch vận hành ở khoảng giữa. Giữ gìn mãi cái tính đã thành, đó là cửa ngõ của đạo và nghĩa.\""],["大衍之數五十其用四十有九分而為二以象兩掛一以象三揲之以四以象四時歸奇於扐以象閏五歲再閏故再扐而後掛","Đại diễn chi số ngũ thập, kỳ dụng tứ thập hữu cửu, phân nhi vi nhị dĩ tượng lưỡng, quải nhất dĩ tượng tam, thiệt chi dĩ tứ dĩ tượng tứ thời, quy cơ ư lặc dĩ tượng nhuận, ngũ tuế tái nhuận, cố tái lặc nhi hậu quải.","Số đại diễn là năm mươi, dùng bốn mươi chín. Chia làm hai phần để tượng Lưỡng nghi; gác ra một que để tượng Tam tài; đếm từng bốn que để tượng bốn mùa; dồn số que lẻ vào kẽ ngón tay để tượng tháng nhuận; năm năm có hai lần nhuận, nên dồn lẻ hai lần rồi mới gác lại."],["潛龍勿用下也見龍在田時舍也終日乾乾行事也或躍在淵自試也飛龍在天上治也亢龍有悔窮之災也乾元用九天下治也","\"Tiềm long vật dụng\", hạ dã. \"Hiện long tại điền\", thời xá dã. \"Chung nhật càn càn\", hành sự dã. \"Hoặc dược tại uyên\", tự thí dã. \"Phi long tại thiên\", thượng trị dã. \"Kháng long hữu hối\", cùng chi tai dã. \"Càn nguyên dụng cửu\", thiên hạ trị dã.","\"Rồng ẩn chớ dùng\" – vì ở dưới. \"Rồng hiện ở ruộng\" – thời còn tạm dừng (chưa được dùng). \"Suốt ngày hăng hái\" – lo làm việc. \"Hoặc nhảy ở vực\" – tự thử sức. \"Rồng bay trên trời\" – ở trên mà cai trị. \"Rồng quá cao có hối\" – tai họa của sự cùng cực. \"Càn nguyên dùng số chín\" – thiên hạ được trị yên."],["物不可以苟合而已故受之以賁賁者飾也致飾然後亨則盡矣故受之以剝剝者剝也物不可以終盡剝窮上反下故受之以復","Vật bất khả dĩ cẩu hợp nhi dĩ, cố thụ chi dĩ Bí; Bí giả sức dã. Trí sức nhiên hậu hanh, tắc tận hĩ, cố thụ chi dĩ Bác; Bác giả bác dã. Vật bất khả dĩ chung tận, Bác cùng thượng phản hạ, cố thụ chi dĩ Phục.","Vật không thể hợp một cách cẩu thả là xong, nên tiếp bằng Bí; Bí là trang sức. Trau chuốt đến cùng rồi hanh thông thì cũng là hết, nên tiếp bằng Bác; Bác là bóc mòn. Vật không thể hết hẳn; Bác cùng ở trên thì quay về dưới, nên tiếp bằng Phục."],["緩必有所失故受之以損損而不已必益故受之以益益而不已必決故受之以夬夬者決也決必有所遇故受之以姤姤者遇也","Hoãn tất hữu sở thất, cố thụ chi dĩ Tổn. Tổn nhi bất dĩ, tất ích, cố thụ chi dĩ Ích. Ích nhi bất dĩ, tất quyết, cố thụ chi dĩ Quải; Quải giả quyết dã. Quyết tất hữu sở ngộ, cố thụ chi dĩ Cấu; Cấu giả ngộ dã.","Thư giãn thì ắt có chỗ sơ thất, nên tiếp bằng Tổn. Bớt mãi không thôi thì ắt được thêm, nên tiếp bằng Ích. Thêm mãi không thôi thì ắt vỡ, nên tiếp bằng Quải; Quải là quyết (vỡ bờ). Vỡ ra thì ắt có chỗ gặp, nên tiếp bằng Cấu; Cấu là gặp."],["初六藉用白茅无咎子曰苟錯諸地而可矣藉之用茅何咎之有慎之至也夫茅之為物薄而用可重也慎斯術也以往其无所失矣","\"Sơ lục, tạ dụng bạch mao, vô cữu.\" Tử viết: \"Cẩu thố chư địa nhi khả hĩ. Tạ chi dụng mao, hà cữu chi hữu! Thận chi chí dã. Phù mao chi vi vật bạc nhi dụng khả trọng dã, thận tư thuật dã dĩ vãng, kỳ vô sở thất hĩ.\"","\"Sơ lục: lót bằng cỏ tranh trắng, không lỗi.\" (quẻ Đại Quá). Khổng Tử nói: \"Đặt (đồ lễ) thẳng xuống đất cũng đã được rồi; lại lót bằng cỏ tranh thì còn lỗi gì! Đó là cẩn thận đến mức tột cùng. Cỏ tranh là vật mỏng nhẹ mà dùng vào việc thì có thể quý trọng. Theo cách cẩn thận ấy mà làm thì không có gì sơ suất.\""],["易曰自天祐之吉无不利子曰祐者助也天之所助者順也人之所助者信也履信思乎順又以尚賢也是以自天祐之吉无不利也","Dịch viết: \"Tự thiên hựu chi, cát vô bất lợi.\" Tử viết: \"Hựu giả, trợ dã. Thiên chi sở trợ giả, thuận dã. Nhân chi sở trợ giả, tín dã. Lý tín tư hồ thuận, hựu dĩ thượng hiền dã, thị dĩ 'tự thiên hựu chi, cát vô bất lợi' dã.\"","Dịch nói: \"Từ trời giúp cho, tốt, không gì không lợi.\" (hào Thượng cửu quẻ Đại Hữu). Khổng Tử nói: \"Hựu là giúp. Trời giúp người thuận; người giúp người có chữ tín. Làm theo chữ tín, nghĩ đến sự thuận, lại tôn trọng người hiền, cho nên 'từ trời giúp cho, tốt, không gì không lợi'.\""],["有天地然後萬物生焉盈天地之間者唯萬物故受之以屯屯者盈也屯者物之始生也物生必蒙故受之以蒙蒙者蒙也物之穉也","Hữu thiên địa, nhiên hậu vạn vật sinh yên. Doanh thiên địa chi gian giả, duy vạn vật, cố thụ chi dĩ Truân; Truân giả doanh dã, Truân giả vật chi thủy sinh dã. Vật sinh tất mông, cố thụ chi dĩ Mông; Mông giả mông dã, vật chi trĩ dã.","Có trời đất (Càn, Khôn) rồi muôn vật mới sinh ra. Đầy khắp khoảng trời đất chỉ có muôn vật, nên tiếp bằng quẻ Truân; Truân là đầy, là lúc vật mới sinh. Vật sinh ra ắt còn non dại, nên tiếp bằng Mông; Mông là mờ tối, là vật còn non."],["夫乾確然示人易矣夫坤隤然示人簡矣爻也者效此者也象也者像此者也爻象動乎內吉凶見乎外功業見乎變聖人之情見乎辭","Phù Càn, xác nhiên thị nhân dị hĩ; phù Khôn, đồi nhiên thị nhân giản hĩ. Hào dã giả, hiệu thử giả dã; tượng dã giả, tượng thử giả dã. Hào tượng động hồ nội, cát hung hiện hồ ngoại, công nghiệp hiện hồ biến, thánh nhân chi tình hiện hồ từ.","Càn vững chắc, chỉ cho người thấy sự dễ dàng; Khôn mềm thuận, chỉ cho người thấy sự giản dị. Hào là bắt chước cái đó; tượng là mô phỏng cái đó. Hào và tượng động ở bên trong (quẻ), cát hung hiện ra bên ngoài, công nghiệp hiện ra ở sự biến, tấm lòng của thánh nhân hiện ra ở lời."],["巽為木為風為長女為繩直為工為白為長為高為進退為不果為臭其於人也為寡髮為廣顙為多白眼為近利市三倍其究為躁卦","Tốn vi mộc, vi phong, vi trưởng nữ, vi thằng trực, vi công, vi bạch, vi trường, vi cao, vi tiến thoái, vi bất quả, vi xú. Kỳ ư nhân dã, vi quả phát, vi quảng tảng, vi đa bạch nhãn, vi cận lợi thị tam bội. Kỳ cứu vi táo quái.","Tốn là cây, là gió, là gái trưởng, là dây mực thẳng, là thợ, là màu trắng, là dài, là cao, là tiến lui, là không quả quyết, là mùi. Với người thì là tóc thưa, trán rộng, mắt nhiều lòng trắng, là gần lợi, buôn bán lãi gấp ba. Cuối cùng thành quẻ nóng nảy."],["易曰困于石據于蒺蔾入于其宮不見其妻凶子曰非所困而困焉名必辱非所據而據焉身必危既辱且危死期將至妻其可得見耶","Dịch viết: \"Khốn vu thạch, cứ vu tật lê, nhập vu kỳ cung, bất kiến kỳ thê, hung.\" Tử viết: \"Phi sở khốn nhi khốn yên, danh tất nhục; phi sở cứ nhi cứ yên, thân tất nguy; ký nhục thả nguy, tử kỳ tương chí, thê kỳ khả đắc kiến da!\"","Dịch nói: \"Khốn vì đá, dựa vào cỏ gai, vào nhà không thấy vợ, hung.\" (hào Lục tam quẻ Khốn). Khổng Tử nói: \"Không phải chỗ đáng khốn mà tự chuốc khốn, danh ắt nhục; không phải chỗ nên dựa mà dựa, thân ắt nguy; đã nhục lại nguy, ngày chết sắp đến, còn thấy được vợ sao!\""],["初九曰潛龍勿用何謂也子曰龍德而隱者也不易乎世不成乎名遯世无悶不見是而无悶樂則行之憂則違之確乎其不可拔潛龍也","Sơ cửu viết: \"Tiềm long, vật dụng.\" Hà vị dã? Tử viết: \"Long đức nhi ẩn giả dã. Bất dịch hồ thế, bất thành hồ danh, độn thế vô muộn, bất kiến thị nhi vô muộn, lạc tắc hành chi, ưu tắc vi chi, xác hồ kỳ bất khả bạt, tiềm long dã.\"","Hào Sơ cửu nói: \"Rồng ẩn, chớ dùng.\" Nghĩa là gì? Khổng Tử nói: \"Có đức của rồng mà ẩn mình. Không vì đời mà đổi mình, không cầu thành danh; lánh đời mà không buồn, không được ai cho là phải cũng không buồn; điều vui thì làm, điều lo thì tránh; vững vàng không thể nhổ đi được – đó là rồng ẩn.\""],["震為雷為龍為玄黃為敷為大涂為長子為決躁為蒼筤竹為萑葦其於馬也為善鳴為馵足為的顙其於稼也為反生其究為健為蕃鮮","Chấn vi lôi, vi long, vi huyền hoàng, vi phu, vi đại đồ, vi trưởng tử, vi quyết táo, vi thương lang trúc, vi hoàn vĩ. Kỳ ư mã dã, vi thiện minh, vi chú túc, vi đích tảng. Kỳ ư giá dã, vi phản sinh. Kỳ cứu vi kiện, vi phồn tiên.","Chấn là sấm, là rồng, là màu đen vàng, là tỏa nở (hoa), là đường lớn, là con trưởng, là quyết liệt nóng nảy, là tre xanh non, là lau sậy. Với ngựa thì là ngựa hay hí, ngựa chân sau trắng, ngựa trán trắng. Với lúa thì là mầm mọc ngược lên. Cuối cùng thì thành mạnh, thành tươi tốt."],["刳木為舟剡木為楫舟楫之利以濟不通致遠以利天下蓋取諸渙服牛乘馬引重致遠以利天下蓋取諸隨重門擊柝以待暴客蓋取諸豫","Khô mộc vi chu, diệm mộc vi tiếp, chu tiếp chi lợi dĩ tế bất thông, trí viễn dĩ lợi thiên hạ, cái thủ chư Hoán. Phục ngưu thừa mã, dẫn trọng trí viễn dĩ lợi thiên hạ, cái thủ chư Tùy. Trùng môn kích thác dĩ đãi bạo khách, cái thủ chư Dự.","Khoét gỗ làm thuyền, vót gỗ làm mái chèo; cái lợi của thuyền chèo là để qua chỗ không thông, đi xa mà lợi cho thiên hạ, có lẽ lấy ý ở quẻ Hoán. Dùng trâu kéo, cưỡi ngựa, chở nặng đi xa mà lợi cho thiên hạ, có lẽ lấy ý ở quẻ Tùy. Làm cửa nhiều lớp, đánh mõ canh để phòng kẻ bạo ngược, có lẽ lấy ý ở quẻ Dự."],["夫乾其靜也專其動也直是以大生焉夫坤其靜也翕其動也闢是以廣生焉廣大配天地變通配四時陰陽之義配日月易簡之善配至德","Phù Càn, kỳ tĩnh dã chuyên, kỳ động dã trực, thị dĩ đại sinh yên. Phù Khôn, kỳ tĩnh dã hấp, kỳ động dã tịch, thị dĩ quảng sinh yên. Quảng đại phối thiên địa, biến thông phối tứ thời, âm dương chi nghĩa phối nhật nguyệt, dị giản chi thiện phối chí đức.","Càn, lúc tĩnh thì chuyên nhất, lúc động thì thẳng tới, nên sinh ra cái lớn. Khôn, lúc tĩnh thì khép lại, lúc động thì mở ra, nên sinh ra cái rộng. Rộng lớn sánh với trời đất; biến thông sánh với bốn mùa; nghĩa âm dương sánh với mặt trời mặt trăng; cái hay của dị giản sánh với đức tột bậc."],["是故君子所居而安者易之序也所樂而玩者爻之辭也是故君子居則觀其象而玩其辭動則觀其變而玩其占是以自天祐之吉无不利","Thị cố quân tử sở cư nhi an giả, Dịch chi tự dã. Sở lạc nhi ngoạn giả, hào chi từ dã. Thị cố quân tử cư tắc quan kỳ tượng nhi ngoạn kỳ từ, động tắc quan kỳ biến nhi ngoạn kỳ chiêm; thị dĩ tự thiên hựu chi, cát vô bất lợi.","Cho nên điều người quân tử ở đó mà yên là trật tự của Dịch; điều vui mà nghiền ngẫm là lời của hào. Vì vậy quân tử lúc ở yên thì xem tượng mà ngẫm lời, lúc hành động thì xem sự biến mà ngẫm lời chiêm; nhờ thế được trời giúp, tốt mà không gì không lợi."],["是故闔戶謂之坤闢戶謂之乾一闔一闢謂之變往來不窮謂之通見乃謂之象形乃謂之器制而用之謂之法利用出入民咸用之謂之神","Thị cố hạp hộ vị chi Khôn, tịch hộ vị chi Càn, nhất hạp nhất tịch vị chi biến; vãng lai bất cùng vị chi thông, hiện nãi vị chi tượng, hình nãi vị chi khí, chế nhi dụng chi vị chi pháp, lợi dụng xuất nhập, dân hàm dụng chi vị chi thần.","Cho nên đóng cửa gọi là Khôn, mở cửa gọi là Càn; một đóng một mở gọi là biến; qua lại không cùng gọi là thông; hiện ra gọi là tượng; có hình thể gọi là khí (đồ vật); chế ra mà dùng gọi là pháp; dùng nó lợi cho việc ra vào, dân ai cũng dùng mà không biết vì sao, gọi là thần."],["包犧氏沒神農氏作斲木為耜揉木為耒耒耨之利以教天下蓋取諸益日中為市致天下之民聚天下之貨交易而退各得其所蓋取諸噬嗑","Bao Hy thị một, Thần Nông thị tác, trác mộc vi tỷ, nhu mộc vi lỗi, lỗi nậu chi lợi, dĩ giáo thiên hạ, cái thủ chư Ích. Nhật trung vi thị, trí thiên hạ chi dân, tụ thiên hạ chi hóa, giao dịch nhi thoái, các đắc kỳ sở, cái thủ chư Phệ Hạp.","Họ Bao Hy mất, họ Thần Nông nổi lên, đẽo gỗ làm lưỡi cày, uốn gỗ làm cán cày, đem cái lợi của cày bừa dạy cho thiên hạ, có lẽ lấy ý ở quẻ Ích. Giữa trưa họp chợ, quy tụ dân thiên hạ, gom hàng hóa thiên hạ, trao đổi xong thì về, ai nấy được chỗ của mình, có lẽ lấy ý ở quẻ Phệ Hạp."],["夫大人者與天地合其德與日月合其明與四時合其序與鬼神合其吉凶先天而天弗違後天而奉天時天且弗違而況於人乎況於鬼神乎","Phù đại nhân giả, dữ thiên địa hợp kỳ đức, dữ nhật nguyệt hợp kỳ minh, dữ tứ thời hợp kỳ tự, dữ quỷ thần hợp kỳ cát hung; tiên thiên nhi thiên phất vi, hậu thiên nhi phụng thiên thời, thiên thả phất vi, nhi huống ư nhân hồ? Huống ư quỷ thần hồ?","Bậc đại nhân thì đức hợp với trời đất, sáng hợp với mặt trời mặt trăng, thứ tự hợp với bốn mùa, cát hung hợp với quỷ thần. Làm trước trời mà trời không trái, làm sau trời thì vâng theo thời trời. Trời còn không trái, huống chi người? Huống chi quỷ thần?"],["是故列貴賤者存乎位齊小大者存乎卦辯吉凶者存乎辭憂悔吝者存乎介震无咎者存乎悔是故卦有小大辭有險易辭也者各指其所之","Thị cố liệt quý tiện giả tồn hồ vị, tề tiểu đại giả tồn hồ quái, biện cát hung giả tồn hồ từ, ưu hối lận giả tồn hồ giới, chấn vô cữu giả tồn hồ hối. Thị cố quái hữu tiểu đại, từ hữu hiểm dị; từ dã giả, các chỉ kỳ sở chi.","Cho nên bày sang hèn là ở ngôi hào; định lớn nhỏ là ở quẻ; phân biệt cát hung là ở lời; lo về hối lận là ở chỗ ranh giới nhỏ (giới); động mà được vô cữu là ở lòng ăn năn. Vì thế quẻ có lớn nhỏ, lời có hiểm có dễ; lời là để chỉ cho mỗi người chỗ mình nên đi tới."],["聖人作易令人趨吉避凶未卜而不知者是大數也卜之而神不告亦大數也旣已卜之神已先吿之明知故犯者亦不可盡委之於數也命也","thánh nhân tác dịch lệnh nhân xu cát tị hung vị bốc nhi bất tri giả thị đại số dã bốc chi nhi thần bất cáo diệc đại số dã 旣 dĩ bốc chi thần dĩ tiên 吿 chi minh tri cố phạm giả diệc bất khả tận uỷ chi ư số dã mệnh dã","thánh nhân làm Dịch để người ta theo lành tránh dữ"],["吉凶悔吝者生乎動者也剛柔者立本者也變通者趣時者也吉凶者貞勝者也天地之道貞觀者也日月之道貞明者也天下之動貞夫一者也","Cát hung hối lận giả, sinh hồ động giả dã. Cương nhu giả, lập bản giả dã; biến thông giả, thú thời giả dã; cát hung giả, trinh thắng giả dã. Thiên địa chi đạo, trinh quan giả dã; nhật nguyệt chi đạo, trinh minh giả dã; thiên hạ chi động, trinh phù nhất giả dã.","Cát, hung, hối, lận đều sinh ra từ sự động. Cương nhu là cái lập nên gốc; biến thông là cái để theo kịp thời; cát hung là do giữ được chính mà thắng. Đạo trời đất là chính mà bày ra cho thấy; đạo mặt trời mặt trăng là chính mà sáng; mọi sự động trong thiên hạ đều quy về chính và một."],["子曰乾坤其易之門邪乾陽物也坤陰物也陰陽合德而剛柔有體以體天地之撰以通神明之德其稱名也雜而不越於稽其類其衰世之意邪","Tử viết: \"Càn Khôn, kỳ Dịch chi môn da! Càn, dương vật dã; Khôn, âm vật dã. Âm dương hợp đức, nhi cương nhu hữu thể, dĩ thể thiên địa chi soạn, dĩ thông thần minh chi đức.\" Kỳ xưng danh dã, tạp nhi bất việt, ư khể kỳ loại, kỳ suy thế chi ý da!","Khổng Tử nói: \"Càn Khôn là cửa ngõ của Dịch chăng! Càn là vật dương, Khôn là vật âm. Âm dương hợp đức mà cương nhu có hình thể, để thể hiện công việc của trời đất, để thông với đức của thần minh.\" Tên gọi (các quẻ) tuy tạp mà không vượt ra ngoài (lẽ âm dương); xét đến loại của chúng, có lẽ mang ý của thời suy chăng!"],["子曰書不盡言言不盡意然則聖人之意其不可見乎子曰聖人立象以盡意設卦以盡情偽繫辭以盡其言變而通之以盡利鼓之舞之以盡神","Tử viết: \"Thư bất tận ngôn, ngôn bất tận ý.\" Nhiên tắc thánh nhân chi ý, kỳ bất khả kiến hồ? Tử viết: \"Thánh nhân lập tượng dĩ tận ý, thiết quái dĩ tận tình ngụy, hệ từ dĩ tận kỳ ngôn, biến nhi thông chi dĩ tận lợi, cổ chi vũ chi dĩ tận thần.\"","Khổng Tử nói: \"Chữ viết không ghi hết lời nói, lời nói không diễn hết ý.\" Vậy thì ý của thánh nhân không thể thấy được sao? Khổng Tử nói: \"Thánh nhân lập ra tượng để diễn hết ý, đặt ra quẻ để nói hết thật giả, buộc lời vào để nói hết điều muốn nói, biến đổi mà làm cho thông để dùng hết cái lợi, cổ động khích lệ để phát huy hết cái thần diệu.\""],["得其所歸者必大故受之以豐豐者大也窮大者必失其居故受之以旅旅而無所容故受之以巽巽者入也入而后說之故受之以兌兌者說也","Đắc kỳ sở quy giả tất đại, cố thụ chi dĩ Phong; Phong giả đại dã. Cùng đại giả tất thất kỳ cư, cố thụ chi dĩ Lữ. Lữ nhi vô sở dung, cố thụ chi dĩ Tốn; Tốn giả nhập dã. Nhập nhi hậu duyệt chi, cố thụ chi dĩ Đoài; Đoài giả duyệt dã.","Được chỗ về thì ắt lớn, nên tiếp bằng Phong; Phong là lớn thịnh. Lớn đến cùng thì ắt mất chỗ ở, nên tiếp bằng Lữ. Đi đất khách không chỗ dung thân, nên tiếp bằng Tốn; Tốn là thâm nhập. Vào được rồi sau mới vui, nên tiếp bằng Đoài; Đoài là vui."],["昔者聖人之作易也幽贊於神明而生蓍參天兩地而倚數觀變於陰陽而立卦發揮於剛柔而生爻和順於道德而理於義窮理盡性以至於命","Tích giả, thánh nhân chi tác Dịch dã, u tán ư thần minh nhi sinh thi. Tham thiên lưỡng địa nhi ỷ số, quan biến ư âm dương nhi lập quái; phát huy ư cương nhu nhi sinh hào; hòa thuận ư đạo đức nhi lý ư nghĩa; cùng lý tận tính dĩ chí ư mệnh.","Xưa thánh nhân làm Dịch, thầm giúp vào sự thần minh mà đặt ra phép dùng cỏ thi. Lấy trời là ba, đất là hai mà dựa vào đó lập số; xem sự biến đổi của âm dương mà lập quẻ; phát huy cương nhu mà sinh ra hào; hòa thuận với đạo đức mà sắp xếp theo nghĩa; xét cùng cái lý, làm trọn cái tính, để đạt tới mệnh."],["潛龍勿用陽氣潛藏見龍在田天下文明終日乾乾與時偕行或躍在淵乾道乃革飛龍在天乃位乎天德亢龍有悔與時偕極乾元用九乃見天則","\"Tiềm long vật dụng\", dương khí tiềm tàng. \"Hiện long tại điền\", thiên hạ văn minh. \"Chung nhật càn càn\", dữ thời giai hành. \"Hoặc dược tại uyên\", Càn đạo nãi cách. \"Phi long tại thiên\", nãi vị hồ thiên đức. \"Kháng long hữu hối\", dữ thời giai cực. \"Càn nguyên dụng cửu\", nãi hiện thiên tắc.","\"Rồng ẩn chớ dùng\" – dương khí còn ẩn tàng. \"Rồng hiện ở ruộng\" – thiên hạ sáng sủa văn minh. \"Suốt ngày hăng hái\" – cùng đi với thời. \"Hoặc nhảy ở vực\" – đạo Càn bắt đầu đổi thay. \"Rồng bay trên trời\" – ở đúng ngôi của đức trời. \"Rồng quá cao có hối\" – cùng với thời mà đến chỗ cực. \"Càn nguyên dùng số chín\" – thấy được phép tắc của trời."],["物穉不可不養也故受之以需需者飲食之道也飲食必有訟故受之以訟訟必有眾起故受之以師師者眾也眾必有所比故受之以比比者比也","Vật trĩ bất khả bất dưỡng dã, cố thụ chi dĩ Nhu; Nhu giả ẩm thực chi đạo dã. Ẩm thực tất hữu tụng, cố thụ chi dĩ Tụng. Tụng tất hữu chúng khởi, cố thụ chi dĩ Sư; Sư giả chúng dã. Chúng tất hữu sở tỷ, cố thụ chi dĩ Tỷ; Tỷ giả tỷ dã.","Vật non không thể không nuôi, nên tiếp bằng Nhu; Nhu là đạo ăn uống. Ăn uống ắt có tranh chấp, nên tiếp bằng Tụng. Tranh chấp ắt có đám đông nổi lên, nên tiếp bằng Sư; Sư là đông người. Đông người ắt phải có chỗ gắn bó, nên tiếp bằng Tỷ; Tỷ là gần gũi, gắn bó."],["積善之家必有餘慶積不善之家必有餘殃臣弒其君子弒其父非一朝一夕之故其所由來者漸矣由辨之不早辨也易曰履霜堅冰至蓋言順也","Tích thiện chi gia, tất hữu dư khánh; tích bất thiện chi gia, tất hữu dư ương. Thần thí kỳ quân, tử thí kỳ phụ, phi nhất triêu nhất tịch chi cố, kỳ sở do lai giả tiệm hĩ. Do biện chi bất tảo biện dã. Dịch viết: \"Lý sương, kiên băng chí.\" Cái ngôn thuận dã.","Nhà tích điều thiện ắt có phúc thừa; nhà tích điều bất thiện ắt có vạ thừa. Bầy tôi giết vua, con giết cha, không phải do một sớm một chiều, mà nguyên do đã đến dần dần; vì không sớm phân biệt mà ngăn ngừa. Dịch nói \"giẫm sương thì biết băng cứng sắp tới\" là nói về sự thuận theo (diễn tiến tự nhiên) vậy."],["九二曰見龍在田利見大人何謂也子曰龍德而正中者也庸言之信庸行之謹閑邪存其誠善世而不伐德博而化易曰見龍在田利見大人君德也","Cửu nhị viết: \"Hiện long tại điền, lợi kiến đại nhân.\" Hà vị dã? Tử viết: \"Long đức nhi chính trung giả dã. Dung ngôn chi tín, dung hạnh chi cẩn; nhàn tà tồn kỳ thành, thiện thế nhi bất phạt, đức bác nhi hóa. Dịch viết: 'Hiện long tại điền, lợi kiến đại nhân.' Quân đức dã.\"","Hào Cửu nhị nói: \"Rồng hiện ở ruộng, lợi gặp đại nhân.\" Nghĩa là gì? Khổng Tử nói: \"Có đức rồng mà ở chỗ chính giữa. Lời nói thường ngày thì tin thật, việc làm thường ngày thì cẩn trọng; ngăn điều tà mà giữ lòng thành; làm tốt cho đời mà không khoe; đức rộng mà cảm hóa người. Dịch nói 'rồng hiện ở ruộng, lợi gặp đại nhân' – ấy là đức của bậc quân vương.\""],["易與天地準故能彌綸天地之道仰以觀於天文俯以察於地理是故知幽明之故原始反終故知死生之說精氣為物遊魂為變是故知鬼神之情狀","Dịch dữ thiên địa chuẩn, cố năng di luân thiên địa chi đạo. Ngưỡng dĩ quan ư thiên văn, phủ dĩ sát ư địa lý, thị cố tri u minh chi cố. Nguyên thủy phản chung, cố tri tử sinh chi thuyết. Tinh khí vi vật, du hồn vi biến, thị cố tri quỷ thần chi tình trạng.","Dịch lấy trời đất làm chuẩn, nên bao trùm và sắp xếp được đạo của trời đất. Ngửa lên xem văn trời, cúi xuống xét lý đất, nên biết nguyên do của tối và sáng. Truy về lúc đầu, quay lại lúc cuối, nên hiểu lẽ chết sống. Tinh khí tụ lại thành vật, hồn tản đi thành biến đổi, nên biết được tình trạng của quỷ thần."],["有天地然後有萬物有萬物然後有男女有男女然後有夫婦有夫婦然後有父子有父子然後有君臣有君臣然後有上下有上下然後禮儀有所錯","Hữu thiên địa nhiên hậu hữu vạn vật, hữu vạn vật nhiên hậu hữu nam nữ, hữu nam nữ nhiên hậu hữu phu phụ, hữu phu phụ nhiên hậu hữu phụ tử, hữu phụ tử nhiên hậu hữu quân thần, hữu quân thần nhiên hậu hữu thượng hạ, hữu thượng hạ nhiên hậu lễ nghĩa hữu sở thố.","Có trời đất rồi có muôn vật; có muôn vật rồi có trai gái; có trai gái rồi có vợ chồng; có vợ chồng rồi có cha con; có cha con rồi có vua tôi; có vua tôi rồi có trên dưới; có trên dưới rồi lễ nghĩa mới có chỗ đặt."],["主器者莫若長子故受之以震震者動也物不可以終動止之故受之以艮艮者止也物不可以終止故受之以漸漸者進也進必有所歸故受之以歸妹","Chủ khí giả mạc nhược trưởng tử, cố thụ chi dĩ Chấn; Chấn giả động dã. Vật bất khả dĩ chung động, chỉ chi, cố thụ chi dĩ Cấn; Cấn giả chỉ dã. Vật bất khả dĩ chung chỉ, cố thụ chi dĩ Tiệm; Tiệm giả tiến dã. Tiến tất hữu sở quy, cố thụ chi dĩ Quy Muội.","Người giữ đồ tế khí (vạc) không ai bằng con trưởng, nên tiếp bằng Chấn; Chấn là động. Vật không thể động mãi, phải dừng lại, nên tiếp bằng Cấn; Cấn là dừng. Vật không thể dừng mãi, nên tiếp bằng Tiệm; Tiệm là tiến (dần dần). Tiến thì ắt có chỗ về, nên tiếp bằng Quy Muội."],["易之興也其當殷之末世周之盛德邪當文王與紂之事邪是故其辭危危者使平易者使傾其道甚大百物不廢懼以終始其要无咎此之謂易之道也","Dịch chi hưng dã, kỳ đương Ân chi mạt thế, Chu chi thịnh đức da! Đương Văn Vương dữ Trụ chi sự da! Thị cố kỳ từ nguy, nguy giả sử bình, dị giả sử khuynh, kỳ đạo thậm đại, bách vật bất phế, cụ dĩ chung thủy, kỳ yếu vô cữu; thử chi vị Dịch chi đạo dã.","Dịch hưng thịnh có lẽ vào cuối đời nhà Ân, lúc đức nhà Chu đang thịnh chăng! Vào thời có việc giữa Văn Vương và vua Trụ chăng! Cho nên lời của nó đầy cảnh giác: biết lo nguy thì được bình yên, khinh dễ thì bị nghiêng đổ. Đạo ấy rất lớn, trăm việc không bỏ sót; giữ lòng cẩn trọng từ đầu đến cuối, cốt yếu là không lỗi. Đó gọi là đạo của Dịch."],["以喜隨人者必有事故受之以蠱蠱者事也有事而后可大故受之以臨臨者大也物大然後可觀故受之以觀可觀而后有所合故受之以噬嗑嗑者合也","Dĩ hỷ tùy nhân giả, tất hữu sự, cố thụ chi dĩ Cổ; Cổ giả sự dã. Hữu sự nhi hậu khả đại, cố thụ chi dĩ Lâm; Lâm giả đại dã. Vật đại nhiên hậu khả quan, cố thụ chi dĩ Quan. Khả quan nhi hậu hữu sở hợp, cố thụ chi dĩ Phệ Hạp; Hạp giả hợp dã.","Vì vui mà theo người thì ắt sinh chuyện, nên tiếp bằng Cổ; Cổ là việc (việc hư hỏng cần sửa). Có việc rồi sau mới lớn được, nên tiếp bằng Lâm; Lâm là lớn. Vật lớn rồi mới đáng xem, nên tiếp bằng Quan. Đáng xem rồi sau mới có chỗ hợp, nên tiếp bằng Phệ Hạp; Hạp là hợp."],["夫易聖人之所以極深而研幾也唯深也故能通天下之志唯幾也故能成天下之務唯神也故不疾而速不行而至子曰易有聖人之道四焉者此之謂也","Phù Dịch, thánh nhân chi sở dĩ cực thâm nhi nghiên cơ dã! Duy thâm dã, cố năng thông thiên hạ chi chí; duy cơ dã, cố năng thành thiên hạ chi vụ; duy thần dã, cố bất tật nhi tốc, bất hành nhi chí. Tử viết \"Dịch hữu thánh nhân chi đạo tứ yên\" giả, thử chi vị dã.","Dịch là cái thánh nhân dùng để đi đến tận chỗ sâu và nghiên cứu chỗ manh nha. Chỉ vì sâu nên thông được chí của thiên hạ; chỉ vì nắm được chỗ manh nha nên làm thành được việc của thiên hạ; chỉ vì thần diệu nên không vội mà nhanh, không đi mà tới. Khổng Tử nói \"Dịch có bốn đạo của thánh nhân\" là nói điều này."],["九五曰飛龍在天利見大人何謂也子曰同聲相應同氣相求水流濕火就燥雲從龍風從虎聖人作而萬物覩本乎天者親上本乎地者親下則各從其類也","Cửu ngũ viết: \"Phi long tại thiên, lợi kiến đại nhân.\" Hà vị dã? Tử viết: \"Đồng thanh tương ứng, đồng khí tương cầu; thủy lưu thấp, hỏa tựu táo, vân tòng long, phong tòng hổ; thánh nhân tác nhi vạn vật đổ; bản hồ thiên giả thân thượng, bản hồ địa giả thân hạ, tắc các tòng kỳ loại dã.\"","Hào Cửu ngũ nói: \"Rồng bay trên trời, lợi gặp đại nhân.\" Nghĩa là gì? Khổng Tử nói: \"Cùng tiếng thì ứng nhau, cùng khí thì tìm nhau; nước chảy chỗ ẩm, lửa bén chỗ khô; mây theo rồng, gió theo hổ; thánh nhân dấy lên thì muôn vật đều trông thấy; cái gốc ở trời thì thân với trên, cái gốc ở đất thì thân với dưới – mỗi thứ theo loại của nó.\""],["比必有所畜也故受之以小畜物畜然後有禮故受之以履履而泰然後安故受之以泰泰者通也物不可以終通故受之以否物不可以終否故受之以同人","Tỷ tất hữu sở súc dã, cố thụ chi dĩ Tiểu Súc. Vật súc nhiên hậu hữu lễ, cố thụ chi dĩ Lý. Lý nhi thái, nhiên hậu an, cố thụ chi dĩ Thái; Thái giả thông dã. Vật bất khả dĩ chung thông, cố thụ chi dĩ Bĩ. Vật bất khả dĩ chung bĩ, cố thụ chi dĩ Đồng Nhân.","Gắn bó thì ắt có chỗ tích chứa, nên tiếp bằng Tiểu Súc. Vật tích chứa rồi mới có lễ, nên tiếp bằng Lý. Theo lễ mà thông thái rồi mới yên, nên tiếp bằng Thái; Thái là thông. Vật không thể thông mãi, nên tiếp bằng Bĩ. Vật không thể bế tắc mãi, nên tiếp bằng Đồng Nhân."],["神農氏沒黃帝堯舜氏作通其變使民不倦神而化之使民宜之易窮則變變則通通則久是以自天祐之吉无不利黃帝堯舜垂衣裳而天下治蓋取諸乾坤","Thần Nông thị một, Hoàng Đế, Nghiêu, Thuấn thị tác, thông kỳ biến, sử dân bất quyện; thần nhi hóa chi, sử dân nghi chi; Dịch cùng tắc biến, biến tắc thông, thông tắc cửu; thị dĩ tự thiên hựu chi, cát vô bất lợi. Hoàng Đế, Nghiêu, Thuấn thùy y thường nhi thiên hạ trị, cái thủ chư Càn Khôn.","Họ Thần Nông mất, Hoàng Đế, Nghiêu, Thuấn nổi lên, làm cho thông suốt sự biến, khiến dân không mỏi mệt; cảm hóa một cách thần diệu, khiến dân thấy thích hợp. Dịch đến chỗ cùng thì biến, biến thì thông, thông thì lâu dài; cho nên từ trời giúp cho, tốt, không gì không lợi. Hoàng Đế, Nghiêu, Thuấn rủ áo xiêm mà thiên hạ được trị, có lẽ lấy ý ở quẻ Càn, Khôn."],["夫婦之道不可以不久也故受之以恆恆者久也物不可以久居其所故受之以遯遯者退也物不可終遯故受之以大壯物不可以終壯故受之以晉晉者進也","Phu phụ chi đạo, bất khả dĩ bất cửu dã, cố thụ chi dĩ Hằng; Hằng giả cửu dã. Vật bất khả dĩ cửu cư kỳ sở, cố thụ chi dĩ Độn; Độn giả thoái dã. Vật bất khả chung độn, cố thụ chi dĩ Đại Tráng. Vật bất khả dĩ chung tráng, cố thụ chi dĩ Tấn; Tấn giả tiến dã.","Đạo vợ chồng không thể không lâu bền, nên tiếp bằng Hằng; Hằng là lâu. Vật không thể ở mãi một chỗ, nên tiếp bằng Độn; Độn là lui. Vật không thể lui mãi, nên tiếp bằng Đại Tráng. Vật không thể mạnh mãi, nên tiếp bằng Tấn; Tấn là tiến."],["子曰危者安其位者也亡者保其存者也亂者有其治者也是故君子安而不忘危存而不忘亡治而不忘亂是以身安而國家可保也易曰其亡其亡繫于苞桑","Tử viết: \"Nguy giả, an kỳ vị giả dã. Vong giả, bảo kỳ tồn giả dã. Loạn giả, hữu kỳ trị giả dã. Thị cố quân tử an nhi bất vong nguy, tồn nhi bất vong vong, trị nhi bất vong loạn, thị dĩ thân an nhi quốc gia khả bảo dã. Dịch viết: 'Kỳ vong kỳ vong, hệ vu bao tang.'\"","Khổng Tử nói: \"Nguy là do (trước đó) yên ổn với ngôi vị của mình; mất là do (trước đó) cho rằng mình còn vững; loạn là do (trước đó) cho rằng mình đang yên trị. Cho nên người quân tử yên mà không quên nguy, còn mà không quên mất, trị mà không quên loạn; nhờ vậy thân yên mà nước nhà giữ được. Dịch nói: 'Sắp mất rồi, sắp mất rồi! (luôn tự nhắc vậy thì) buộc chặt vào gốc dâu.'\" (hào Cửu ngũ quẻ Bĩ)"],["是故天生神物聖人則之天地變化聖人效之天垂象見吉凶聖人象之河出圖洛出書聖人則之易有四象所以示也繫辭焉所以告也定之以吉凶所以斷也","Thị cố thiên sinh thần vật, thánh nhân tắc chi. Thiên địa biến hóa, thánh nhân hiệu chi. Thiên thùy tượng, hiện cát hung, thánh nhân tượng chi. Hà xuất Đồ, Lạc xuất Thư, thánh nhân tắc chi. Dịch hữu tứ tượng, sở dĩ thị dã. Hệ từ yên, sở dĩ cáo dã. Định chi dĩ cát hung, sở dĩ đoán dã.","Cho nên trời sinh vật thiêng, thánh nhân lấy làm phép tắc. Trời đất biến hóa, thánh nhân bắt chước theo. Trời rủ hình tượng, hiện ra cát hung, thánh nhân mô phỏng theo. Sông Hoàng Hà hiện ra Đồ, sông Lạc hiện ra Thư, thánh nhân lấy làm phép tắc. Dịch có tứ tượng là để chỉ bày; buộc lời vào là để báo cho biết; định bằng cát hung là để quyết đoán."],["神也者妙萬物而為言者也動萬物者莫疾乎雷橈萬物者莫疾乎風燥萬物者莫熯乎火說萬物者莫說乎澤潤萬物者莫潤乎水終萬物始萬物者莫盛乎艮","Thần dã giả, diệu vạn vật nhi vi ngôn giả dã. Động vạn vật giả, mạc tật hồ lôi. Nạo vạn vật giả, mạc tật hồ phong. Táo vạn vật giả, mạc hãn hồ hỏa. Duyệt vạn vật giả, mạc duyệt hồ trạch. Nhuận vạn vật giả, mạc nhuận hồ thủy. Chung vạn vật, thủy vạn vật giả, mạc thịnh hồ Cấn.","\"Thần\" là nói cái kỳ diệu (khó lường) trong muôn vật. Làm muôn vật động, không gì nhanh bằng sấm. Làm muôn vật uốn lay, không gì nhanh bằng gió. Làm muôn vật khô, không gì nóng bằng lửa. Làm muôn vật vui, không gì vui bằng đầm. Làm muôn vật thấm nhuần, không gì nhuần bằng nước. Kết thúc muôn vật và khởi đầu muôn vật, không gì thịnh bằng Cấn."],["夫易彰往而察來而微顯闡幽開而當名辨物正言斷辭則備矣其稱名也小其取類也大其旨遠其辭文其言曲而中其事肆而隱因貳以濟民行以明失得之報","Phù Dịch, chương vãng nhi sát lai, nhi vi hiển xiển u, khai nhi đáng danh biện vật, chính ngôn đoán từ, tắc bị hĩ. Kỳ xưng danh dã tiểu, kỳ thủ loại dã đại, kỳ chỉ viễn, kỳ từ văn, kỳ ngôn khúc nhi trúng, kỳ sự tứ nhi ẩn, nhân nhị dĩ tế dân hành, dĩ minh thất đắc chi báo.","Dịch làm sáng tỏ việc đã qua mà xét rõ việc sắp tới, làm hiện rõ cái nhỏ nhặt và soi tỏ cái u ẩn; mở ra thì gọi đúng tên, phân biệt đúng vật, lời nói ngay thẳng, lời đoán dứt khoát, thế là đầy đủ. Tên gọi thì nhỏ mà loại suy thì lớn; ý chỉ sâu xa, lời lẽ có văn; lời nói quanh co mà trúng; sự việc bày ra mà ý ẩn bên trong. Nhân lúc người ta còn phân vân (giữa hai đường) mà giúp họ hành động, để làm rõ sự báo ứng của được và mất."],["元者善之長也亨者嘉之會也利者義之和也貞者事之幹也君子體仁足以長人嘉會足以合禮利物足以和義貞固足以幹事君子行此四德者故曰乾元亨利貞","Nguyên giả, thiện chi trưởng dã. Hanh giả, gia chi hội dã. Lợi giả, nghĩa chi hòa dã. Trinh giả, sự chi cán dã. Quân tử thể nhân túc dĩ trưởng nhân, gia hội túc dĩ hợp lễ, lợi vật túc dĩ hòa nghĩa, trinh cố túc dĩ cán sự. Quân tử hành thử tứ đức giả, cố viết: \"Càn, nguyên, hanh, lợi, trinh.\"","Nguyên là đứng đầu các điều thiện. Hanh là chỗ hội tụ các điều tốt đẹp. Lợi là sự hài hòa của nghĩa. Trinh là cái cốt cán của mọi việc. Người quân tử thể hiện điều nhân thì đủ để làm người đứng đầu; hội tụ cái đẹp thì đủ để hợp lễ; làm lợi cho vật thì đủ để hòa với nghĩa; giữ chính bền vững thì đủ để làm nên việc. Người quân tử làm theo bốn đức ấy, nên nói: \"Càn: nguyên, hanh, lợi, trinh.\""],["天一地二天三地四天五地六天七地八天九地十天數五地數五五位相得而各有合天數二十有五地數三十凡天地之數五十有五此所以成變化而行鬼神也","Thiên nhất địa nhị, thiên tam địa tứ, thiên ngũ địa lục, thiên thất địa bát, thiên cửu địa thập. Thiên số ngũ, địa số ngũ, ngũ vị tương đắc nhi các hữu hợp. Thiên số nhị thập hữu ngũ, địa số tam thập, phàm thiên địa chi số, ngũ thập hữu ngũ, thử sở dĩ thành biến hóa nhi hành quỷ thần dã.","Trời một, đất hai; trời ba, đất bốn; trời năm, đất sáu; trời bảy, đất tám; trời chín, đất mười. Số trời có năm, số đất có năm; năm ngôi tương đắc mà mỗi cặp có chỗ hợp. Số trời cộng lại là hai mươi lăm, số đất là ba mươi; tổng số trời đất là năm mươi lăm. Đó là cái làm nên biến hóa và vận hành quỷ thần."],["易曰公用射隼于高墉之上獲之无不利子曰隼者禽也弓矢者器也射之者人也君子藏器於身待時而動何不利之有動而不括是以出而有獲語成器而動者也","Dịch viết: \"Công dụng xạ chuẩn vu cao dung chi thượng, hoạch chi, vô bất lợi.\" Tử viết: \"Chuẩn giả, cầm dã; cung thỉ giả, khí dã. Xạ chi giả, nhân dã. Quân tử tàng khí ư thân, đãi thời nhi động, hà bất lợi chi hữu. Động nhi bất quát, thị dĩ xuất nhi hữu hoạch, ngữ thành khí nhi động giả dã.\"","Dịch nói: \"Bậc công bắn chim cắt trên tường thành cao, bắn được, không gì không lợi.\" (hào Thượng lục quẻ Giải). Khổng Tử nói: \"Chim cắt là con mồi; cung tên là khí cụ; người bắn là con người. Người quân tử cất giữ khí cụ (tài năng) nơi mình, đợi thời mà động, thì có gì không lợi! Động mà không vướng mắc, cho nên ra tay là có thu hoạch; ý nói chuẩn bị xong khí cụ rồi mới động.\""],["是故蓍之德圓而神卦之德方以知六爻之義易以貢聖人以此洗心退藏於密吉凶與民同患神以知來知以藏往其孰能與此哉古之聦明叡知神武而不殺者夫","Thị cố thi chi đức viên nhi thần, quái chi đức phương dĩ trí, lục hào chi nghĩa dịch dĩ cống; thánh nhân dĩ thử tẩy tâm, thoái tàng ư mật, cát hung dữ dân đồng hoạn, thần dĩ tri lai, trí dĩ tàng vãng, kỳ thục năng dự thử tai? Cổ chi thông minh duệ trí thần vũ nhi bất sát giả phù!","Cho nên đức của cỏ thi tròn mà thần diệu, đức của quẻ vuông mà sáng suốt, nghĩa của sáu hào biến đổi để bày ra cho người biết. Thánh nhân lấy đó mà rửa sạch lòng, lui về giữ mình nơi kín đáo; cùng lo với dân về cát hung; nhờ thần mà biết việc sẽ tới, nhờ trí mà cất giữ việc đã qua. Ai làm được như thế? Hẳn là bậc thông minh, sáng suốt, thần vũ mà không giết chóc thời xưa chăng!"],["乾元者始而亨者也利貞者性情也乾始能以美利利天下不言所利大矣哉大哉乾元剛健中正純粹精也六爻發揮旁通情也時乘六龍以御天也雲行雨施天下平也","Càn nguyên giả, thủy nhi hanh giả dã. Lợi trinh giả, tính tình dã. Càn thủy năng dĩ mỹ lợi lợi thiên hạ, bất ngôn sở lợi, đại hĩ tai! Đại tai Càn nguyên, cương kiện trung chính, thuần túy tinh dã. Lục hào phát huy, bàng thông tình dã. Thời thừa lục long, dĩ ngự thiên dã. Vân hành vũ thi, thiên hạ bình dã.","Càn nguyên là khởi đầu mà hanh thông. Lợi trinh là tính tình (của Càn). Càn mới khởi đầu đã đem cái lợi tốt đẹp mà làm lợi cho thiên hạ, lại không nói mình làm lợi gì – lớn thay! Lớn thay Càn nguyên: cứng mạnh, trung chính, thuần túy, tinh khiết. Sáu hào phát huy, thông suốt mọi tình. Theo thời cưỡi sáu rồng mà điều khiển trời; mây bay mưa rải, thiên hạ yên bình."],["乾道成男坤道成女乾知大始坤作成物乾以易知坤以簡能易則易知簡則易從易知則有親易從則有功有親則可久有功則可大可久則賢人之德可大則賢人之業","Càn đạo thành nam, Khôn đạo thành nữ; Càn tri đại thủy, Khôn tác thành vật; Càn dĩ dị tri, Khôn dĩ giản năng; dị tắc dị tri, giản tắc dị tòng; dị tri tắc hữu thân, dị tòng tắc hữu công; hữu thân tắc khả cửu, hữu công tắc khả đại; khả cửu tắc hiền nhân chi đức, khả đại tắc hiền nhân chi nghiệp.","Đạo Càn thành giống đực, đạo Khôn thành giống cái. Càn chủ việc khởi đầu lớn, Khôn làm thành muôn vật. Càn lấy sự dễ dàng mà chủ trì, Khôn lấy sự giản dị mà làm được việc. Dễ thì dễ biết, giản thì dễ theo. Dễ biết thì có người thân, dễ theo thì có công. Có người thân thì lâu dài được, có công thì lớn được. Lâu dài được là đức của người hiền, lớn được là sự nghiệp của người hiền."],["易之為書也廣大悉備有天道焉有人道焉有地道焉兼三材而兩之故六六者非它也三材之道也道有變動故曰爻爻有等故曰物物相雜故曰文文不當故吉凶生焉","Dịch chi vi thư dã, quảng đại tất bị: hữu thiên đạo yên, hữu nhân đạo yên, hữu địa đạo yên, kiêm tam tài nhi lưỡng chi, cố lục. Lục giả, phi tha dã, tam tài chi đạo dã. Đạo hữu biến động, cố viết hào; hào hữu đẳng, cố viết vật; vật tương tạp, cố viết văn; văn bất đáng, cố cát hung sinh yên.","Dịch là sách rộng lớn, đầy đủ: có đạo trời, có đạo người, có đạo đất; gồm ba ngôi (tam tài) mà nhân đôi, nên có sáu (hào). Sáu ấy không gì khác, là đạo của tam tài. Đạo có biến động nên gọi là hào; hào có thứ bậc nên gọi là vật; vật xen nhau nên gọi là văn; văn không xứng đáng nên cát hung sinh ra."],["震一索而得男故謂之長男巽一索而得女故謂之長女坎再索而得男故謂之中男離再索而得女故謂之中女艮三索而得男故謂之少男兌三索而得女故謂之少女","Chấn nhất sách nhi đắc nam, cố vị chi trưởng nam; Tốn nhất sách nhi đắc nữ, cố vị chi trưởng nữ; Khảm tái sách nhi đắc nam, cố vị chi trung nam; Ly tái sách nhi đắc nữ, cố vị chi trung nữ; Cấn tam sách nhi đắc nam, cố vị chi thiếu nam; Đoài tam sách nhi đắc nữ, cố vị chi thiếu nữ.","Chấn là lần cầu thứ nhất mà được con trai, nên gọi là trai trưởng; Tốn là lần cầu thứ nhất mà được con gái, nên gọi là gái trưởng. Khảm cầu lần thứ hai được trai, gọi là trai giữa; Ly cầu lần thứ hai được gái, gọi là gái giữa. Cấn cầu lần thứ ba được trai, gọi là trai út; Đoài cầu lần thứ ba được gái, gọi là gái út."],["二與四同功而異位其善不同二多譽四多懼近也柔之為道不利近者其要無咎其用柔中也三與五同功而異位其遇不同三多凶五多功貴賤之等也其柔危其剛勝邪","Nhị dữ tứ đồng công nhi dị vị, kỳ thiện bất đồng: nhị đa dự, tứ đa cụ, cận dã. Nhu chi vi đạo, bất lợi cận giả, kỳ yếu vô cữu, kỳ dụng nhu trung dã. Tam dữ ngũ đồng công nhi dị vị, kỳ ngộ bất đồng: tam đa hung, ngũ đa công, quý tiện chi đẳng dã. Kỳ nhu nguy, kỳ cương thắng da?","Hào 2 và hào 4 cùng công dụng (đều là ngôi âm) mà khác vị trí, nên cái tốt không giống nhau: hào 2 nhiều lời khen, hào 4 nhiều lo sợ, vì ở gần (ngôi vua – hào 5). Đạo của âm nhu vốn không lợi khi ở xa (người trên); hào 2 cốt yếu không lỗi là vì dùng sự nhu thuận mà đắc trung. Hào 3 và hào 5 cùng công dụng (đều là ngôi dương) mà khác vị trí, nên cảnh ngộ không giống nhau: hào 3 nhiều hung, hào 5 nhiều công, là do thứ bậc sang hèn. Ở đó (ngôi dương) mà âm nhu thì nguy, dương cương thì thắng chăng?"],["小畜寡也履不處也需不進也訟不親也大過顛也姤遇也柔遇剛也漸女歸待男行也頤養正也既濟定也歸妹女之終也未濟男之窮也夬決也剛決柔也君子道長小人道消也","Tiểu Súc quả dã, Lý bất xử dã. Nhu bất tiến dã, Tụng bất thân dã. Đại Quá điên dã, Cấu ngộ dã, nhu ngộ cương dã. Tiệm nữ quy đãi nam hành dã, Di dưỡng chính dã, Ký Tế định dã. Quy Muội nữ chi chung dã, Vị Tế nam chi cùng dã. Quải quyết dã, cương quyết nhu dã. Quân tử đạo trưởng, tiểu nhân đạo tiêu dã.","Tiểu Súc là ít (sức chứa nhỏ), Lý là không ở yên. Nhu là chưa tiến, Tụng là không thân. Đại Quá là nghiêng đổ, Cấu là gặp, mềm gặp cứng. Tiệm là con gái về nhà chồng, chờ trai đi đón; Di là nuôi điều chính; Ký Tế là đã định. Quy Muội là chỗ kết thúc của con gái; Vị Tế là chỗ cùng của con trai. Quải là quyết, cứng quyết trừ mềm. Đạo quân tử lớn lên, đạo tiểu nhân tiêu đi."],["進必有所傷故受之以明夷夷者傷也傷於外者必反其家故受之以家人家道窮必乖故受之以睽睽者乖也乖必有難故受之以蹇蹇者難也物不可終難故受之以解解者緩也","Tiến tất hữu sở thương, cố thụ chi dĩ Minh Di; Di giả thương dã. Thương ư ngoại giả, tất phản kỳ gia, cố thụ chi dĩ Gia Nhân. Gia đạo cùng tất quai, cố thụ chi dĩ Khuê; Khuê giả quai dã. Quai tất hữu nạn, cố thụ chi dĩ Kiển; Kiển giả nạn dã. Vật bất khả chung nạn, cố thụ chi dĩ Giải; Giải giả hoãn dã.","Tiến thì ắt có chỗ bị thương, nên tiếp bằng Minh Di; Di là thương tổn. Bị thương ở ngoài thì ắt trở về nhà, nên tiếp bằng Gia Nhân. Đạo nhà đến cùng thì ắt chia lìa, nên tiếp bằng Khuê; Khuê là trái lìa. Trái lìa ắt có hoạn nạn, nên tiếp bằng Kiển; Kiển là nạn. Vật không thể mãi hoạn nạn, nên tiếp bằng Giải; Giải là thư giãn."],["夫乾天下之至健也德行恒易以知險夫坤天下之至順也德行恒簡以知阻能說諸心能研諸侯之慮定天下之吉凶成天下之亹亹者是故變化云為吉事有祥象事知器占事知來","Phù Càn, thiên hạ chi chí kiện dã; đức hạnh hằng dị dĩ tri hiểm. Phù Khôn, thiên hạ chi chí thuận dã; đức hạnh hằng giản dĩ tri trở. Năng duyệt chư tâm, năng nghiên chư hầu chi lự, định thiên hạ chi cát hung, thành thiên hạ chi vỉ vỉ giả. Thị cố biến hóa vân vi, cát sự hữu tường, tượng sự tri khí, chiêm sự tri lai.","Càn là cái mạnh mẽ nhất thiên hạ; đức hạnh luôn dễ dàng mà biết chỗ hiểm. Khôn là cái thuận nhất thiên hạ; đức hạnh luôn giản dị mà biết chỗ trở ngại. (Dịch) làm vui được lòng người, nghiên cứu được mối lo của các chư hầu, định được cát hung của thiên hạ, làm nên sự cần mẫn không ngừng của thiên hạ. Cho nên trong biến hóa và lời nói việc làm, việc lành có điềm báo; xem tượng của việc thì biết khí cụ, chiêm việc thì biết việc sắp tới."],["子曰顏氏之子其殆庶幾乎有不善未嘗不知知之未嘗復行也易曰不遠復无祇悔元吉天地絪縕萬物化醇男女構精萬物化生易曰三人行則損一人一人行則得其友言致一也","Tử viết: \"Nhan thị chi tử, kỳ đãi thứ cơ hồ! Hữu bất thiện, vị thường bất tri; tri chi, vị thường phục hành dã. Dịch viết: 'Bất viễn phục, vô kỳ hối, nguyên cát.' Thiên địa nhân uân, vạn vật hóa thuần; nam nữ cấu tinh, vạn vật hóa sinh. Dịch viết: 'Tam nhân hành, tắc tổn nhất nhân; nhất nhân hành, tắc đắc kỳ hữu.' Ngôn trí nhất dã.\"","Khổng Tử nói: \"Người con họ Nhan (Nhan Hồi) có lẽ gần được (đạo) chăng! Có điều không tốt thì chưa từng không biết; biết rồi thì chưa từng tái phạm. Dịch nói: 'Đi chưa xa đã quay lại, không đến nỗi hối, rất tốt' (hào Sơ cửu quẻ Phục).\" Trời đất giao hòa nồng thắm, muôn vật hóa thành thuần hậu; đực cái giao tinh, muôn vật hóa sinh. Dịch nói: 'Ba người cùng đi thì bớt một người; một người đi thì được bạn' (hào Lục tam quẻ Tổn), ý nói đạt đến sự hợp nhất."],["古者包犧氏之王天下也仰則觀象於天俯則觀法於地觀鳥獸之文與地之宜近取諸身遠取諸物於是始作八卦以通神明之德以類萬物之情作結繩而為罔罟以佃以漁蓋取諸離","Cổ giả Bao Hy thị chi vương thiên hạ dã, ngưỡng tắc quan tượng ư thiên, phủ tắc quan pháp ư địa, quan điểu thú chi văn, dữ địa chi nghi, cận thủ chư thân, viễn thủ chư vật; ư thị thủy tác bát quái, dĩ thông thần minh chi đức, dĩ loại vạn vật chi tình. Tác kết thằng nhi vi võng cổ, dĩ điền dĩ ngư, cái thủ chư Ly.","Ngày xưa họ Bao Hy (Phục Hy) làm vua thiên hạ, ngẩng lên thì xem hình tượng ở trời, cúi xuống thì xem phép tắc ở đất, xem vằn vẻ của chim muông và những gì thích hợp với đất; gần thì lấy ở thân mình, xa thì lấy ở muôn vật; bèn bắt đầu làm ra bát quái, để thông với đức của thần minh, để xếp loại tình trạng của muôn vật. Thắt dây làm lưới để săn bắt, đánh cá, có lẽ lấy ý ở quẻ Ly."],["坎為水為溝瀆為隱伏為矯輮為弓輪其於人也為加憂為心病為耳痛為血卦為赤其於馬也為美脊為亟心為下首為薄蹄為曳其於輿也為多眚為通為月為盜其於木也為堅多心","Khảm vi thủy, vi câu độc, vi ẩn phục, vi kiểu nhu, vi cung luân. Kỳ ư nhân dã, vi gia ưu, vi tâm bệnh, vi nhĩ thống, vi huyết quái, vi xích. Kỳ ư mã dã, vi mỹ tích, vi cức tâm, vi hạ thủ, vi bạc đề, vi duệ. Kỳ ư dư dã, vi đa sảnh, vi thông, vi nguyệt, vi đạo. Kỳ ư mộc dã, vi kiên đa tâm.","Khảm là nước, là ngòi rãnh, là ẩn nấp, là uốn thẳng nắn cong, là cung và bánh xe. Với người thì là thêm lo, là bệnh tim, là đau tai, là quẻ máu, là màu đỏ. Với ngựa thì là sống lưng đẹp, tính nóng vội, cúi đầu, móng mỏng, đi lê kéo. Với xe thì là nhiều trục trặc, là thông suốt, là mặt trăng, là trộm cướp. Với cây thì là cây cứng nhiều lõi."],["物相遇而后聚故受之以萃萃者聚也聚而上者謂之升故受之以升升而不已必困故受之以困困乎上者必反下故受之以井井道不可不革故受之以革革物者莫若鼎故受之以鼎","Vật tương ngộ nhi hậu tụ, cố thụ chi dĩ Tụy; Tụy giả tụ dã. Tụ nhi thượng giả, vị chi thăng, cố thụ chi dĩ Thăng. Thăng nhi bất dĩ, tất khốn, cố thụ chi dĩ Khốn. Khốn hồ thượng giả, tất phản hạ, cố thụ chi dĩ Tỉnh. Tỉnh đạo bất khả bất cách, cố thụ chi dĩ Cách. Cách vật giả mạc nhược đỉnh, cố thụ chi dĩ Đỉnh.","Vật gặp nhau rồi mới tụ lại, nên tiếp bằng Tụy; Tụy là tụ. Tụ mà đi lên thì gọi là thăng, nên tiếp bằng Thăng. Lên mãi không thôi thì ắt khốn, nên tiếp bằng Khốn. Khốn ở trên thì ắt quay xuống dưới, nên tiếp bằng Tỉnh (giếng). Đạo giếng không thể không đổi mới, nên tiếp bằng Cách. Làm đổi mới vật không gì bằng cái vạc, nên tiếp bằng Đỉnh."],["說而后散之故受之以渙渙者離也物不可以終離故受之以節節而信之故受之以中孚有其信者必行之故受之以小過有過物者必濟故受之既濟物不可窮也故受之以未濟終焉","Duyệt nhi hậu tán chi, cố thụ chi dĩ Hoán; Hoán giả ly dã. Vật bất khả dĩ chung ly, cố thụ chi dĩ Tiết. Tiết nhi tín chi, cố thụ chi dĩ Trung Phu. Hữu kỳ tín giả, tất hành chi, cố thụ chi dĩ Tiểu Quá. Hữu quá vật giả, tất tế, cố thụ chi Ký Tế. Vật bất khả cùng dã, cố thụ chi dĩ Vị Tế; chung yên.","Vui rồi sau thì tan ra, nên tiếp bằng Hoán; Hoán là lìa tan. Vật không thể lìa tan mãi, nên tiếp bằng Tiết. Có chừng mực rồi người mới tin, nên tiếp bằng Trung Phu. Có lòng tin thì ắt làm, nên tiếp bằng Tiểu Quá. Có tài vượt hơn vật thì ắt nên việc, nên tiếp bằng Ký Tế. Vật không thể cùng tận, nên tiếp bằng Vị Tế; hết vậy."],["與天地相似故不違知周乎萬物而道濟天下故不過旁行而不流樂天知命故不憂安土敦乎仁故能愛範圍天地之化而不過曲成萬物而不遺通乎晝夜之道而知故神无方而易无體","Dữ thiên địa tương tự, cố bất vi; trí chu hồ vạn vật, nhi đạo tế thiên hạ, cố bất quá; bàng hành nhi bất lưu, lạc thiên tri mệnh, cố bất ưu; an thổ đôn hồ nhân, cố năng ái; phạm vi thiên địa chi hóa nhi bất quá, khúc thành vạn vật nhi bất di, thông hồ trú dạ chi đạo nhi tri, cố thần vô phương nhi Dịch vô thể.","Giống với trời đất nên không trái; trí hiểu khắp muôn vật mà đạo cứu giúp thiên hạ, nên không sai lệch; đi khắp nơi mà không trôi theo (điều sai), vui với trời, biết mệnh, nên không lo; yên với chỗ đất mình ở mà dày lòng nhân, nên thương yêu được. Bao quát sự hóa sinh của trời đất mà không vượt quá, uốn theo mà làm thành muôn vật không bỏ sót, thông suốt đạo ngày đêm mà hiểu biết; cho nên cái thần diệu không có phương sở cố định, và Dịch không có hình thể cố định."],["子曰作易者其知盜乎易曰負且乘致寇至負也者小人之事也乘也者君子之器也小人而乘君子之器盜思奪之矣上慢下暴盜思伐之矣慢藏誨盜冶容誨淫易曰負且乘致寇至盜之招也","Tử viết: \"Tác Dịch giả, kỳ tri đạo hồ! Dịch viết: 'Phụ thả thừa, trí khấu chí.' Phụ dã giả, tiểu nhân chi sự dã. Thừa dã giả, quân tử chi khí dã. Tiểu nhân nhi thừa quân tử chi khí, đạo tư đoạt chi hĩ. Thượng mạn hạ bạo, đạo tư phạt chi hĩ. Mạn tàng hối đạo, dã dung hối dâm. Dịch viết: 'Phụ thả thừa, trí khấu chí.' Đạo chi chiêu dã.\"","Khổng Tử nói: \"Người làm ra Dịch hẳn hiểu rõ về trộm cướp chăng! Dịch nói: 'Vừa gánh đồ vừa ngồi xe, rước giặc tới.' (hào Lục tam quẻ Giải). Gánh vác là việc của người thường; xe là đồ dùng của người quân tử. Kẻ tầm thường mà ngồi xe của người quân tử thì kẻ cướp nghĩ đến chuyện cướp. Trên thì khinh nhờn, dưới thì tàn bạo, kẻ cướp nghĩ đến chuyện đánh. Cất giữ cẩu thả là dạy kẻ trộm, trang điểm lả lơi là dạy sự dâm. Dịch nói 'vừa gánh vừa ngồi xe, rước giặc tới', ấy là tự mời kẻ cướp.\""],["是故法象莫大乎天地變通莫大乎四時縣象著明莫大乎日月崇高莫大乎富貴備物致用立成器以為天下利莫大乎聖人探賾索隱鉤深致遠以定天下之吉凶成天下之亹亹者莫大乎蓍龜","Thị cố pháp tượng mạc đại hồ thiên địa; biến thông mạc đại hồ tứ thời; huyền tượng trứ minh mạc đại hồ nhật nguyệt; sùng cao mạc đại hồ phú quý; bị vật trí dụng, lập thành khí dĩ vi thiên hạ lợi, mạc đại hồ thánh nhân; thám trách sách ẩn, câu thâm trí viễn, dĩ định thiên hạ chi cát hung, thành thiên hạ chi vỉ vỉ giả, mạc đại hồ thi quy.","Cho nên khuôn mẫu không gì lớn bằng trời đất; biến thông không gì lớn bằng bốn mùa; treo hình tượng sáng rõ không gì lớn bằng mặt trời mặt trăng; cao quý không gì lớn bằng giàu sang; sắm đủ đồ vật để dùng, làm ra khí cụ đem lợi cho thiên hạ, không ai lớn bằng thánh nhân; dò chỗ rối rắm, tìm chỗ ẩn kín, móc lên chỗ sâu, vươn tới chỗ xa, để định cát hung của thiên hạ, làm nên sự cần mẫn không ngừng của thiên hạ, không gì lớn bằng cỏ thi và mai rùa."],["子曰君子安其身而後動易其心而後語定其交而後求君子脩此三者故全也危以動則民不與也懼以語則民不應也无交而求則民不與也莫之與則傷之者至矣易曰莫益之或擊之立心勿恒凶","Tử viết: \"Quân tử an kỳ thân nhi hậu động, dị kỳ tâm nhi hậu ngữ, định kỳ giao nhi hậu cầu. Quân tử tu thử tam giả, cố toàn dã. Nguy dĩ động, tắc dân bất dữ dã. Cụ dĩ ngữ, tắc dân bất ứng dã. Vô giao nhi cầu, tắc dân bất dữ dã. Mạc chi dữ, tắc thương chi giả chí hĩ. Dịch viết: 'Mạc ích chi, hoặc kích chi. Lập tâm vật hằng, hung.'\"","Khổng Tử nói: \"Người quân tử làm cho thân yên rồi mới hành động, làm cho lòng bình thản rồi mới nói, xác lập quan hệ rồi mới cầu xin. Người quân tử sửa được ba điều ấy nên được vẹn toàn. Đang nguy mà hành động thì dân không theo; sợ hãi mà nói thì dân không hưởng ứng; không có quan hệ mà cầu thì dân không cho. Không ai theo giúp thì kẻ làm hại sẽ đến. Dịch nói: 'Không ai giúp thêm, có kẻ đánh cho. Lập tâm không bền, hung' (hào Thượng cửu quẻ Ích).\""],["子曰知幾其神乎君子上交不諂下交不瀆其知幾乎幾者動之微吉之先見者也君子見幾而作不俟終日易曰介于石不終日貞吉介如石焉寧用終日斷可識矣君子知微知彰知柔知剛萬夫之望","Tử viết: \"Tri cơ kỳ thần hồ! Quân tử thượng giao bất siểm, hạ giao bất độc, kỳ tri cơ hồ! Cơ giả, động chi vi, cát chi tiên hiện giả dã. Quân tử kiến cơ nhi tác, bất sĩ chung nhật. Dịch viết: 'Giới vu thạch, bất chung nhật, trinh cát.' Giới như thạch yên, ninh dụng chung nhật, đoán khả thức hĩ. Quân tử tri vi tri chương, tri nhu tri cương, vạn phu chi vọng.\"","Khổng Tử nói: \"Biết được cơ thì thần diệu thay! Người quân tử giao với người trên không nịnh, giao với người dưới không nhờn, đó là biết cơ chăng! Cơ là cái nhỏ nhất của sự động, là cái báo trước của điều lành. Người quân tử thấy cơ thì hành động, không đợi hết ngày. Dịch nói: 'Vững như đá, không đợi hết ngày, giữ chính thì tốt' (hào Lục nhị quẻ Dự). Vững như đá thì cần gì đợi hết ngày, quyết đoán là biết được ngay. Người quân tử biết cái nhỏ, biết cái rõ, biết cái mềm, biết cái cứng, là chỗ muôn người trông vào.\""],["易有聖人之道四焉以言者尚其辭以動者尚其變以制器者尚其象以卜筮者尚其占是以君子將有為也將有行也問焉而以言其受命也如響无有遠近幽深遂知來物非天下之至精其孰能與於此","Dịch hữu thánh nhân chi đạo tứ yên: dĩ ngôn giả thượng kỳ từ, dĩ động giả thượng kỳ biến, dĩ chế khí giả thượng kỳ tượng, dĩ bốc phệ giả thượng kỳ chiêm. Thị dĩ quân tử tương hữu vi dã, tương hữu hành dã, vấn yên nhi dĩ ngôn, kỳ thụ mệnh dã như hưởng, vô hữu viễn cận u thâm, toại tri lai vật. Phi thiên hạ chi chí tinh, kỳ thục năng dự ư thử!","Dịch có bốn đạo của thánh nhân: dùng để nói năng thì chuộng lời của nó; dùng để hành động thì chuộng sự biến của nó; dùng để chế tạo đồ vật thì chuộng hình tượng của nó; dùng để bói toán thì chuộng lời chiêm của nó. Vì vậy người quân tử sắp làm việc gì, sắp đi đâu, đem lời ra hỏi Dịch; Dịch nhận lời hỏi mà đáp lại như tiếng vang, không kể xa gần sâu kín, bèn biết được việc sắp tới. Nếu không phải là cái tinh vi bậc nhất thiên hạ thì sao dự được vào việc này!"],["易之為書也原始要終以為質也六爻相雜唯其時物也其初難知其上易知本末也初辭擬之卒成之終若夫雜物撰德辨是與非則非其中爻不備噫亦要存亡吉凶則居可知矣知者觀其彖辭則思過半矣","Dịch chi vi thư dã, nguyên thủy yếu chung dĩ vi chất dã. Lục hào tương tạp, duy kỳ thời vật dã. Kỳ sơ nan tri, kỳ thượng dị tri, bản mạt dã. Sơ từ nghĩ chi, tốt thành chi chung. Nhược phù tạp vật soạn đức, biện thị dữ phi, tắc phi kỳ trung hào bất bị. Y, diệc yếu tồn vong cát hung, tắc cư khả tri hĩ. Trí giả quan kỳ thoán từ, tắc tư quá bán hĩ.","Dịch là sách lấy việc truy nguyên chỗ đầu, tổng kết chỗ cuối làm thực chất. Sáu hào xen nhau, chỉ là theo thời và vật. Hào đầu khó biết, hào trên dễ biết, vì là gốc và ngọn. Lời hào đầu phỏng định (mầm mống), đến cuối thì thành kết cục. Còn như xen tạp các vật, bày ra các đức, phân biệt đúng sai, thì không có các hào giữa thì không đủ. Ôi! Muốn biết còn mất cát hung thì cứ ngồi yên cũng biết được. Người trí xem lời Thoán thì đã hiểu quá nửa."],["易之為書也不可遠為道也屢遷變動不居周流六虛上下无常剛柔相易不可為典要唯變所適其出入以度外內使知懼又明於憂患與故无有師保如臨父母初率其辭而揆其方既有典常苟非其人道不虛行","Dịch chi vi thư dã bất khả viễn, vi đạo dã lũ thiên; biến động bất cư, chu lưu lục hư, thượng hạ vô thường, cương nhu tương dịch, bất khả vi điển yếu, duy biến sở thích. Kỳ xuất nhập dĩ độ, ngoại nội sử tri cụ. Hựu minh ư ưu hoạn dữ cố, vô hữu sư bảo, như lâm phụ mẫu. Sơ suất kỳ từ nhi quỹ kỳ phương, ký hữu điển thường, cẩu phi kỳ nhân, đạo bất hư hành.","Dịch là sách không thể xa rời; đạo của nó thường đổi dời; biến động không ngừng, xoay vần khắp sáu ngôi; lên xuống không thường, cương nhu đổi chỗ cho nhau; không thể lấy làm khuôn phép cố định, chỉ theo sự biến mà thích ứng. Ra vào đều có chừng mực, khiến trong ngoài đều biết sợ (cẩn trọng). Lại làm rõ nỗi lo âu và nguyên do của nó; dù không có thầy dạy, người giữ, mà như đứng trước cha mẹ. Ban đầu theo lời mà đoán định phương hướng, thì thấy có phép thường; nhưng nếu không đúng người thì đạo không tự nhiên mà thực hiện được."],["九三曰君子終日乾乾夕惕若厲无咎何謂也子曰君子進德脩業忠信所以進德也脩辭立其誠所以居業也知至至之可與言幾也知終終之可與存義也是故居上位而不驕在下位而不憂故乾乾因其時而惕雖危无咎矣","Cửu tam viết: \"Quân tử chung nhật càn càn, tịch dịch nhược, lệ, vô cữu.\" Hà vị dã? Tử viết: \"Quân tử tiến đức tu nghiệp. Trung tín, sở dĩ tiến đức dã; tu từ lập kỳ thành, sở dĩ cư nghiệp dã. Tri chí chí chi, khả dữ ngôn cơ dã. Tri chung chung chi, khả dữ tồn nghĩa dã. Thị cố cư thượng vị nhi bất kiêu, tại hạ vị nhi bất ưu, cố càn càn nhân kỳ thời nhi dịch, tuy nguy vô cữu hĩ.\"","Hào Cửu tam nói: \"Quân tử suốt ngày hăng hái, tối vẫn lo sợ; nguy mà không lỗi.\" Nghĩa là gì? Khổng Tử nói: \"Quân tử tiến đức và sửa nghiệp. Trung tín là để tiến đức; sửa lời nói, lập lòng thành là để giữ nghiệp. Biết chỗ cần đến mà đến, thì có thể cùng bàn về cơ (dấu hiệu nhỏ); biết chỗ cần dừng mà dừng, thì có thể cùng giữ nghĩa. Cho nên ở trên không kiêu, ở dưới không lo; hăng hái theo thời mà dè chừng, nên tuy nguy mà không lỗi.\""],["天地設位聖人成能人謀鬼謀百姓與能八卦以象告爻彖以情言剛柔雜居而吉凶可見矣變動以利言吉凶以情遷是故愛惡相攻而吉凶生遠近相取而悔吝生情偽相感而利害生凡易之情近而不相得則凶或害之悔且吝","Thiên địa thiết vị, thánh nhân thành năng; nhân mưu quỷ mưu, bách tính dự năng. Bát quái dĩ tượng cáo, hào thoán dĩ tình ngôn, cương nhu tạp cư, nhi cát hung khả kiến hĩ. Biến động dĩ lợi ngôn, cát hung dĩ tình thiên. Thị cố ái ố tương công nhi cát hung sinh, viễn cận tương thủ nhi hối lận sinh, tình ngụy tương cảm nhi lợi hại sinh. Phàm Dịch chi tình, cận nhi bất tương đắc, tắc hung hoặc hại chi, hối thả lận.","Trời đất đặt ngôi, thánh nhân làm thành công năng; người mưu tính, quỷ thần mưu tính, trăm họ đều được dự phần. Bát quái báo bằng hình tượng; lời hào, lời thoán nói bằng tình trạng; cương nhu ở xen nhau mà cát hung có thể thấy được. Biến động là nói theo cái lợi; cát hung thay đổi theo tình trạng. Cho nên yêu ghét công kích nhau mà cát hung sinh; xa gần lấy nhau mà hối lận sinh; thật giả cảm nhau mà lợi hại sinh. Phàm tình của Dịch: gần nhau mà không hợp nhau thì hung, hoặc bị hại, hối và lận."],["上古穴居而野處後世聖人易之以宮室上棟下宇以待風雨蓋取諸大壯古之葬者厚衣之以薪葬之中野不封不樹喪期无數後世聖人易之以棺槨蓋取諸大過上古結繩而治後世聖人易之以書契百官以治萬民以察蓋取諸夬","Thượng cổ huyệt cư nhi dã xử, hậu thế thánh nhân dịch chi dĩ cung thất, thượng đống hạ vũ, dĩ đãi phong vũ, cái thủ chư Đại Tráng. Cổ chi táng giả, hậu y chi dĩ tân, táng chi trung dã, bất phong bất thụ, tang kỳ vô số, hậu thế thánh nhân dịch chi dĩ quan quách, cái thủ chư Đại Quá. Thượng cổ kết thằng nhi trị, hậu thế thánh nhân dịch chi dĩ thư khế, bách quan dĩ trị, vạn dân dĩ sát, cái thủ chư Quải.","Thời thượng cổ ở hang, sống ngoài đồng; thánh nhân đời sau thay bằng nhà cửa, trên có xà dưới có mái, để chống gió mưa, có lẽ lấy ý ở quẻ Đại Tráng. Người xưa chôn người chết, bọc dày bằng củi, chôn giữa đồng, không đắp mộ không trồng cây, thời gian tang không định; thánh nhân đời sau thay bằng quan quách, có lẽ lấy ý ở quẻ Đại Quá. Thời thượng cổ thắt nút dây mà cai trị; thánh nhân đời sau thay bằng chữ viết và khế ước, trăm quan nhờ đó mà làm việc, muôn dân nhờ đó mà xét rõ, có lẽ lấy ý ở quẻ Quải."],["聖人有以見天下之賾而擬諸其形容象其物宜是故謂之象聖人有以見天下之動而觀其會通以行其典禮繫辭焉以斷其吉凶是故謂之爻言天下之至賾而不可惡也言天下之至動而不可亂也擬之而後言議之而後動擬議以成其變化","Thánh nhân hữu dĩ kiến thiên hạ chi trách, nhi nghĩ chư kỳ hình dung, tượng kỳ vật nghi, thị cố vị chi tượng. Thánh nhân hữu dĩ kiến thiên hạ chi động, nhi quan kỳ hội thông, dĩ hành kỳ điển lễ, hệ từ yên dĩ đoán kỳ cát hung, thị cố vị chi hào. Ngôn thiên hạ chi chí trách nhi bất khả ố dã, ngôn thiên hạ chi chí động nhi bất khả loạn dã. Nghĩ chi nhi hậu ngôn, nghị chi nhi hậu động, nghĩ nghị dĩ thành kỳ biến hóa.","Thánh nhân thấy được chỗ sâu kín rối rắm của thiên hạ, bèn phỏng theo hình dáng, tượng trưng cho cái thích hợp của từng vật, nên gọi là tượng. Thánh nhân thấy được sự chuyển động của thiên hạ, xem chỗ hội tụ và thông suốt của nó để thi hành phép tắc, rồi buộc lời vào để đoán cát hung, nên gọi là hào. Nói đến chỗ phức tạp nhất của thiên hạ mà không thể chán ghét; nói đến chỗ biến động nhất của thiên hạ mà không thể rối loạn. Phỏng xét rồi mới nói, bàn kỹ rồi mới làm; nhờ phỏng xét và bàn bạc mà thành được sự biến hóa."],["須要先念渾天甲子六親歌占出卦來會裝五行六親再學變動卦中必有動爻動則必變卽知動變然後再看用神元神忌神知此者卽如入周易之門也再看四時旺相章五行相生相克章五行相沖相合章旬空月破生旺墓絕章又如進周易之堂也","tu yếu tiên niệm hồn thiên giáp tử lục thân ca chiêm xuất quái lai hội 裝 ngũ hành lục thân tái học biến động quái trung tất hữu động hào động tắc tất biến 卽 tri động biến nhiên hậu tái khán dụng thần nguyên thần kỵ thần tri thử giả 卽 như nhập chu dịch chi môn dã tái khán tứ thời 旺 tương chương ngũ hành tương sinh tương khắc chương ngũ hành tương xung tương hợp chương tuần không nguyệt phá sinh 旺 mộ tuyệt chương hựu như tiến chu dịch chi đường dã","trước hết thuộc"],["子曰小人不恥不仁不畏不義不見利不勸不威不懲小懲而大誡此小人之福也易曰履校滅趾无咎此之謂也善不積不足以成名惡不積不足以滅身小人以小善為无益而弗為也以小惡為无傷而弗去也故惡積而不可揜罪大而不可解易曰何校滅耳凶","Tử viết: \"Tiểu nhân bất sỉ bất nhân, bất úy bất nghĩa, bất kiến lợi bất khuyến, bất uy bất trừng, tiểu trừng nhi đại giới, thử tiểu nhân chi phúc dã. Dịch viết: 'Lý giảo diệt chỉ, vô cữu.' Thử chi vị dã. Thiện bất tích bất túc dĩ thành danh, ác bất tích bất túc dĩ diệt thân, tiểu nhân dĩ tiểu thiện vi vô ích nhi phất vi dã, dĩ tiểu ác vi vô thương nhi phất khứ dã; cố ác tích nhi bất khả yểm, tội đại nhi bất khả giải. Dịch viết: 'Hạ giảo diệt nhĩ, hung.'\"","Khổng Tử nói: \"Kẻ tiểu nhân không biết xấu hổ vì bất nhân, không sợ điều bất nghĩa, không thấy lợi thì không gắng, không bị uy hiếp thì không chừa; phạt nhỏ mà răn lớn, đó là phúc của kẻ tiểu nhân. Dịch nói: 'Chân mang cùm, mất ngón chân, không lỗi' (hào Sơ cửu Phệ Hạp), là nói điều này. Điều thiện không tích lại thì không đủ để nên danh; điều ác không tích lại thì không đủ để hại thân. Kẻ tiểu nhân cho điều thiện nhỏ là vô ích nên không làm, cho điều ác nhỏ là không hại nên không bỏ; vì thế ác tích lại mà không che giấu được, tội lớn mà không gỡ được. Dịch nói: 'Cổ đeo gông, mất tai, hung' (hào Thượng cửu Phệ Hạp).\""],["鳴鶴在陰其子和之我有好爵吾與爾靡之子曰君子居其室出其言善則千里之外應之況其邇者乎居其室出其言不善則千里之外違之況其邇者乎言出乎身加乎民行發乎邇見乎遠言行君子之樞機樞機之發榮辱之主也言行君子之所以動天地也可不慎乎","\"Minh hạc tại âm, kỳ tử họa chi. Ngã hữu hảo tước, ngô dữ nhĩ mị chi.\" Tử viết: \"Quân tử cư kỳ thất, xuất kỳ ngôn thiện, tắc thiên lý chi ngoại ứng chi, huống kỳ nhĩ giả hồ! Cư kỳ thất, xuất kỳ ngôn bất thiện, tắc thiên lý chi ngoại vi chi, huống kỳ nhĩ giả hồ! Ngôn xuất hồ thân gia hồ dân; hành phát hồ nhĩ hiện hồ viễn. Ngôn hành, quân tử chi xu cơ; xu cơ chi phát, vinh nhục chi chủ dã. Ngôn hành, quân tử chi sở dĩ động thiên địa dã, khả bất thận hồ!\"","\"Hạc kêu trong bóng râm, con nó họa theo. Ta có chén rượu ngon, cùng ngươi chia nhau.\" (hào Cửu nhị quẻ Trung Phu). Khổng Tử nói: \"Người quân tử ở trong nhà, nói ra lời tốt thì ngoài nghìn dặm cũng hưởng ứng, huống là người ở gần! Ở trong nhà nói ra lời không tốt thì ngoài nghìn dặm cũng chống lại, huống là người ở gần! Lời nói từ thân mình mà tác động tới dân; việc làm phát ra từ chỗ gần mà hiện ra ở chỗ xa. Lời nói và việc làm là then chốt của người quân tử; then chốt ấy phát ra thì làm chủ cho vinh hay nhục. Lời nói và việc làm là cái để người quân tử làm động cả trời đất, há không thận trọng sao!\""],["乾之策二百一十有六坤之策百四十有四凡三百有六十當期之日二篇之策萬有一千五百二十當萬物之數也是故四營而成易十有八變而成卦八卦而小成引而伸之觸類而長之天下之能事畢矣顯道神德行是故可與酬酢可與祐神矣子曰知變化之道者其知神之所為乎","Càn chi sách, nhị bách nhất thập hữu lục, Khôn chi sách, bách tứ thập hữu tứ, phàm tam bách hữu lục thập, đương kỳ chi nhật. Nhị thiên chi sách, vạn hữu nhất thiên ngũ bách nhị thập, đương vạn vật chi số dã. Thị cố tứ doanh nhi thành Dịch, thập hữu bát biến nhi thành quái, bát quái nhi tiểu thành; dẫn nhi thân chi, xúc loại nhi trưởng chi, thiên hạ chi năng sự tất hĩ. Hiển đạo thần đức hạnh, thị cố khả dữ thù tạc, khả dữ hựu thần hĩ. Tử viết: \"Tri biến hóa chi đạo giả, kỳ tri thần chi sở vi hồ!\"","Số que của quẻ Càn là 216, của quẻ Khôn là 144, cộng lại 360, ứng với số ngày trong một năm. Số que của hai thiên (Thượng kinh, Hạ kinh) là 11.520, ứng với số của muôn vật. Cho nên bốn bước thao tác thành một lần biến, mười tám lần biến thành một quẻ; tám quái là bước tiểu thành; kéo dài ra, theo loại mà mở rộng, thì mọi việc có thể làm trong thiên hạ đều gồm đủ. Làm sáng tỏ đạo, làm cho đức hạnh thành thần diệu, nên có thể dùng để ứng đối với việc đời, có thể giúp vào việc của thần. Khổng Tử nói: \"Người biết đạo biến hóa hẳn biết được việc làm của thần chăng!\""],["是故夫象聖人有以見天下之賾而擬諸其形容象其物宜是故謂之象聖人有以見天下之動而觀其會通以行其典禮繫辭焉以斷其吉凶是故謂之爻極天下之賾者存乎卦鼓天下之動者存乎辭化而裁之存乎變推而行之存乎通神而明之存乎其人默而成之不言而信存乎德行","Thị cố phù tượng, thánh nhân hữu dĩ kiến thiên hạ chi trách, nhi nghĩ chư kỳ hình dung, tượng kỳ vật nghi, thị cố vị chi tượng. Thánh nhân hữu dĩ kiến thiên hạ chi động, nhi quan kỳ hội thông, dĩ hành kỳ điển lễ, hệ từ yên dĩ đoán kỳ cát hung, thị cố vị chi hào. Cực thiên hạ chi trách giả tồn hồ quái; cổ thiên hạ chi động giả tồn hồ từ; hóa nhi tài chi tồn hồ biến; suy nhi hành chi tồn hồ thông; thần nhi minh chi, tồn hồ kỳ nhân; mặc nhi thành chi, bất ngôn nhi tín, tồn hồ đức hạnh.","Cho nên tượng là: thánh nhân thấy được chỗ rối rắm của thiên hạ, bèn phỏng theo hình dáng, tượng trưng cái thích hợp của vật, nên gọi là tượng. Thánh nhân thấy được sự chuyển động của thiên hạ, xem chỗ hội thông để thi hành phép tắc, buộc lời vào để đoán cát hung, nên gọi là hào. Đi tới cùng chỗ rối rắm của thiên hạ là ở quẻ; cổ động sự vận động của thiên hạ là ở lời; theo biến hóa mà cắt đặt là ở biến; đẩy ra mà thực hành là ở thông; thần diệu mà sáng tỏ là ở con người; lặng lẽ mà thành, không nói mà được tin, là ở đức hạnh."],["易曰憧憧往來朋從爾思子曰天下何思何慮天下同歸而殊途一致而百慮天下何思何慮日往則月來月往則日來日月相推而明生焉寒往則暑來暑往則寒來寒暑相推而歲成焉往者屈也來者信也屈信相感而利生焉尺蠖之屈以求信也龍蛇之蟄以存身也精義入神以致用也利用安身以崇德也過此以往未之或知也窮神知化德之盛也","Dịch viết: \"Xung xung vãng lai, bằng tòng nhĩ tư.\" Tử viết: \"Thiên hạ hà tư hà lự! Thiên hạ đồng quy nhi thù đồ, nhất trí nhi bách lự, thiên hạ hà tư hà lự! Nhật vãng tắc nguyệt lai, nguyệt vãng tắc nhật lai, nhật nguyệt tương suy nhi minh sinh yên. Hàn vãng tắc thử lai, thử vãng tắc hàn lai, hàn thử tương suy nhi tuế thành yên. Vãng giả, khuất dã; lai giả, thân dã. Khuất thân tương cảm nhi lợi sinh yên. Xích hoạch chi khuất, dĩ cầu thân dã. Long xà chi trập, dĩ tồn thân dã. Tinh nghĩa nhập thần, dĩ trí dụng dã. Lợi dụng an thân, dĩ sùng đức dã. Quá thử dĩ vãng, vị chi hoặc tri dã. Cùng thần tri hóa, đức chi thịnh dã.\"","Dịch nói: \"Bồn chồn qua lại, bạn bè theo ý nghĩ của ngươi.\" (hào Cửu tứ quẻ Hàm). Khổng Tử nói: \"Thiên hạ cần gì nghĩ, cần gì lo! Thiên hạ cùng về một chỗ mà đường đi khác nhau, cùng một đích mà trăm mối lo, thiên hạ cần gì nghĩ, cần gì lo! Mặt trời đi thì mặt trăng lại, mặt trăng đi thì mặt trời lại; mặt trời mặt trăng đẩy nhau mà ánh sáng sinh ra. Lạnh đi thì nóng lại, nóng đi thì lạnh lại; lạnh nóng đẩy nhau mà thành năm. Đi là co lại; đến là duỗi ra. Co duỗi cảm nhau mà cái lợi sinh ra. Con sâu đo co lại là để duỗi ra; rồng rắn nằm im (qua đông) là để giữ thân. Tinh thông nghĩa lý đến chỗ thần diệu là để đem ra dùng; dùng cho lợi mà yên thân là để nâng cao đức. Vượt quá chỗ đó thì chưa ai biết được. Hiểu thấu chỗ thần diệu, biết lẽ biến hóa, đó là đức thịnh.\""]];
